window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-07-15"]={"date":"2026-07-15","dateKR":"2026년 7월 15일","dateEN":"15 July 2026","total":259,"sections":[{"code":"TOP","type":"news","kTitle":"Section 1. 주요 뉴스","eTitle":"Section 1. Top News","items":[{"code":"TOP","title":"원유 탱커 신조 발주 사상 최고치 경신","src":"Splash247","date":"2026-07-13","kSum":"2026년 원유 탱커 신조 계약이 234척, 6,000만 DWT로 사상 최대를 기록했다. Veson 집계상 상반기 VLCC 계약만 183척으로 전년 동기 18척 대비 폭증했다.","eSum":"Crude tanker newbuilding contracting has hit a record 60m dwt across 234 ships in 2026, with 183 VLCC contracts in H1 alone versus 18 a year earlier.","kImp":"높은 운임과 노후 선대 교체 수요가 겹치며 발주 사이클이 과열 국면에 진입, 2028~29년 인도 물량 과잉 리스크가 커지고 있다.","eImp":"High freight rates and an ageing fleet are driving an overheated ordering cycle, raising oversupply risk for 2028-29 deliveries.","url":"https://splash247.com/crude-tanker-orders-hit-record-high/"},{"code":"TOP","title":"HMM, 22억 달러 규모 컨테이너선 발주 추진","src":"Splash247","date":"2026-07-14","kSum":"HMM이 국내 조선 빅2에 LNG 이중연료 14,000TEU급 컨테이너선 12척을 발주한 것으로 알려졌다. 척당 약 1억 8,250만 달러 수준이다.","eSum":"HMM is reported to have ordered 12 LNG dual-fuelled 14,000 teu containerships at Korean yards, at around $182.5m per unit.","kImp":"국적선사의 대규모 이중연료 선대 확충으로 IMO 넷제로 규제 대응과 한국 조선소 수주잔고 확보가 동시에 이뤄진다.","eImp":"A major dual-fuel fleet expansion positions the Korean carrier for IMO net-zero rules while filling domestic yard orderbooks.","url":"https://splash247.com/hmm-tied-to-2-2bn-boxship-orders/"},{"code":"TOP","title":"메가맥스 신조선 유휴화 — 선사, 화주 상대 협상력 반전 시도","src":"Splash247","date":"2026-07-10","kSum":"선사들이 신조 메가맥스 선박을 의도적으로 유휴 상태로 두며 공급을 조절, 화주와의 협상 구도를 되돌리려 하고 있다.","eSum":"Carriers are idling newly delivered megamax tonnage to manage capacity and turn the tables in negotiations with shippers.","kImp":"공급 조절이 구조적 전략으로 자리잡으면 계약운임 협상과 선복 확보 전략 전반이 바뀐다.","eImp":"If capacity management becomes structural, contract rate negotiations and space procurement strategies shift materially.","url":"https://splash247.com/megamax-newbuilds-idle-as-carriers-try-to-turn-the-tables-with-shippers/"},{"code":"TOP","title":"글로벌 컨테이너 스팟운임 9% 급등 — 태평양·아시아-유럽 동시 타이트","src":"gCaptain","date":"2026-07-10","kSum":"태평양 횡단과 아시아-유럽 항로가 동시에 타이트해지며 글로벌 컨테이너 스팟운임이 주간 기준 9% 급등했다.","eSum":"Global container spot rates jumped 9% week-on-week as transpacific and Asia-Europe trades tightened simultaneously.","kImp":"주요 동서항로 동시 강세는 4년 만의 고점 형성으로 이어지며 선사 실적 전망을 대폭 끌어올린다.","eImp":"Simultaneous strength on major east-west trades is pushing rates to four-year highs and lifting carrier earnings guidance.","url":"https://gcaptain.com/global-container-spot-rates-jump-9-as-transpacific-asia-europe-trades-tighten/"},{"code":"TOP","title":"브라질 첫 에탄올 추진 선박 출항 — 바이오연료 시험대","src":"gCaptain","date":"2026-07-14","kSum":"브라질산 에탄올로 운항하는 첫 컨테이너선 CMA CGM Iron이 산투스항을 출항해 스리랑카·싱가포르를 경유, 중국으로 향한다.","eSum":"The CMA CGM Iron, the first containership running on Brazilian-made ethanol, sailed from Santos bound for China via Sri Lanka and Singapore.","kImp":"메탄올·에탄올·중유 겸용 선박의 실증은 IMO 넷제로 체계 도입을 앞둔 대체연료 포트폴리오를 넓힌다.","eImp":"Proving a methanol/ethanol/fossil tri-fuel vessel broadens the alternative fuel portfolio ahead of the IMO net-zero framework.","url":"https://gcaptain.com/brazils-first-ethanol-powered-ship-sails-in-win-for-biofuels/"},{"code":"TOP","title":"7월 추가 인상 강행에 스팟운임 재차 급등","src":"The Loadstar","date":"2026-07-13","kSum":"선사들이 7월 중순 추가 운임인상(GRI)을 밀어붙이며 스팟운임이 다시 뛰었다. HMM은 15일부터 FEU당 3,000달러 성수기 할증료를 도입했다.","eSum":"Spot rates surged again as carriers pushed through fresh mid-July increases; HMM introduced a $3,000/40ft peak season surcharge from 15 July.","kImp":"성수기 할증료가 관철되면 3분기 선사 수익성이 크게 개선되지만 화주 부담과 반발도 커진다.","eImp":"If PSS levels hold, Q3 carrier profitability improves sharply, but shipper pushback intensifies.","url":"https://theloadstar.com/spot-rates-surge-again-as-carriers-push-through-fresh-july-hikes/"},{"code":"TOP","title":"아시아 수출항로, 선복 회복에도 운임 강세 지속","src":"Seatrade Maritime","date":"2026-07-10","kSum":"아시아-미서안 선복이 35만 TEU로 사상 최대인데도 스팟운임은 7월 3일 기준 FEU당 6,639달러로 전주 대비 14% 올랐다.","eSum":"Despite Asia-USWC capacity at an all-time high of 350,000 teu, spot rates rose 14% week-on-week to $6,639/feu by 3 July.","kImp":"선복 증가에도 운임이 오르는 것은 수요가 예상보다 강하다는 신호로, 수급 모델 재조정이 필요하다.","eImp":"Rates rising despite added capacity signals demand is stronger than modelled, forcing supply-demand reassessment.","url":"https://www.seatrade-maritime.com/containers/container-rates-defy-capacity-rebound-on-asia-export-trades"},{"code":"TOP","title":"2026 컨테이너 시황 전망 — 홍해 복귀 가능성","src":"Seatrade Maritime","date":"2026-07-09","kSum":"내년 이맘때면 홍해를 통과하는 선박 비중이 훨씬 커질 것이라는 전망이 나오지만, 여전히 불확실하고 되돌려질 여지가 크다는 평가다.","eSum":"Analysts expect a much larger share of vessels to transit the Red Sea within a year, though the outlook remains uncertain and reversible.","kImp":"홍해 복귀는 실질 선복을 크게 늘려 운임을 급락시킬 수 있는 최대 하방 변수다.","eImp":"A Red Sea return would release large effective capacity and is the single biggest downside risk to rates.","url":"https://www.seatrade-maritime.com/containers/container-shipping-market-outlook-for-2026-a-red-sea-return-"},{"code":"TOP","title":"SEA-LNG: LNG 벙커링 급증 — 대체연료 발주잔고의 90% 차지","src":"MarineLink","date":"2026-07-13","kSum":"주요 벙커링 허브의 LNG 공급량이 급증했다. 싱가포르는 1분기 48% 증가한 15만 톤, 로테르담·안트베르펜-브뤼헤는 합산 44% 증가했다.","eSum":"LNG bunkering volumes are surging: Singapore up 48% in Q1 to 150,000 tonnes, Rotterdam and Antwerp-Bruges up 44% combined; LNG-fuelled ships are ~90% of the alternative fuel orderbook.","kImp":"LNG가 사실상 과도기 표준 연료로 굳어지며 벙커링 인프라 투자와 선대 전략의 기준점이 되고 있다.","eImp":"LNG is consolidating as the de facto transition fuel, anchoring bunkering infrastructure investment and fleet strategy.","url":"https://www.marinelink.com/news/sealng-lng-bunkering-surging-539984"},{"code":"TOP","title":"메탄 탈탄소 경로 투자, 지정학 불확실성에도 지속 확대","src":"Hellenic Shipping News","date":"2026-07-10","kSum":"SEA-LNG 자료에 따르면 지정학적 혼란과 규제 불확실성에도 메탄 기반 탈탄소 경로 투자가 계속 늘고 있다. 주요 항만의 액화바이오메탄 판매는 6배 증가했다.","eSum":"SEA-LNG data shows investment in the methane decarbonisation pathway continues to grow despite geopolitical disruption and regulatory uncertainty, with liquefied biomethane sales up six-fold at major ports.","kImp":"바이오메탄·e-메탄 공급망이 확대되면 기존 LNG 선대가 규제 대응 자산으로 전환될 수 있다.","eImp":"A scaling bio-/e-methane supply chain could convert existing LNG tonnage into compliance-ready assets.","url":"https://www.hellenicshippingnews.com/data-shows-investments-in-the-methane-decarbonisation-pathway-continue-to-grow/"},{"code":"TOP","title":"IMO 넷제로 프레임워크 해설 — 12월 채택 앞두고 쟁점 정리","src":"Maritime Executive","date":"2026-07-11","kSum":"2025년 4월 승인된 IMO 넷제로 지침은 미국의 압박으로 채택이 올해 12월로 연기됐다. 온실가스 부과금과 연료 강도 기준의 실제 작동 방식이 쟁점이다.","eSum":"The IMO net-zero framework, approved in April 2025, had formal adoption pushed to December this year under US pressure; the mechanics of the GHG levy and fuel intensity standard remain contested.","kImp":"채택 여부와 세부 설계가 향후 10년 선대 투자·연료 선택의 최대 변수다.","eImp":"Adoption and design details are the single largest variable for fleet investment and fuel choice over the next decade.","url":"https://maritime-executive.com/index.php/editorials/understanding-the-imo-s-net-zero-framework"}]},{"code":"ACC","type":"accident","kTitle":"Section 2. 해양사고","eTitle":"Section 2. Accidents","items":[{"code":"ACC","title":"이란, 선박 충돌 후 승선원 23명 구조","src":"SAFETY4SEA","date":"2026-07-14","kSum":"7월 14일 반다르아바스 해사당국이 벌크선과 타 선박의 충돌 조난신호를 접수했다. 벌크선은 선체 중앙부에 큰 손상을 입고 침수됐으며 외국인 선원 23명 전원이 케슘섬으로 안전 대피했다.","eSum":"Maritime authorities in Bandar Abbas received a distress call on 14 July after a bulk carrier collided with another vessel, suffering major midships damage and flooding. All 23 foreign crew were evacuated safely to Qeshm Island.","kCause":"충돌 원인은 아직 규명되지 않았으며 조사가 진행 중이다. 호르무즈 해협 인근 고밀도 통항 해역의 상황인식 문제가 지목된다.","eCause":"Cause undetermined; an investigation is under way. Situational awareness in the congested waters near the Strait of Hormuz is a focus.","kLes":"고밀도·고긴장 해역에서는 견시 강화와 조기 회피 조치, 침수 대응 훈련이 생존의 관건이다.","eLes":"In congested, high-tension waters, enhanced lookout, early collision avoidance and flooding drills are decisive.","url":"https://safety4sea.com/iran-reportedly-rescues-23-crew-after-vessel-collision/"},{"code":"ACC","title":"NTSB 조사: 화물선 화재로 2명 사망","src":"SAFETY4SEA","date":"2026-07-07","kSum":"NTSB가 화물선 화재로 승선원 2명이 사망한 사고 조사 결과를 공개했다. 화재 확산과 대피 지연이 인명 피해로 이어졌다.","eSum":"The NTSB released its investigation into a fire aboard a cargo vessel that claimed two lives, with fire spread and delayed evacuation contributing to the fatalities.","kCause":"발화원 관리 미흡과 화재 감지·경보 지연, 방화구획 유지 실패가 복합 작용했다.","eCause":"A combination of poor ignition source control, delayed detection/alarm, and failure to maintain fire boundaries.","kLes":"화재 감지 시스템 정기 시험, 방화문·구획 무결성 유지, 신속한 대피 절차 훈련이 필요하다.","eLes":"Regular testing of detection systems, maintaining fire door and boundary integrity, and drilling rapid evacuation are essential.","url":"https://safety4sea.com/ntsb-investigation-fire-aboard-cargo-vessel-claims-two-lives/"},{"code":"ACC","title":"피격 벌크선 Mayuree Naree, 이란 케슘섬에 좌초","src":"gCaptain","date":"2026-07-13","kSum":"호르무즈 해협에서 미상 발사체에 피격돼 손상된 태국 벌크선 Mayuree Naree가 이란 케슘섬 인근에 좌초했다.","eSum":"The stricken Thai bulk carrier Mayuree Naree, damaged after being hit by an unidentified projectile in the Strait of Hormuz, ran aground on Iran's Qeshm Island.","kCause":"피격에 따른 선체 손상과 추진·조타 능력 상실이 좌초로 이어졌다.","eCause":"Hull damage from the strike and loss of propulsion/steering capability led to the grounding.","kLes":"손상 선박의 예인·피난처(Place of Refuge) 확보 계획을 사전에 수립해야 2차 사고를 막을 수 있다.","eLes":"Pre-planned towage and Place of Refuge arrangements for damaged ships are key to preventing secondary casualties.","url":"https://gcaptain.com/stricken-bulk-carrier-mayuree-naree-runs-aground-on-irans-qeshm-island/"},{"code":"ACC","title":"태국 화물선, 호르무즈 피격 수 주 만에 이란 앞바다 좌초 — 3명 실종","src":"Marine Insight","date":"2026-07-12","kSum":"호르무즈 해협에서 피격된 태국 국적 화물선이 수 주 만에 이란 앞바다에서 좌초했다. 20명이 구조됐으나 승선원 3명은 여전히 실종 상태다.","eSum":"A Thai-flagged cargo ship struck in the Strait of Hormuz ran aground off Iran weeks later; 20 crew were rescued but three remain missing.","kCause":"공격에 따른 구조 손상 누적과 예인 중 통제 상실.","eCause":"Cumulative structural damage from the attack and loss of control during towage.","kLes":"피격 손상 선박은 즉시 구조 강도 평가 후 예인 여부를 판단해야 하며, 실종자 수색 체계도 조기 가동해야 한다.","eLes":"Attack-damaged ships need immediate structural strength assessment before towage decisions, with SAR activated early.","url":"https://www.marineinsight.com/thai-cargo-ship-runs-aground-off-iran-weeks-after-being-struck-in-strait-of-hormuz-3-crew-still-missing/"},{"code":"ACC","title":"267명 탑승 한국 여객선 좌초 — 승무원 체포","src":"Marine Insight","date":"2026-07-10","kSum":"승객·승무원 267명을 태운 한국 여객선이 좌초해 승무원이 체포됐다. 당국은 항해 과실 여부를 조사 중이다.","eSum":"A South Korean ferry carrying 267 people ran aground and crew members were arrested, with authorities investigating navigational error.","kCause":"항로 이탈 및 당직 항해 과실 가능성이 제기되고 있다.","eCause":"Suspected off-track navigation and bridge watchkeeping failure.","kLes":"연안 여객선은 항로계획(Passage Plan) 준수와 브리지 리소스 관리(BRM)가 핵심이며, 야간·연안 항해 시 감시 강화가 요구된다.","eLes":"Coastal ferries depend on passage plan adherence and BRM; vigilance must increase for night and coastal transits.","url":"https://www.marineinsight.com/shipping-news/crew-arrested-after-south-korean-ferry-runs-aground-with-267-people-aboard/"},{"code":"ACC","title":"이탈리아 주요 항만서 여객선 대형 화재 — 항만 운영 차질","src":"Marine Insight","date":"2026-07-05","kSum":"이탈리아의 주요 해상 허브 중 한 곳에서 여객선 대형 화재가 발생해 항만 운영이 중단됐다. 승선 인원 85명 전원이 안전하게 대피했고 승객은 탑승하지 않은 상태였다.","eSum":"A major fire broke out aboard a ferry at one of Italy's busiest maritime hubs, disrupting port operations. All 85 aboard evacuated safely; no passengers were on board.","kCause":"정박 중 화재로, 발화원은 조사 중이며 차량갑판·기관구역 관련 가능성이 검토되고 있다.","eCause":"Fire while alongside; ignition source under investigation, with vehicle deck/machinery space origins being examined.","kLes":"정박 중에도 화재 당직과 고정식 소화설비 즉시 사용 가능 상태 유지가 필수다.","eLes":"Fire watches and immediate availability of fixed firefighting systems must be maintained even alongside.","url":"https://www.marineinsight.com/massive-fire-aboard-ferry-at-one-of-italys-busiest-maritime-hubs-disrupts-port-operations/"},{"code":"ACC","title":"컨테이너 화재로 머스크 선박 테네리페 긴급 기항","src":"Maritime Executive","date":"2026-07-08","kSum":"머스크 컨테이너선에서 컨테이너 화재가 발생해 테네리페로 긴급 회항했다.","eSum":"A container fire prompted a Maersk boxship to divert to Tenerife.","kCause":"위험물 컨테이너 자체 발열 또는 신고 누락(misdeclared cargo) 가능성이 주요 조사 대상이다.","eCause":"Self-heating dangerous goods or misdeclared cargo are the primary lines of inquiry.","kLes":"위험물 신고 검증과 적재 위치 관리, 갑판 화재 조기 감지 체계 강화가 필요하다.","eLes":"DG declaration verification, stowage position control and early deck fire detection need strengthening.","url":"https://maritime-executive.com/article/container-fire-prompts-maersk-boxship-to-divert-to-tenerife"},{"code":"ACC","title":"화물 페리 화재 후 와이트섬 앞 정박","src":"Maritime Executive","date":"2026-07-03","kSum":"포츠머스-저지 항로를 운항하던 122m급 화물 페리 Caesarea Trader에서 화재가 발생해 와이트섬 앞바다에 정박했다. 승무원 전원과 승객 1명은 무사했다.","eSum":"Fire broke out aboard the 400-foot freight ferry Caesarea Trader on the Portsmouth-Jersey route, forcing it to anchor off the Isle of Wight. All crew and one passenger were safe.","kCause":"차량갑판 또는 기관구역 발화 가능성. 로로선 특유의 개방 공간이 화재 확산에 취약하다.","eCause":"Likely vehicle deck or machinery space origin; ro-ro open spaces are inherently vulnerable to fire spread.","kLes":"로로선은 차량갑판 감시(CCTV·순찰)와 드렌처 시스템 준비 상태가 화재 통제의 관건이다.","eLes":"For ro-ros, vehicle deck monitoring (CCTV/patrols) and drencher readiness determine fire control outcomes.","url":"https://maritime-executive.com/article/freight-ferry-catches-fire-goes-to-anchor-off-isle-of-wight"},{"code":"ACC","title":"MAIB, 승객 사망으로 이어진 크루즈선 추진력 상실 사고 보고서 발간","src":"Baird Maritime","date":"2026-07-01","kSum":"영국 MAIB가 크루즈선 추진력 상실 사고 보고서를 발간했다. 선박 동요로 승객 1명이 사망했다.","eSum":"The UK MAIB published its report on a cruise ship propulsion loss incident that led to a passenger death.","kCause":"추진 시스템 고장으로 선박이 파도에 노출된 채 표류하며 급격한 횡동요가 발생했다.","eCause":"Propulsion failure left the vessel beam-on and drifting, producing severe rolling.","kLes":"추진 이중화 확보와 함께, 추진 상실 시 승객 착석·안전 조치 방송 절차를 즉시 발동해야 한다.","eLes":"Propulsion redundancy matters, but so does immediate activation of passenger be-seated announcements on power loss.","url":"https://www.bairdmaritime.com/security/incidents/accidents/maib-publishes-report-on-cruise-ship-propulsion-loss-that-led-to-passenger-death"},{"code":"ACC","title":"브리지팀 붕괴: 컨테이너선-범선 충돌 부른 소통 실패","src":"gCaptain","date":"2026-07-02","kSum":"조사 결과 컨테이너선과 대형 범선의 충돌은 브리지팀 내부 소통 실패에서 비롯된 것으로 드러났다.","eSum":"An investigation found that bridge team communication failures led to a containership's collision with a tall ship.","kCause":"당직사관 간 의도 공유 부재, 도선사-브리지팀 정보 교환 미흡, 폐쇄 루프 통신 미이행.","eCause":"Absence of shared intent between watch officers, poor pilot-bridge team information exchange, and no closed-loop communication.","kLes":"BRM 훈련과 도선사 정보교환(Master-Pilot Exchange) 실질 이행, 폐쇄 루프 복명복창이 필수다.","eLes":"Effective BRM training, a substantive Master-Pilot Exchange and closed-loop readbacks are essential.","url":"https://gcaptain.com/bridge-team-breakdown-how-communication-failures-led-to-containerships-collision-with-tall-ship/"},{"code":"ACC","title":"실습선 Kennedy, 세인트토머스서 좌초 직전 상황 발생","src":"gCaptain","date":"2026-07-09","kSum":"미국 해양대 실습선 Kennedy가 세인트토머스에서 좌초 직전 상황(near-grounding)에 처했다는 보고가 나왔다.","eSum":"The training ship Kennedy was involved in a near-grounding incident at St. Thomas, according to reports.","kCause":"항로계획 이탈 및 수심 여유(UKC) 관리 미흡 가능성.","eCause":"Possible deviation from the passage plan and inadequate under-keel clearance management.","kLes":"실습선일수록 감독 항해사의 개입 시점 기준(intervention criteria)을 명문화해야 한다.","eLes":"On training ships especially, intervention criteria for supervising officers must be explicitly documented.","url":"https://gcaptain.com/training-ship-kennedy-involved-in-near-grounding-incident-in-st-thomas-report/"}]},{"code":"PSC","type":"news","kTitle":"Section 3. 항만국통제","eTitle":"Section 3. Port State Control","items":[{"code":"PSC","title":"2026 PSC CIC 초점은 화물 고박 — 9~11월 파리·도쿄 MOU 합동 시행","src":"SAFETY4SEA","date":"2026-07-10","kSum":"파리·도쿄 MOU가 2026년 9월 1일~11월 30일 화물 고박(Cargo Securing)을 주제로 합동 집중점검(CIC)을 시행한다. 유럽·아태 항만에서 전용 질문서가 통상 검사와 병행 적용된다.","eSum":"The Paris and Tokyo MoUs will run a joint CIC on cargo securing from 1 September to 30 November 2026, applying a dedicated questionnaire alongside routine inspections in European and Asia-Pacific ports.","kImp":"고박 결함은 억류로 직결될 수 있고, 컨테이너선은 대규모 재적재로 비용·지연·용선주 분쟁까지 번질 수 있다.","eImp":"Securing deficiencies can trigger detention; boxships face costly restows, delays and charterer disputes.","url":"https://safety4sea.com/cargo-securing-in-focus-preparing-for-the-2026-psc-cic/"},{"code":"PSC","title":"ClassNK PSC 연차보고서 2026 — 화재안전·노후선이 압박 요인","src":"SAFETY4SEA","date":"2026-07-08","kSum":"ClassNK 2026 PSC 연차보고서에 따르면 2025년 화재안전이 억류사유 1위(426건)였고, 구명설비 172건, 비상시스템 169건, ISM 159건이 뒤를 이었다. USCG는 2,156회 검사에 11건 억류를 기록했다.","eSum":"ClassNK's 2026 PSC annual report shows fire safety was the top detainable deficiency category in 2025 with 426 items, followed by LSA (172), emergency systems (169) and ISM (159); the USCG recorded 11 detentions from 2,156 inspections.","kImp":"화재안전 결함의 지속적 1위는 선령 증가와 유지보수 지연이 구조적 문제임을 보여준다.","eImp":"Fire safety topping the list persistently signals a structural problem of fleet ageing and deferred maintenance.","url":"https://safety4sea.com/classnk-psc-annual-report-2026-fire-safety-and-ageing-ships-signal-psc-compliance-pressure/"},{"code":"PSC","title":"ABS PSC 보고서 1분기 2026 — 1~3월 601척 억류","src":"SAFETY4SEA","date":"2026-07-06","kSum":"ABS의 2026년 1분기 PSC 보고서에 따르면 1월부터 3월까지 전 세계에서 601척이 억류됐다.","eSum":"The ABS PSC Report for Q1 2026 records 601 vessel detentions globally from January to March.","kImp":"분기 억류 건수가 높은 수준을 유지하며, 선사는 출항 전 자체 점검(pre-PSC self-check) 강화가 필요하다.","eImp":"Detentions remain elevated quarter-on-quarter, making pre-PSC self-inspection regimes a priority for operators.","url":"https://safety4sea.com/abs-psc-report-q1-2026-601-vessel-detentions-from-january-to-march/"},{"code":"PSC","title":"파리 MOU, 새 EU PSC 체제 앞두고 RO 성과평가 방식 개정","src":"SAFETY4SEA","date":"2026-07-07","kSum":"파리 MOU가 새로운 EU PSC 규제 체제 도입을 앞두고 인정기관(RO) 성과평가 방법론을 개정한다.","eSum":"The Paris MoU will revise its RO performance methodology ahead of a new EU PSC regime.","kImp":"RO 등급 변동은 선박의 위험도 프로파일과 검사 주기에 직접 반영되므로 선급 선택 전략에 영향을 준다.","eImp":"RO rating changes feed directly into ship risk profiles and inspection frequency, affecting class selection strategy.","url":"https://safety4sea.com/paris-mou-to-revise-ro-performance-methodology-ahead-of-new-eu-psc-regime/"},{"code":"PSC","title":"도쿄 MOU 항만국통제위원회 주요 결과","src":"SAFETY4SEA","date":"2026-07-02","kSum":"도쿄 MOU 항만국통제위원회가 검사 정책, CIC 계획, 선박 위험도 산정 등 주요 안건을 결정했다.","eSum":"The Tokyo MoU Port State Control Committee agreed key outcomes on inspection policy, CIC planning and ship risk calculation.","kImp":"아태 지역 검사 정책 변경은 한국·중국·일본 기항 선대의 검사 빈도에 직접 영향을 미친다.","eImp":"Asia-Pacific inspection policy changes directly affect inspection frequency for fleets calling Korea, China and Japan.","url":"https://safety4sea.com/tokyo-mou-port-state-control-committee-key-outcomes/"},{"code":"PSC","title":"AMSA 2025 PSC 연차보고서 — 총 237척 억류","src":"SAFETY4SEA","date":"2026-07-01","kSum":"호주 AMSA의 2025년 PSC 연차보고서에 따르면 총 237척이 억류됐다.","eSum":"AMSA's 2025 annual PSC report records a total of 237 ships detained.","kImp":"호주는 억류 기준이 엄격하고 MLC 위반에 대해 항만 출입금지까지 부과하므로 호주 기항선은 특별 대비가 필요하다.","eImp":"Australia applies strict detention thresholds and issues port bans for MLC breaches, so Australia-bound ships need specific preparation.","url":"https://safety4sea.com/amsa-annual-psc-report-2025-237-ships-were-detained-in-total/"},{"code":"PSC","title":"PSC 억류는 대체로 준비 실패의 결과","src":"SAFETY4SEA","date":"2026-07-11","kSum":"선박이 억류되는 것은 본질적 문제 때문이 아니라 승무원과 관리회사가 책임을 제대로 수행하지 못했기 때문이라는 분석이다. 검사 결과를 선대 전체에 공유하는 학습 프로세스가 핵심으로 제시됐다.","eSum":"Ships are detained not because they are inherently problematic but because crews and management failed to discharge their responsibilities; sharing inspection results fleet-wide as a structured learning process is the recommended fix.","kImp":"억류를 개별 사건이 아닌 SMS 결함 신호로 다뤄야 반복 결함이 줄어든다.","eImp":"Treating detentions as SMS failure signals rather than isolated events is what reduces recurring deficiencies.","url":"https://safety4sea.com/cm-psc-detentions-are-usually-a-preparation-failure/"},{"code":"PSC","title":"도쿄·파리 MOU, 평형수 관리 합동 점검 캠페인 개시","src":"gCaptain","date":"2026-07-05","kSum":"도쿄 MOU와 파리 MOU가 선박 평형수 관리(BWM) 준수 여부를 대상으로 합동 집중점검 캠페인을 시작했다.","eSum":"The Tokyo and Paris MoUs launched a joint inspection campaign on ballast water management compliance.","kImp":"BWMS 작동 불량과 기록부 미비는 억류로 이어질 수 있어 설비 시운전·선원 교육 점검이 시급하다.","eImp":"BWMS malfunctions and incomplete records can lead to detention, making commissioning checks and crew training urgent.","url":"https://gcaptain.com/tokyo-and-paris-mous-launch-joint-inspection-campaign-on-ballast-water-management/"},{"code":"PSC","title":"파리 MOU 억류율, 팬데믹 이전 수준 상회 지속","src":"gCaptain","date":"2026-07-04","kSum":"파리 MOU의 억류율이 팬데믹 이전 수준을 계속 웃돌고 있는 것으로 나타났다.","eSum":"Paris MoU detention rates remain above pre-pandemic levels.","kImp":"유럽 기항 선대의 위험도 프로파일이 악화되며 검사 빈도와 상업적 리스크가 동시에 높아진다.","eImp":"Deteriorating risk profiles for Europe-calling fleets raise both inspection frequency and commercial risk.","url":"https://gcaptain.com/paris-mou-detention-rates-remain-above-pre-pandemic-levels/"},{"code":"PSC","title":"호주, 노동 규정 위반 라이베리아 선적 벌크선에 6개월 출입금지","src":"Baird Maritime","date":"2026-07-02","kSum":"AMSA가 뉴캐슬항에서 라이베리아 선적 벌크선 FPMC B Forever를 PSC 검사한 결과 선원 임금 약 AU$15,000 미지급과 음용수 비용 부당 청구를 적발, 억류 후 10월 4일까지 호주 항만 출입을 금지했다.","eSum":"AMSA inspected the Liberia-flagged bulker FPMC B Forever at Newcastle, found crew underpaid by almost AU$15,000 and unlawfully charged for potable water, detained the ship and banned it from Australian ports until 4 October.","kImp":"MLC 위반이 단순 결함을 넘어 선사 전체에 대한 출입금지로 이어질 수 있음을 보여주는 사례다.","eImp":"Shows MLC breaches can escalate beyond deficiencies to operator-level port bans.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/bulkers/australian-authorities-issue-six-month-ban-on-liberian-flagged-bulker-for-labour-violations"}]},{"code":"PCTC","type":"news","kTitle":"Section 4. 자동차운반선","eTitle":"Section 4. PCTC / Car Carriers","items":[{"code":"PCTC","title":"드라이카고 선박 뉴스 라운드업 7월 9일 — 유럽 선주 신조 로로선·일본 자동차선 인도","src":"Baird Maritime","date":"2026-07-09","kSum":"유럽 선주들을 위한 신조 로로선과 일본 선사의 자동차운반선 인도 등 최근 드라이카고·로로 부문 인도 및 발주 동향을 정리했다.","eSum":"Roundup covering new ro-ros for European owners, a Japanese car carrier delivery and other recent dry cargo/ro-ro deliveries and orders.","kImp":"로로·PCTC 신조 인도가 지속되며 선복 공급 증가 압력이 이어지고 있음을 확인시킨다.","eImp":"Confirms the steady stream of ro-ro/PCTC deliveries maintaining supply-side pressure on the market.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/dry-cargo-vessel-news-roundup-july-9-new-ro-ros-for-european-owners-japanese-car-carrier-delivery-and-more"},{"code":"PCTC","title":"회그 오토라이너스, 북미–중동 완성차 수송 5년 계약 체결","src":"Splash247","date":"2026-06-30","kSum":"회그 오토라이너스가 북미에서 중동으로 완성차를 수송하는 5년 장기계약을 확보했다. 신규 트레이드 레인 확장 전략의 일환이다.","eSum":"Hoegh Autoliners secured a five-year deal to carry cars from North America to the Middle East, extending its trade-lane footprint.","kImp":"장기계약 커버리지 확대는 스팟 용선료 하락 국면에서 수익 안정성을 확보하는 방어 전략이다.","eImp":"Long-term contract coverage is a defensive play to lock in earnings stability as spot charter rates soften.","url":"https://splash247.com/hoegh-autoliners-nets-five-year-deal-to-bring-cars-from-north-america-to-the-middle-east/"},{"code":"PCTC","title":"해상보험업계, 전기차 화재안전 지침 개정","src":"gCaptain","date":"2026-06-15","kSum":"국제해상보험연맹(IUMI) 등 해상보험업계가 자동차운반선의 전기차 안전운송 지침을 개정 발표했다. 배터리 충전율(SOC) 관리, 조기 감지, 소화 대응 절차 등 실무 권고를 강화했다.","eSum":"Marine insurers updated their guidelines for the safe carriage of electric vehicles on car carriers, tightening recommendations on battery state-of-charge, early detection and firefighting response.","kImp":"보험 인수 조건과 선박 운항 절차에 직접 반영될 수 있어 PCTC 운항사의 EV 화물 취급 SOP 재검토가 필요하다.","eImp":"Likely to feed into underwriting terms, requiring PCTC operators to revisit EV cargo handling SOPs.","url":"https://gcaptain.com/marine-insurers-update-electric-vehicle-fire-safety-guidelines-for-car-carriers/"},{"code":"PCTC","title":"IUMI: 로로선 전기차 화재는 폭발로 이어질 수 있다","src":"Maritime Executive","date":"2026-06-16","kSum":"IUMI는 PCTC와 로팍스 운항사가 선내 전기차 화재 시 폭발 위험에 노출된다고 경고했다. 배터리팩 방출가스에 수소가 약 30% 포함돼 폭발 잠재력이 높다는 연구를 인용했다.","eSum":"IUMI warns PCTC and ropax operators face explosion risk during onboard EV fires, citing research that battery vent gas contains around 30% hydrogen with high explosion potential.","kImp":"기존 화재진압 중심 대응을 넘어 환기·가스감지 등 폭발 방지 설계로 규제·운항 기준이 이동할 가능성을 시사한다.","eImp":"Points to a regulatory and operational shift from firefighting toward explosion prevention via ventilation and gas detection.","url":"https://maritime-executive.com/article/iumi-ev-fires-can-cause-explosions-on-ro-ros"},{"code":"PCTC","title":"IMO, 전기차 화재 위험에 주목 — PCTC 잠정 지침 우선 추진","src":"Riviera Maritime Media","date":"2026-06-10","kSum":"IMO 선박시스템·장비 소위원회(SSE12)는 신에너지차 운송 선박의 화재위험 저감을 위한 액션플랜을 개정하고, PCTC 화재안전 잠정 지침과 영상 감시·감지 시스템 지침 개발을 우선 과제로 합의했다.","eSum":"IMO's SSE12 revised its action plan on fire risk from ships carrying new-energy vehicles, prioritising interim fire-safety guidelines for PCTCs and guidelines for video monitoring/detection, with work continuing until SSE13 in March 2027.","kImp":"PCTC 전용 화재안전 규정이 국제규범으로 구체화되는 단계로, 신조 설계와 기존선 개조 비용에 직접 영향을 준다.","eImp":"PCTC-specific fire safety rules are moving toward formal international standards, with direct capex implications for newbuilds and retrofits.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/ev-fire-risks-draw-imos-attention-88377"},{"code":"PCTC","title":"인터페리, 화재 규정에 선종별 차이 반영 요구","src":"MarineLink","date":"2026-06-22","kSum":"인터페리는 IMO의 로로·차량구역 화재안전 규정 논의에서 페리, 로팍스, PCTC 등 선종별 운항 특성과 구조 차이를 반영해야 한다고 주장했다.","eSum":"Interferry argued that IMO fire regulations for ro-ro and vehicle spaces must account for structural and operational differences between ferries, ropax and PCTCs, warning that one-size-fits-all rules would be ineffective.","kImp":"규정 제정 과정에서 선종별 분화 가능성이 커져, PCTC 전용 기준이 별도로 마련될 여지를 남긴다.","eImp":"Raises the likelihood of vessel-type-differentiated rules, leaving room for a separate PCTC-specific standard.","url":"https://www.marinelink.com/news/interferry-says-vessel-differences-need-537059"},{"code":"PCTC","title":"살라움 라인, 8,600ceu 암모니아 레디 PCTC 2+2척 발주로 최대 선형 경신","src":"Splash247","date":"2026-06-25","kSum":"살라움 라인이 중국 샤먼조선에 8,600ceu급 PCTC 확정 2척·옵션 2척을 발주했다. LNG·VLSFO·MGO 운항이 가능하고 암모니아 레디 사양이며, 전장 약 200m에 리프터블 데크 5개를 갖춰 승용차와 상용차·중량 롤링 화물을 혼적할 수 있다.","eSum":"Sallaum Lines ordered two firm plus two optional 8,600 ceu PCTCs at Xiamen Shipbuilding Industry. The LNG/VLSFO/MGO-capable, ammonia-ready ships measure nearly 200m with five liftable decks, carrying a mix of cars, light commercial units and heavy rolling cargo.","kImp":"중견 선사까지 8,600ceu 대형선·암모니아 레디 사양으로 상향되면서, 아시아발 수출 물량 증가에 대응한 PCTC 대형화 경쟁이 전 선사로 확산되고 있음을 보여준다.","eImp":"Mid-tier operators are now moving to 8,600 ceu ammonia-ready tonnage, showing the PCTC upsizing race has spread across the whole owner spectrum in response to rising Asian export flows.","url":"https://splash247.com/sallaum-lines-continues-car-carrier-fleet-expanision/"},{"code":"PCTC","title":"레이 카캐리어스, HD현대에 2억7,000만 달러 규모 PCTC 신조 계약 연계","src":"Riviera Maritime Media","date":"2026-07-01","kSum":"레이 카캐리어스가 HD현대 조선소에서 약 2억7,000만 달러 규모의 PCTC 신조 계약과 연계된 것으로 파악됐다. 그리스계 선주가 자동차운반선 선대를 한국 조선소를 통해 확대하는 움직임이다.","eSum":"Ray Car Carriers has been linked to a roughly US$270M PCTC newbuilding contract at HD Hyundai, as the owner expands its vehicle carrier fleet through Korean yards.","kImp":"중국 조선소 중심으로 쏠렸던 PCTC 신조 발주가 한국 조선소로도 분산되는 신호로, 선가와 슬롯 확보 경쟁의 지형 변화를 시사한다.","eImp":"Indicates PCTC newbuild orders — heavily concentrated in Chinese yards — are diversifying back toward Korea, shifting the pricing and berth-slot competition landscape.","url":"https://www.rivieramm.com/news-content-hub/ray-car-carriers-linked-to-us270m-pctc-newbuilding-contract-at-hd-hyundai-88493"},{"code":"PCTC","title":"베어드 건화물선 뉴스 라운드업 7월 1일 — 중국 건조 자동차운반선 등","src":"Baird Maritime","date":"2026-07-01","kSum":"베어드 마리타임의 7월 1일 건화물선 뉴스 라운드업에서 중국에서 건조된 자동차운반선 인도 소식과 영국 선주의 신규 근해선 등 최신 선대 소식을 정리했다.","eSum":"Baird Maritime's 1 July dry cargo vessel news roundup covers newly delivered China-built car carriers, a UK owner's new shortsea ship and other fleet developments.","kImp":"중국 조선소발 PCTC 인도가 주간 단위로 지속되고 있음을 확인시켜 주며, 2026년 하반기 선복 공급 압력을 가늠하는 지표가 된다.","eImp":"Confirms a steady weekly cadence of China-built PCTC deliveries, a useful gauge of tonnage supply pressure through H2 2026.","url":"https://www.bairdmaritime.com/amp/story/shipping/dry-cargo/dry-cargo-vessel-news-roundup-july-1-china-built-car-carriers-uk-owners-new-shortsea-ship-and-more"},{"code":"PCTC","title":"칼럼 | 신형 자동차운반선 설계, 화재 시 탈출 어렵게 만들 수 있다","src":"Baird Maritime","date":"2026-07-06","kSum":"베어드 마리타임 Grey Power 칼럼은 대형화·다층화된 신형 자동차운반선 설계가 화재 발생 시 승조원 탈출과 대피를 어렵게 만들 수 있다고 지적했다. 데크 수 증가와 밀집 적재가 소화·탈출 동선을 제약한다는 문제 제기다.","eSum":"Baird Maritime's Grey Power column argues that the design of new, larger multi-deck car carriers could make crew escape and evacuation difficult in a fire, as more decks and denser stowage constrain firefighting and escape routes.","kImp":"EV 화재 리스크 논의가 소화 설비를 넘어 선박 설계·탈출 동선 자체로 확대되고 있으며, 향후 SOLAS 개정 논의에서 설계 규제가 쟁점화될 수 있다.","eImp":"Extends the EV fire debate beyond suppression systems to vessel design and escape routes, a likely flashpoint in upcoming SOLAS amendment discussions.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/column-new-car-carrier-designs-could-make-evacuation-difficult-in-case-of-fire-grey-power"},{"code":"PCTC","title":"안지물류, 2026년 해상 완성차 수송능력 60만 대로 확대","src":"Automotive Logistics","date":"2026-06-30","kSum":"중국 상하이자동차(SAIC) 계열 안지물류가 2026년 연간 해상 완성차 수송능력이 60만 대에 이를 것이라고 밝혔다. 2025년 한 해에만 PCTC 8척을 인도받아 총 선대는 41척으로 늘었다.","eSum":"Anji Logistics, owned by China's SAIC Motor, says its annual ocean finished-vehicle transport capacity will reach 600,000 units in 2026. It took delivery of eight PCTCs in 2025, bringing its fleet to 41 vessels.","kImp":"중국 OEM 계열 물류사의 자체 선대 수직계열화가 빠르게 진행되면서, 기존 글로벌 PCTC 선사의 중국발 수출 물량 확보 경쟁이 한층 치열해질 전망이다.","eImp":"Rapid vertical integration by Chinese OEM-affiliated logistics arms will intensify competition for China-origin export volumes against established global PCTC operators.","url":"https://www.automotivelogistics.media/vehicle-logistics/anji-logistics-boosts-ocean-carrier-capacity-for-2026/2582650"},{"code":"PCTC","title":"로로 선복난 지속에 컨테이너 자동차 수송이 일상화","src":"Seatrade Maritime","date":"2026-07-08","kSum":"로로·PCTC 부문의 선복 부족이 이어지면서 완성차를 컨테이너에 적입해 수송하는 방식이 예외가 아닌 일상적 대안으로 자리잡고 있다. 자동차 제조사들이 확보 가능한 선복을 찾아 컨테이너 선사로 눈을 돌리고 있다.","eSum":"With the ro-ro capacity crunch persisting, shipping finished vehicles in containers has become the norm rather than an exception, as carmakers turn to container lines to secure available space.","kImp":"컨테이너 수송이 PCTC의 구조적 대체재로 굳어지면 자동차운반선 운임의 상단이 제한될 수 있어, 선복 공급 확대기와 맞물릴 경우 운임 하방 압력이 커진다.","eImp":"If containerised car moves entrench as a structural substitute, they cap the upside for PCTC freight rates — a real downside risk as newbuild supply floods in.","url":"https://www.seatrade-maritime.com/containers/cars-in-containers-the-norm-as-ro-ro-sector-capacity-crunch-continues"}]},{"code":"WW","type":"news","kTitle":"Section 5. 발레니우스 빌헬름센","eTitle":"Section 5. Wallenius Wilhelmsen","items":[{"code":"WW","title":"발레니우스 빌헬름센, 불확실한 시장에서 안정적인 1분기 실적 시현","src":"Wallenius Wilhelmsen","date":"2026-05-13","kSum":"발레니우스 빌헬름센이 불확실한 시장 환경에도 견조한 1분기 실적을 발표했다. 계약 커버리지와 물류 부문 개선이 해운 부문의 계절적 약세를 상쇄했다.","eSum":"Wallenius Wilhelmsen reported a solid Q1 despite market uncertainty, with contract coverage and improved Logistics results offsetting seasonally softer Shipping.","kImp":"용선료 하락 국면에서도 장기계약 기반 수익구조가 실적 방어력을 제공함을 입증한다.","eImp":"Demonstrates that a long-term contract-backed earnings model provides resilience even as charter rates fall.","url":"https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-delivers-stability-and-a-strong-q1-in-an-uncertain-market"},{"code":"WW","title":"발레니우스 빌헬름센 1분기 조정 EBITDA 3억 8,900만 달러","src":"MarketScreener","date":"2026-05-13","kSum":"2026년 1분기 조정 EBITDA는 3억 8,900만 달러로 전분기 대비 3% 감소했고 매출은 12억 5,300만 달러를 기록했다. 순이자부부채는 20억 6,500만 달러로 19% 증가했다.","eSum":"Q1 2026 adjusted EBITDA came in at USD 389m, down 3% QoQ, on revenue of USD 1,253m. NIBD rose 19% to USD 2,065m and liquidity reserves fell 28% to USD 1,437m after dividend payout and RCF drawdowns.","kImp":"배당 지급과 신조 투자로 재무 레버리지가 상승하는 국면으로, 향후 배당 여력과 자본 배분 우선순위를 주시할 필요가 있다.","eImp":"Rising leverage from dividends and newbuild capex makes future payout capacity and capital allocation the key watch items.","url":"https://www.marketscreener.com/news/wallenius-wilhelmsen-q1-adjusted-ebitda-389-mln-ce7f58ddda80f427"},{"code":"WW","title":"발레니우스 빌헬름센 2026년 1분기 실적 발표자료 — 연간 EBITDA 16억 달러 가이던스","src":"MarketScreener","date":"2026-05-13","kSum":"1분기 실적 발표자료에서 회사는 2026년 조정 EBITDA 가이던스를 약 16억 달러로 제시했다. 벙커유 순원가 상승과 선복 비용 증가를 반영했으며, 중동 정세 등 외부 변수에 크게 좌우된다고 밝혔다.","eSum":"The Q1 2026 presentation guided to about USD 1.6bn adjusted EBITDA for 2026, reflecting significantly higher net bunker costs and increased capacity costs, while flagging dependence on the Middle East situation.","kImp":"연료비와 선복비 상승이 2026년 마진을 압박하는 핵심 변수로, 지정학 리스크가 가이던스의 최대 불확실성이다.","eImp":"Bunker and capacity costs are the key 2026 margin headwinds, with geopolitics the biggest guidance swing factor.","url":"https://www.marketscreener.com/news/wallenius-wilhelmsen-q1-2026-presentation-ce7f58dddc81f125"},{"code":"WW","title":"발레니우스 빌헬름센, 신조선 4척 세계 최대급으로 대형화","src":"Wallenius Wilhelmsen","date":"2026-03-20","kSum":"발레니우스 빌헬름센이 셰이퍼 클래스 신조선 4척을 세계 최대 규모인 11,700CEU급으로 상향 설계했다. 인도는 2027년 말부터 예정돼 있다.","eSum":"Wallenius Wilhelmsen upsized four Shaper Class newbuilds to 11,700 CEU, the largest car carriers in the world, with deliveries due from late 2027.","kImp":"규모의 경제를 통한 CEU당 단위원가 절감 전략으로, 경쟁사 대비 원가 우위 확보를 노린다.","eImp":"A scale play to cut unit cost per CEU and build a structural cost advantage over rivals.","url":"https://www.walleniuswilhelmsen.com/news/we-are-going-large-wallenius-wilhelmsen-upsizes-four-vessels-to-the-largest-in-the-world"},{"code":"WW","title":"발레니우스 빌헬름센, 신조 자동차선 4척 사상 최대 규모로 상향","src":"Seatrade Maritime","date":"2026-03-21","kSum":"발레니우스 빌헬름센이 셰이퍼 클래스 발주분 중 4척을 11,700CEU로 대형화한다고 밝혔다. 현재 발주 잔량은 9,300CEU급 6척과 11,700CEU급으로 확대된 8척으로 구성된다.","eSum":"Seatrade reports Wallenius Wilhelmsen upsizing four newbuild car carriers to the largest ever built; the orderbook now comprises six 9,300 CEU vessels and eight expanded to 11,700 CEU.","kImp":"WW의 신조 선대 규모가 14척으로 확대되며, 2027~2029년 선복 공급 증가의 주요 축이 된다.","eImp":"Confirms a 14-ship newbuild programme that will be a major driver of 2027-29 capacity growth.","url":"https://www.seatrade-maritime.com/shipyards/wallenius-wilhelmsen-upsizing-four-newbuild-car-carriers-to-largest-ever"},{"code":"WW","title":"발레니우스 빌헬름센, 셰이퍼 클래스 추가 4척 옵션 행사","src":"Wallenius Wilhelmsen","date":"2026-02-12","kSum":"발레니우스 빌헬름센이 셰이퍼 클래스 추가 4척에 대한 옵션을 행사했다. 메탄올 이중연료·암모니아 레디 사양이 적용된다.","eSum":"Wallenius Wilhelmsen declared options for four additional Shaper Class vessels, all methanol dual-fuel and ammonia-ready.","kImp":"발주 사이클이 둔화되는 시장에서 WW가 역행적으로 선대 확장에 나서고 있음을 보여준다.","eImp":"Shows WW expanding counter-cyclically while the wider ordering cycle cools.","url":"https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-declare-options-for-four-additional-shaper-class-vessels"},{"code":"WW","title":"발레니우스 빌헬름센, 메탄올 추진·암모니아 레디 신조선 4척 추가 발주","src":"Splash247","date":"2026-02-13","kSum":"발레니우스 빌헬름센이 메탄올 추진·암모니아 레디 자동차운반선 4척을 추가 발주했다고 보도됐다. 중국 조선소에서 건조되며 셰이퍼 클래스 시리즈에 편입된다.","eSum":"Wallenius Wilhelmsen placed four more orders for methanol-fuelled, ammonia-ready car carrier newbuilds, joining the Shaper Class series at Chinese yards.","kImp":"메탄올 이중연료 PCTC 선대 규모에서 WW가 업계 선두를 굳히고 있음을 확인시킨다.","eImp":"Cements WW's lead in methanol dual-fuel PCTC tonnage among car carrier operators.","url":"https://splash247.com/wallenius-wilhelmsen-places-four-more-orders-for-methanol-fuelled-ammonia-ready-newbuilds/"},{"code":"WW","title":"발레니우스 빌헬름센, 11,700CEU 셰이퍼 클래스 2척 옵션 행사 및 2척 추가 대형화 추진","src":"Wallenius Wilhelmsen","date":"2026-04-24","kSum":"발레니우스 빌헬름센이 11,700CEU급 셰이퍼 클래스 2척에 대한 옵션을 행사하고, 추가 2척을 동급으로 대형화할 의사를 밝혔다는 증권거래소 공시를 냈다.","eSum":"Stock exchange notice: Wallenius Wilhelmsen exercised options for two additional 11,700 CEU Shaper Class vessels and signalled its intention to upsize two more.","kImp":"대형화 기조가 옵션 행사 단계까지 이어지며, 자본지출 규모와 인도 스케줄이 재무구조의 핵심 변수가 된다.","eImp":"The upsizing push is now locked in via option exercises, making capex scale and delivery timing key balance-sheet variables.","url":"https://www.walleniuswilhelmsen.com/stock-exchange-notice/wallenius-wilhelmsen-exercise-options-for-two-additional-11-700-ceu-shaper-class-vessels-and-intends-to-upsize-an-additional-two"},{"code":"WW","title":"발레니우스 빌헬름센, 재무목표 및 배당정책 갱신","src":"Wallenius Wilhelmsen","date":"2026-02-20","kSum":"이사회가 재무목표와 배당정책을 갱신했다. 연간 세후이익의 30~50%를 배당으로 지급하며, 상·하반기 순이익을 기준으로 반기 단위 선언·지급한다는 방침을 재확인했다.","eSum":"The Board updated its financial targets and dividend policy, targeting dividends of 30-50% of annual profit after tax, declared and paid semi-annually based on reported net profit for each half-year.","kImp":"신조 투자 확대 국면에서 주주환원 정책의 예측가능성을 높여 주가 밸류에이션을 지지하는 요인이다.","eImp":"Adds predictability to shareholder returns during a heavy newbuild capex cycle, supporting the equity valuation.","url":"https://www.walleniuswilhelmsen.com/stock-exchange-notice/wallenius-wilhelmsen-updated-financial-targets-and-dividend-policy"},{"code":"WW","title":"세계 최초 풍력추진 로로선 오르셀 윈드, EU 자금 900만 유로 확보","src":"Wallenius Wilhelmsen","date":"2026-04-08","kSum":"발레니우스 빌헬름센과 프로젝트 파트너들이 풍력 로로선 건조를 위해 Horizon Europe에서 총 900만 유로를 확보했다. 기상 라우팅, 선박 설계, 공급망 조율, 승무원 훈련, 기존선 리그 설치 시험까지 포괄한다.","eSum":"Wallenius Wilhelmsen and partners secured EUR 9m in Horizon Europe funding for the world's first wind-powered ro-ro, covering weather routing, vessel design, supply chain orchestration, crew training and rig installation trials on an existing vessel.","kImp":"풍력추진 상용화의 자금·기술 리스크를 공적자금으로 분산시키는 구조로, 오르셀 윈드 실현 가능성을 높인다.","eImp":"Public funding de-risks the wind-propulsion commercialisation path and raises the odds of Orcelle Wind materialising.","url":"https://www.walleniuswilhelmsen.com/news/worlds-first-wind-powered-roro-vessel-secures-eur-9m-in-eu-funding"},{"code":"WW","title":"오르셀 터미널 개장 — 2027년 18,000CEU로 확장","src":"Wallenius Wilhelmsen","date":"2026-05-28","kSum":"오랜 기다림 끝에 오르셀 터미널이 5월 문을 열었다. 현재 처리능력 10,000CEU, 트로피카나 터미널 선석 1개, 전용 차량가공센터와 친환경 세차시설을 갖췄으며 2027년까지 선석 3개·풍력발전기 2기와 함께 18,000CEU로 확장된다.","eSum":"Orcelle Terminal opened in May with 10,000 CEU capacity, a berth at Tropicana Terminal, a dedicated vehicle processing centre and an eco-car wash; by 2027 it will expand to 18,000 CEU with three berths and two windmills generating clean power.","kImp":"해상-육상 통합 물류 역량 강화로 엔드투엔드 서비스 마진과 고객 락인 효과를 높인다.","eImp":"Strengthens integrated sea-land logistics, boosting end-to-end margins and customer lock-in.","url":"https://www.walleniuswilhelmsen.com/news/orcelle-terminal-opens-its-doors"},{"code":"WW","title":"발레니우스 빌헬름센, 오르셀 윈드 신형 선체 시험 완료 후 조선소 접촉","src":"Offshore Energy","date":"2026-06-05","kSum":"발레니우스 빌헬름센이 오르셀 윈드의 신형 선체를 시험한 뒤 조선소 접촉에 나섰다. 220m, 7,000대 이상 적재 능력에 브레이크벌크·롤링 장비도 수송 가능한 설계다.","eSum":"Wallenius Wilhelmsen tested the new hull for Orcelle Wind before approaching shipyards; the 220m design carries over 7,000 cars plus breakbulk and rolling equipment, targeting service entry in late 2026 or early 2027.","kImp":"세계 최초 풀스케일 풍력추진 로로선이 발주 단계에 근접했으며, 성공 시 업계 탈탄소 경로에 새 선택지를 제시한다.","eImp":"The world's first full-scale wind-powered ro-ro is nearing order stage; success would open a new decarbonisation pathway for the sector.","url":"https://www.offshore-energy.biz/watch-wallenius-wilhelmsen-tests-new-hull-of-orcelle-wind/"},{"code":"WW","title":"워터웨이 IT, 글로벌 선박 IT 공급사로 출범","src":"Wilhelmsen","date":"2026-04-01","kSum":"빌헬름센 십 매니지먼트와 MPC 캐피털이 합작한 워터웨이 IT(Waterway IT)가 2026년 4월 1일부터 선내 IT 솔루션 독립 공급사로 전 세계 영업을 시작했다.","eSum":"Waterway IT, a JV between Wilhelmsen Ship Management and MPC Capital, began operating on 1 April 2026 as an independent global provider of secure, future-ready onboard vessel IT.","kImp":"선박 사이버보안·디지털 인프라 수요 증가에 대응한 플랫폼 사업 진출로, 빌헬름센 그룹의 비자산 수익 모델을 강화한다.","eImp":"A platform play into rising vessel cyber-security and digital infrastructure demand, strengthening the group's asset-light revenue mix.","url":"https://www.wilhelmsen.com/media-news-and-events/press-releases/2026/waterway-it-a-new-global-platform-for-onboard-vessel-it/"},{"code":"WW","title":"빌헬름센 홀딩 2026년 1분기 실적 보고서","src":"MarketScreener","date":"2026-05-14","kSum":"빌헬름센 홀딩(Wilh. Wilhelmsen Holding)이 2026년 1분기 실적 보고서를 공시했다. 선박관리, 선용품·서비스, 발레니우스 빌헬름센 지분 등 그룹 전 부문 실적이 포함된다.","eSum":"Wilh. Wilhelmsen Holding published its Q1 2026 report, covering ship management, ships service and its stake in Wallenius Wilhelmsen across the group's segments.","kImp":"지주회사 실적은 WW ASA 지분가치와 비해운 서비스 부문의 성장세를 동시에 반영하는 지표다.","eImp":"Holding-level results capture both the WW ASA stake value and the growth trajectory of non-shipping service segments.","url":"https://www.marketscreener.com/news/wilh-wilhelmsen-wilhelmsen-q1-2026-report-ce7f58d2da8cf021"}]},{"code":"EE","type":"news","kTitle":"Section 6. 에너지 효율·탈탄소","eTitle":"Section 6. Energy Efficiency","items":[{"code":"EE","title":"VPS: 넷제로 프레임워크 지연으로 EU ETS·FuelEU에 초점 이동","src":"SAFETY4SEA","date":"2026-07-08","kSum":"VPS는 IMO 넷제로 프레임워크 채택이 2026년 10월로 연기되면서 선주들의 실질적 규제 부담이 이미 시행 중인 EU ETS와 FuelEU Maritime으로 옮겨갔다고 분석했다.","eSum":"VPS says the delay of the IMO Net-Zero Framework adoption to October 2026 has shifted owners' practical compliance focus onto the already-in-force EU ETS and FuelEU Maritime, with entry into force now impossible before March 2028.","kImp":"단기 컴플라이언스 예산과 연료 전략은 IMO가 아니라 EU 규제 기준으로 재편해야 한다.","eImp":"Near-term compliance budgets and fuel strategy must be built around EU rules, not the IMO timeline.","url":"https://safety4sea.com/vps-net-zero-framework-delay-shifts-focus-to-eu-ets-and-fueleu/"},{"code":"EE","title":"ICS: 선상 탄소포집(OCCS)이 해운 탈탄소에 중요한 역할 가능","src":"SAFETY4SEA","date":"2026-07-01","kSum":"국제해운회의소(ICS)는 OCCS가 해운 탈탄소에 상당한 역할을 할 수 있으나, EEXI·EEDI·CII에 포집 탄소를 크레딧으로 인정하는 메커니즘이 없어 규제 공백이 크다고 지적했다.","eSum":"The ICS argues onboard carbon capture could play a significant decarbonisation role, but notes EEXI, EEDI and CII provide no mechanism to credit captured carbon, leaving a major regulatory gap.","kImp":"OCCS 투자 판단은 규제 인정 여부가 결정하므로 조기 도입은 리스크가 크다.","eImp":"OCCS investment cases hinge on regulatory recognition, so early adoption carries real risk.","url":"https://safety4sea.com/ics-occs-could-play-significant-role-in-shippings-decarbonization/"},{"code":"EE","title":"IMO 넷제로 지연에도 선박은 FuelEU·EU ETS 부담 직면","src":"MarineLink","date":"2026-07-06","kSum":"IMO 넷제로 프레임워크가 지연됐음에도 EU 역내 운항 선박은 FuelEU Maritime의 GHG 집약도 한도와 EU ETS 배출권 매입 의무를 그대로 이행해야 한다는 분석이다.","eSum":"Despite the IMO Net-Zero Framework delay, vessels trading in EU waters still face FuelEU Maritime GHG-intensity limits and EU ETS allowance purchase obligations in full.","kImp":"EU 항로 배선 선박은 지연을 이유로 컴플라이언스 준비를 늦출 수 없다.","eImp":"Ships on EU trades cannot use the IMO delay as a reason to slow compliance preparation.","url":"https://www.marinelink.com/news/vessels-face-fueleu-maritime-eu-ets-531852"},{"code":"EE","title":"IMO와 EU 탈탄소 체제 간 전략적 차이 분석","src":"Riviera Maritime Media","date":"2026-07-02","kSum":"IMO의 글로벌 체제와 EU의 지역 규제는 적용 범위, 연료 라이프사이클 산정, 페널티 구조에서 근본적으로 달라 선주가 이중 컴플라이언스를 설계해야 한다는 지적이다.","eSum":"Riviera analyses how the IMO's global regime and the EU's regional rules differ fundamentally in scope, fuel lifecycle accounting and penalty structure, forcing owners into dual compliance design.","kImp":"이중 체제 하에서 항로별 연료 배분 최적화가 수익성을 좌우한다.","eImp":"Under dual regimes, route-level fuel allocation optimisation drives profitability.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/strategic-differences-between-imo-and-eu-decarbonisation-regimes-84771"},{"code":"EE","title":"영국 ETS 해운 부문 확대 — DNV, 핵심 메커니즘 제시","src":"Manifold Times","date":"2026-07-10","kSum":"DNV는 영국 ETS의 해운 부문 확대에 따른 적용 대상, 배출권 산정 방식, EU ETS와의 상호작용 등 핵심 메커니즘과 선사 영향을 정리했다.","eSum":"DNV outlines the key mechanisms of the UK ETS expansion into shipping — scope, allowance calculation and interaction with the EU ETS — and its implications for operators.","kImp":"영국 기항 선박은 EU ETS에 더해 추가 탄소비용을 예산에 반영해야 한다.","eImp":"Ships calling the UK must budget an additional carbon cost layer on top of EU ETS.","url":"https://www.manifoldtimes.com/news/uk-ets-expansion-to-maritime-sector-dnv-outlines-key-mechanisms-and-implications"},{"code":"EE","title":"OOCL 이중연료 컨테이너선, 칭다오항서 첫 그린메탄올 벙커링","src":"Manifold Times","date":"2026-07-06","kSum":"세계 최대 메탄올 이중연료 컨테이너선인 24,168TEU급 OOCL Wisdom이 7월 3일 칭다오항에서 첫 그린메탄올 벙커링을 완료했다. 아시아-북유럽 Loop 1 서비스에 투입된다.","eSum":"OOCL Wisdom, at 24,168 TEU the world's largest methanol dual-fuel containership, completed its first green methanol bunkering at Qingdao Port on 3 July, ahead of deployment on the Asia-North Europe Loop 1 service.","kImp":"중국 항만의 그린메탄올 공급망이 초대형 컨테이너선 상업 운항 수준에 도달했다.","eImp":"Chinese ports' green methanol supply chain has reached commercial ULCS scale.","url":"https://www.manifoldtimes.com/news/oocl-dual-fuel-boxship-completes-first-green-methanol-bunkering-op-at-qingdao-port/"},{"code":"EE","title":"DNV: 2026년 상반기 대체연료 선박 발주 11.6% 감소","src":"Manifold Times","date":"2026-07-09","kSum":"DNV 집계 결과 2026년 상반기 대체연료 선박 발주는 137척으로 전년 동기 155척 대비 11.6% 줄었다. 메탄올 2척, 에탄올 2척, 암모니아 4척, 수소 1척 등으로 LNG 편중이 심화됐다.","eSum":"DNV data shows 137 alternative-fuelled vessels were ordered in H1 2026, down 11.6% from 155 a year earlier, with just 2 methanol, 2 ethanol, 4 ammonia and 1 hydrogen — deepening the LNG skew.","kImp":"대체연료 발주 둔화는 규제 불확실성이 투자 결정을 지연시키고 있음을 보여준다.","eImp":"Slowing alternative-fuel orders show regulatory uncertainty is deferring investment decisions.","url":"https://www.manifoldtimes.com/news/dnv-alternative-fuelled-vessel-orders-down-11-6-in-h1-2026/"},{"code":"EE","title":"세계 최초 암모니아 이중연료 가스운반선 항만-선박 벙커링 완료","src":"Offshore Energy","date":"2026-07-01","kSum":"울산항에서 암모니아 이중연료 가스운반선을 대상으로 한 세계 최초 항만-선박(port-to-ship) 암모니아 벙커링이 완료됐다. 울산항은 메탄올 벙커링 실증과 자동차운반선 동시 LNG 벙커링 실적도 보유하고 있다.","eSum":"The world's first port-to-ship ammonia bunkering for an ammonia dual-fuel gas carrier was completed at Ulsan Port, which has also delivered methanol bunkering demonstrations and simultaneous LNG bunkering for car carriers.","kImp":"암모니아 연료 공급 인프라가 실증을 넘어 상업 운영 단계로 진입하고 있다.","eImp":"Ammonia fuel supply infrastructure is moving beyond demonstration into commercial operation.","url":"https://www.offshore-energy.biz/worlds-first-ammonia-port-to-ship-bunkering-for-dual-fuel-gas-carrier-wraps-up-in-korea/"},{"code":"EE","title":"CE Delft: CII 제대로 집행되면 EU 해운 배출 30% 감축 가능","src":"Offshore Energy","date":"2026-07-07","kSum":"CE Delft 연구는 CII 규제가 실효적으로 집행될 경우 EU 해운 배출을 최대 30% 줄일 수 있으나, 현행 등급제의 허점과 약한 페널티가 효과를 제한하고 있다고 분석했다.","eSum":"A CE Delft study finds CII could cut EU shipping emissions by up to 30% if properly enforced, but loopholes in the rating scheme and weak penalties are blunting its effect.","kImp":"CII 강화 개정 논의가 재점화될 경우 노후선 운항 제약이 커진다.","eImp":"If CII tightening is revived, operational constraints on older tonnage will increase.","url":"https://www.offshore-energy.biz/ce-delft-cii-could-cut-eu-shippings-emissions-by-30-if-enforced-correctly/"},{"code":"EE","title":"중국 산둥해운, LNG 이중연료 컨테이너선 발주","src":"Offshore Energy","date":"2026-07-13","kSum":"중국 산둥해운(Shandong Shipping)이 LNG 이중연료 컨테이너선을 발주했다. 2026년 대체연료 발주가 LNG 중심으로 재편되는 흐름을 다시 확인시켜 준다.","eSum":"China's Shandong Shipping has ordered LNG dual-fuel containerships, reinforcing the 2026 trend of alternative-fuel newbuild ordering consolidating around LNG.","kImp":"LNG가 사실상 과도기 연료의 기본값으로 굳어지고 있다.","eImp":"LNG is hardening into the default transition fuel.","url":"https://www.offshore-energy.biz/chinas-shandong-shipping-places-order-for-lng-dual-fuel-containership/"},{"code":"EE","title":"카길 용선용 최초 캄사르막스 메탄올 추진 벌크선 인도","src":"Maritime Executive","date":"2026-07-07","kSum":"카길 장기 용선을 전제로 한 세계 최초 메탄올 추진 캄사르막스 벌크선이 인도됐다. 벌크 부문에서도 메탄올 이중연료가 상업 운항에 진입했다.","eSum":"The first Kamsarmax methanol-fuelled bulk carrier has been delivered for charter to Cargill, bringing methanol dual-fuel into commercial service in the dry bulk sector.","kImp":"화주 주도 장기 용선이 대체연료 벌크선 발주의 핵심 자금원임을 보여준다.","eImp":"Charterer-backed long-term contracts are the key financing route for alternative-fuel bulkers.","url":"https://maritime-executive.com/article/first-kamsarmax-methanol-fueled-bulker-delivered-for-cargill-charter"},{"code":"EE","title":"연구: 듀얼유즈 LNG 선박이 탄소포집 물류를 바꿀 수 있다","src":"Maritime Executive","date":"2026-07-10","kSum":"LNG 운반선을 LCO2 운송과 겸용(dual-use)으로 설계·운용하면 CCS 밸류체인의 물류 병목을 크게 완화할 수 있다는 연구 결과다. 22,000㎥급 대형 LCO2/멀티가스 운반선도 이미 인도됐다.","eSum":"A study argues that designing and operating LNG carriers for dual-use LCO2 transport could ease the logistics bottleneck in the CCS value chain; a 22,000 cbm large LCO2/multi-gas carrier has already been delivered.","kImp":"CCS 확대는 전용선 신조뿐 아니라 기존 가스선 겸용화로도 가능해진다.","eImp":"CCS scale-up may come from converting existing gas carriers, not only purpose-built newbuilds.","url":"https://maritime-executive.com/article/study-dual-use-lng-shipping-could-transform-carbon-capture"},{"code":"EE","title":"현대중공업, 자체 로터세일 기술 공개","src":"Splash247","date":"2026-07-08","kSum":"현대중공업이 자체 개발한 로터세일 기술을 선보였다. 연료 소모와 탄소배출을 약 6~8% 줄일 수 있다고 밝혔다.","eSum":"Hyundai Heavy Industries has debuted its own rotor sail technology, claiming fuel consumption and carbon emission reductions of around 6-8%.","kImp":"조선소가 풍력보조추진을 내재화하면 신조 옵션 채택 비용이 낮아진다.","eImp":"Shipyard-owned WAPS lowers the cost of specifying wind assist on newbuilds.","url":"https://splash247.com/hyundai-heavy-debuts-its-own-rotor-sail-tech/"},{"code":"EE","title":"EU, 풍력추진 확산 가속 프로젝트 지원","src":"Splash247","date":"2026-07-02","kSum":"EU가 해운 풍력추진 기술의 상업적 도입을 가속하기 위한 프로젝트를 지원한다. 로터세일·석션윙·리지드세일은 이미 실선에서 5~20% 연료 절감을 입증했다.","eSum":"The EU is backing a project to accelerate commercial uptake of wind propulsion in shipping; rotor sails, suction wings and rigid sails have already demonstrated 5-20% fuel savings in real operations.","kImp":"공공 자금 지원은 풍력보조추진의 투자회수 기간을 단축시킨다.","eImp":"Public funding shortens the payback period for wind-assist retrofits.","url":"https://splash247.com/eu-backs-wind-propulsion-project-to-accelerate-shipping-uptake/"}]},{"code":"DIG","type":"news","kTitle":"Section 7. 디지털라이제이션","eTitle":"Section 7. Digitalization","items":[{"code":"DIG","title":"AI 인프라·자율운항 선박 설계 가속 위한 신규 이니셔티브 출범","src":"SAFETY4SEA","date":"2026-07-06","kSum":"포시도니아 2026에서 AI 기반 디지털 인프라와 자율운항 선박 설계를 추진하는 신규 이니셔티브들이 발표됐다. 해운이 물류·에너지·디지털 인프라·AI 운영을 결합한 하이브리드 산업으로 진화하고 있다는 평가다.","eSum":"New initiatives to advance AI infrastructure and autonomous vessel design were announced at Posidonia 2026, reflecting shipping's evolution into a hybrid of logistics, energy, digital infrastructure and AI-enabled operations.","kImp":"선사의 IT 조직은 지원부서가 아니라 사업개발 조직으로 재정의되고 있다.","eImp":"Owners' IT functions are being redefined from support units into business-development units.","url":"https://safety4sea.com/new-initiatives-formed-to-advance-ai-infrastructure-and-autonomous-vessel-design/"},{"code":"DIG","title":"앵글로-이스턴: 사이버 보안은 더 이상 IT만의 문제가 아니다","src":"SAFETY4SEA","date":"2026-07-09","kSum":"앵글로-이스턴은 2026년 사이버 보안이 IT 이슈를 넘어 핵심 사업·안전·규제 문제가 됐다고 밝혔다. 스타링크 등 위성망 확산으로 선박 시스템이 본사 수준의 위협에 노출되고 있다.","eSum":"Anglo-Eastern says cyber security in 2026 is no longer an IT issue but a core business, safety and regulatory concern, as Starlink and hybrid networks expose shipboard systems to headquarters-level threats.","kImp":"선박관리사는 OT 네트워크 분리와 선원 교육을 안전관리체계에 통합해야 한다.","eImp":"Managers must fold OT segregation and crew training into their safety management systems.","url":"https://safety4sea.com/anglo-eastern-cyber-security-is-no-longer-just-an-it-issue/"},{"code":"DIG","title":"IMO, 자율운항선박 강제 규정 도입 계획 제시","src":"MarineLink","date":"2026-07-10","kSum":"IMO가 비강제 MASS 코드 시행 이후 강제화 로드맵을 제시했다. 경험축적기간(Experience Building Phase)을 거쳐 구속력 있는 규정으로 전환하는 절차가 논의되고 있다.","eSum":"The IMO has outlined its roadmap toward binding rules for autonomous ships following entry into effect of the non-mandatory MASS Code, with an Experience Building Phase preceding mandatory status.","kImp":"자율운항 관련 투자는 강제화 시점을 감안한 단계적 접근이 안전하다.","eImp":"Autonomy investments should be staged against the mandatory-code timeline.","url":"https://www.marinelink.com/news/imo-outlines-plans-binding-rules-539565"},{"code":"DIG","title":"IMO, 자율운항선박 글로벌 코드 채택","src":"MarineLink","date":"2026-07-02","kSum":"IMO는 MSC 111에서 최초의 자율운항선박(MASS) 코드를 채택했으며, 2026년 7월 1일부터 비강제 문서로 발효됐다. 화물선에 적용된다.","eSum":"The IMO adopted the first-ever MASS Code at MSC 111; it took effect as a non-mandatory instrument on 1 July 2026 and applies to cargo ships.","kImp":"7월 1일 발효로 자율운항 시범 프로젝트의 규제 근거가 처음 마련됐다.","eImp":"The 1 July entry into effect gives autonomy pilots their first regulatory basis.","url":"https://www.marinelink.com/news/imo-adopts-global-code-autonomous-ships-539519"},{"code":"DIG","title":"MASS 코드 채택 — 자율운항선이 설계도에서 규제 현실로","src":"gCaptain","date":"2026-07-01","kSum":"gCaptain은 MASS 코드 채택으로 자율운항선이 개념 단계를 벗어나 규제 대상 현실이 됐다고 평가했다. 코드는 원격운영센터(ROC) 통합, 연결성, 사이버보안, 항해안전, 기관 시스템, 당직, 수색구조 의무를 포괄한다.","eSum":"gCaptain assesses that with the MASS Code's adoption the autonomous ship has moved from drawing board to regulated reality, covering ROC integration, connectivity, cyber security, navigation safety, machinery, watchkeeping and SAR duties.","kImp":"ROC 인력의 자격·당직 요건이 향후 선원 조직 설계의 핵심 변수가 된다.","eImp":"ROC staffing and watchkeeping requirements become a key variable in future crewing design.","url":"https://gcaptain.com/imo-adopts-mass-code-the-autonomous-ship-moves-from-drawing-board-to-regulated-reality/"},{"code":"DIG","title":"말링크, Stellar Cyber와 제휴로 해상 사이버 방어 강화","src":"Splash247","date":"2026-07-07","kSum":"말링크(Marlink)가 Stellar Cyber의 AI 기반 네트워크 탐지·대응(NDR) 기술을 보안운영 플랫폼에 통합했다. 해운을 포함한 원격 산업의 사이버 회복력 강화를 목표로 한다.","eSum":"Marlink has integrated Stellar Cyber's AI-driven network detection and response technology into its security operations platform to strengthen cyber resilience across shipping and other remote industries.","kImp":"연결성 공급자가 보안까지 번들로 제공하는 방향으로 시장이 재편되고 있다.","eImp":"The market is consolidating toward connectivity providers bundling security.","url":"https://splash247.com/marlink-boosts-maritime-cyber-defences-through-stellar-cyber-tie-up/"},{"code":"DIG","title":"AI로 설계한 해상풍력 지원선, 연료 소모·배출 대폭 절감","src":"Splash247","date":"2026-07-03","kSum":"AI 기반 선형 최적화로 설계된 해상풍력 지원선이 기존 대비 연료 소모와 배출을 크게 줄일 것으로 기대된다. 생성형 설계가 조선 초기 단계에 적용된 사례다.","eSum":"An AI-designed offshore wind support vessel is projected to sharply cut fuel burn and emissions, demonstrating generative design applied at the early naval architecture stage.","kImp":"AI 설계는 운항 최적화보다 상류 단계에서 더 큰 효율 개선 여지를 제공한다.","eImp":"AI design offers larger efficiency gains upstream than voyage optimisation does downstream.","url":"https://splash247.com/ai-designed-offshore-wind-vessel-to-slash-fuel-burn-and-emissions/"},{"code":"DIG","title":"표적형 사이버 공격 위협 고조","src":"Riviera Maritime Media","date":"2026-07-06","kSum":"해운을 겨냥한 표적형 사이버 공격이 늘고 있으며, 스타링크 등 상시 연결 환경이 공격 표면을 넓히고 있다는 분석이다. 랜섬웨어와 공급망 침투가 주요 위협으로 지목됐다.","eSum":"Riviera reports a rising threat of targeted cyber attacks on shipping, with always-on connectivity such as Starlink widening the attack surface; ransomware and supply-chain intrusion are highlighted as primary vectors.","kImp":"IACS UR E26/E27 대응만으로는 표적형 공격 방어에 불충분하다.","eImp":"IACS UR E26/E27 compliance alone is insufficient against targeted attacks.","url":"https://www.rivieramm.com/expert-views/expert-views/the-heightened-threat-of-targeted-cyber-attacks"},{"code":"DIG","title":"디지털 트윈: 자동화로 가는 항로를 그리다","src":"Seatrade Maritime","date":"2026-07-06","kSum":"통합 데이터 루프로 구동되는 디지털 트윈이 해운 자율화 진전의 핵심이 될 것이라는 분석이다. 선박·기자재 가상 모델로 성능 감시와 정비 예측이 이뤄지며 고장·다운타임 감소와 자산 수명 연장 효과가 확인되고 있다.","eSum":"Seatrade argues the digital twin, fuelled by an integrated data loop, will be key to advancing autonomy; virtual models of ships and components are already cutting breakdowns and downtime while extending asset life.","kImp":"디지털 트윈은 자율운항의 전제이자 예측정비의 실질적 수익원이다.","eImp":"Digital twins are both a prerequisite for autonomy and a real payback source via predictive maintenance.","url":"https://www.seatrade-maritime.com/technology/digital-twin-plotting-course-automation"}]},{"code":"TECH","type":"news","kTitle":"Section 8. 선박관리 기술","eTitle":"Section 8. Ship Manager Technical","items":[{"code":"TECH","title":"WinGD, 암모니아 엔진 시험 진전 — X52DF-A 공장인수시험 완료","src":"The Motorship","date":"2026-07-06","kSum":"WinGD가 암모니아 2행정 엔진의 추가 공장인수시험(FAT)을 완료했다. 위차이 마린파워(YCMP)가 제작한 X52DF-A-1.0 엔진이 중국선급(CCS) 입회 하에 2026년 4월 시험을 거쳤다.","eSum":"WinGD has completed another factory acceptance test for its ammonia-fuelled two-stroke engine; the X52DF-A-1.0 built by Yuchai Marine Power was trialled in April 2026 under China Classification Society supervision.","kImp":"암모니아 엔진의 상업 공급망이 중국 라이선시까지 확장되며 납기 리스크가 완화된다.","eImp":"Extension of the ammonia engine supply chain to Chinese licensees eases delivery risk.","url":"https://www.motorship.com/alternative-fuels-and-lubricants/wingd-advances-ammonia-engine-testing/1509294.article"},{"code":"TECH","title":"크루즈선, 비용 효율적 수처리 설비 레트로핏","src":"The Motorship","date":"2026-07-02","kSum":"크루즈선에 비용 효율적인 수처리(water treatment) 설비를 레트로핏한 사례가 소개됐다. 제한된 기관실 공간에서의 배치와 설치 공기 단축이 핵심 과제로 지적됐다.","eSum":"The Motorship details a cruise ship retrofit for cost-effective water treatment, highlighting layout within constrained machinery spaces and shortened installation time as the core challenges.","kImp":"공간 제약은 레트로핏 프로젝트에서 가장 흔한 실패 요인이다.","eImp":"Space constraint remains the most common failure factor in retrofit projects.","url":"https://www.motorship.com/cruise-retrofit-for-cost-effective-water-treatment/993396.article"},{"code":"TECH","title":"WinGD, 최초 에탄올 2행정 엔진 2026년 출시 예고","src":"Riviera Maritime Media","date":"2026-06-30","kSum":"WinGD가 최초의 에탄올 연료 2행정 엔진을 2026년 시장에 내놓고, 신조 및 레트로핏 인도는 2027년부터 시작한다고 밝혔다. Everllence도 90보어 ME-LGIM 엔진에서 전 부하 에탄올 시험에 성공한 바 있다.","eSum":"WinGD says it will bring its first ethanol-fuelled two-stroke engine to market in 2026, with newbuild and retrofit deliveries from 2027; Everllence has separately tested ethanol at all load points on a 90-bore ME-LGIM.","kImp":"에탄올이 메탄올 엔진 플랫폼의 저비용 대안 연료로 부상하고 있다.","eImp":"Ethanol is emerging as a low-cost alternative fuel on the methanol engine platform.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/wingd-sets-2026-for-launch-of-first-ethanol-two-stroke-marine-engine-86312"},{"code":"TECH","title":"Everllence, 2행정 암모니아 이중연료 엔진 공개 — 상용화 준비","src":"Riviera Maritime Media","date":"2026-07-09","kSum":"Everllence(구 MAN ES)가 2행정 암모니아 이중연료 엔진을 공개하며 상용화 단계 진입을 선언했다. ME-LGIA 초도호기는 2026년 1분기 인도 예정으로, 2025년 1월 100% 부하 운전에 성공한 바 있다.","eSum":"Everllence has unveiled its two-stroke ammonia dual-fuel engine, declaring it ready for prime time; the first ME-LGIA unit is due for handover in Q1 2026 after achieving 100% load running in January 2025.","kImp":"암모니아 추진 신조 발주의 기술적 병목이 해소 국면에 들어섰다.","eImp":"The technical bottleneck for ammonia newbuild ordering is easing.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/ready-for-prime-time-everllence-to-unveil-two-stroke-ammonia-dual-fuel-engine-86763"},{"code":"TECH","title":"탱커 수리조선소, 레트로핏 물량 급증","src":"Riviera Maritime Media","date":"2026-07-07","kSum":"환경 규제 대응 수요로 탱커 수리조선소에 레트로핏 물량이 몰리고 있다. 배기가스 세정장치와 밸러스트수 처리설비 동시 설치 수요가 증가하며 도크 슬롯 확보 경쟁이 심화됐다.","eSum":"Tanker repair yards are seeing a flurry of retrofit activity driven by environmental compliance, with rising demand for concurrent exhaust gas cleaning and ballast water treatment installations tightening dock slot availability.","kImp":"도크 슬롯 부족은 계획 정비 일정을 최소 1~2분기 앞당겨 예약할 것을 요구한다.","eImp":"Dock slot scarcity requires booking planned maintenance one to two quarters earlier.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/tanker-repair-yards-experience-a-flurry-of-retrofit-activity-55810"},{"code":"TECH","title":"Everllence, 2행정 암모니아 엔진 해상 데뷔 임박","src":"Offshore Energy","date":"2026-07-10","kSum":"Everllence의 2행정 암모니아 엔진이 실선 데뷔를 앞두고 있다. 초도 ME-LGIA 유닛의 인도와 베딩인(bedding-in) 일정이 확정되며 실운항 검증 단계로 진입한다.","eSum":"Everllence's two-stroke ammonia engine is poised for its maritime debut, with the first ME-LGIA unit's handover and bedding-in scheduled, moving it into in-service validation.","kImp":"기술팀은 암모니아 독성 대응 절차와 선원 훈련을 지금부터 준비해야 한다.","eImp":"Technical teams should begin preparing ammonia toxicity procedures and crew training now.","url":"https://www.offshore-energy.biz/everllence-two-stroke-ammonia-engine-poised-for-maritime-debut/"},{"code":"TECH","title":"MAN·바르질라, 탈탄소 겨냥 신형 엔진 출시","src":"Offshore Energy","date":"2026-07-03","kSum":"MAN과 바르질라가 탈탄소를 겨냥한 신형 엔진 라인업을 공개했다. 두 업체 모두 암모니아 엔진 수주잔고를 쌓아가고 있다.","eSum":"MAN and Wartsila have rolled out new engines targeting decarbonisation, with both builders accumulating order books for ammonia-capable units.","kImp":"엔진 선택지 확대로 신조 사양 확정 시점을 늦출 여지가 생겼다.","eImp":"A wider engine menu gives owners room to defer newbuild specification decisions.","url":"https://www.offshore-energy.biz/man-wartsila-roll-out-new-engines-targeting-decarbonization/"},{"code":"TECH","title":"MAN, 암모니아 2행정 엔진 최초 전부하 시험 착수","src":"Maritime Executive","date":"2026-07-08","kSum":"MAN이 암모니아 2행정 엔진의 최초 전규모(full-scale) 시험에 착수했다. 상용 암모니아 추진 실현의 핵심 이정표로 평가된다.","eSum":"MAN has begun the first full-scale tests of its ammonia two-stroke engine, a milestone regarded as central to realising commercial ammonia propulsion.","kImp":"전부하 시험 결과는 암모니아 선박 발주 의사결정의 최종 관문이다.","eImp":"Full-scale test results are the final gate for ammonia newbuild ordering decisions.","url":"https://maritime-executive.com/article/milestone-as-man-starts-first-full-scale-tests-of-ammonia-two-stroke-engine"},{"code":"TECH","title":"ShipParts.com, 예비품 온디맨드 3D 프린팅 검토","src":"Maritime Executive","date":"2026-07-06","kSum":"ShipParts.com이 예비품 온디맨드 3D 프린팅 도입을 검토 중이다. 기관 고장 시 OEM 중앙창고 배송 대신 차항에서 부품을 제작해 지연을 줄이고, 밸브·관 피팅·임펠러 등 소형 부품은 선상 제작도 가능하다.","eSum":"ShipParts.com is exploring on-demand 3D printing for spares, which could let parts be produced at the next port rather than shipped from an OEM central warehouse, with small items such as valves, pipe fittings and impellers potentially printed onboard.","kImp":"적층제조는 예비품 재고비용과 기관 고장 다운타임을 동시에 줄일 수 있다.","eImp":"Additive manufacturing can cut both spares inventory cost and breakdown downtime.","url":"https://maritime-executive.com/corporate/shipparts-com-explores-on-demand-3d-printing-for-spares"},{"code":"TECH","title":"MSC, 바르질라 간편 전환형 2행정 엔진 시험 참여","src":"Seatrade Maritime","date":"2026-07-07","kSum":"MSC가 바르질라의 전환이 쉬운(convertible) 2행정 엔진 시험에 참여한다. 기존 엔진을 향후 대체연료로 개조할 수 있도록 설계돼 자산 좌초 리스크를 줄이는 개념이다.","eSum":"MSC is taking part in a trial of Wartsila's easy convertible two-stroke engine, designed so existing engines can later be converted to alternative fuels, reducing stranded-asset risk.","kImp":"전환 가능 엔진은 연료 불확실성 시대의 실질적 헤지 수단이다.","eImp":"Convertible engines are a practical hedge in an era of fuel uncertainty.","url":"https://www.seatrade-maritime.com/shipyards/msc-in-trial-of-wartsila-easy-convertible-two-stroke-engine"},{"code":"TECH","title":"ASRY, VLCC 스크러버 레트로핏 33일 만에 완료","src":"Seatrade Maritime","date":"2026-07-01","kSum":"바레인 ASRY 조선소가 VLCC 스크러버 레트로핏을 33일 만에 완료했으며, 밸러스트수 처리설비(BWTS) 설치도 동시에 진행했다. 일반적 스크러버 설치 공기는 21~28일 수준이다.","eSum":"Bahrain's ASRY completed a VLCC scrubber retrofit in 33 days, carried out concurrently with a ballast water treatment system installation; typical scrubber retrofits take 21-28 days.","kImp":"동시 시공은 도크 기간과 기회비용을 줄이는 가장 확실한 방법이다.","eImp":"Concurrent installation is the surest way to cut dock time and opportunity cost.","url":"https://www.seatrade-maritime.com/tankers/asry-completes-vlcc-scrubber-retrofit-in-33-days"},{"code":"TECH","title":"전 선종 대상 배기·수처리 레트로핏 솔루션 확대","src":"SAFETY4SEA","date":"2026-07-02","kSum":"모든 선종에 적용 가능한 배기가스 세정 및 수처리 레트로핏 솔루션이 제공되고 있다. 턴키 레트로핏 비용은 기자재 40%, 설치 40%, 엔지니어링·PM·물류·선급승인 20% 구조로 알려졌다.","eSum":"Retrofit solutions for exhaust gas and water cleaning are now available across all ship types; as a rule of thumb turnkey retrofit cost splits 40% equipment, 40% installation and 20% engineering, project management, logistics and class approval.","kImp":"레트로핏 견적 검토 시 비기자재 비용 60%를 과소평가하지 말아야 한다.","eImp":"When reviewing retrofit quotes, do not underestimate the 60% of cost that is not equipment.","url":"https://safety4sea.com/retrofit-solutions-for-exhaust-gas-and-water-cleaning-available-across-all-ship/"}]},{"code":"HR","type":"news","kTitle":"Section 9. 해기인력·선원","eTitle":"Section 9. Marine HR","items":[{"code":"HR","title":"선원 최저임금 3년간 6.2% 인상 합의","src":"Maritime Executive","date":"2026-06-30","kSum":"선주와 선원노조가 IBF를 통해 2026년 1월 1일부터 2028년 1월 1일까지 3년간 월 최저임금을 6.2% 인상하기로 합의했다. 월 673달러에서 715달러로 오른다.","eSum":"Shipowners and seafarer unions agreed through the IBF to a 6.2% rise in the monthly minimum wage over three years from 1 Jan 2026 to 1 Jan 2028, from $673 to $715 per month, reflecting cost-of-living increases since 2022.","kImp":"선원비 인상은 선주의 운항원가에 직접 반영되며, 3년 예측 가능한 인상폭은 예산 수립에 활용할 수 있다.","eImp":"Crew cost rises feed directly into owners' operating costs; a three-year visible escalation aids budgeting.","url":"https://www.maritime-executive.com/article/seafarers-win-6-wage-increase-over-three-years-despite-trade-uncertainties"},{"code":"HR","title":"IBF, 2026-2027년 선원 임금 인상안 타결","src":"Nautilus International","date":"2026-06-25","kSum":"국제교섭포럼(IBF)이 2026년 3.5%, 2027년 추가 1.5%의 임금 및 보상 인상에 합의했다. ITF-IBF 단체협약이 적용되는 선박에 승선한 사관과 부원 모두에게 적용된다.","eSum":"The International Bargaining Forum agreed a 3.5% increase in wages and compensation in 2026 plus a further 1.5% in 2027, applying to officers and ratings on vessels covered by ITF-IBF collective bargaining agreements.","kImp":"ITF-IBF CBA 적용 선박의 선원비 산정 기준이 확정되어 2026-2027년 인력 예산의 불확실성이 축소된다.","eImp":"Fixes the crew-cost baseline for ITF-IBF CBA vessels, reducing manning budget uncertainty for 2026-2027.","url":"https://www.nautilusint.org/en/news-insight/news/international-bargaining-forum-agrees-2026-2027-pay-rise-for-seafarers/"},{"code":"HR","title":"IBF 합의로 선원 25만명 임금·근로조건 개선","src":"Nautilus International","date":"2026-06-24","kSum":"IBF 합의는 전 세계 약 25만명의 선원에게 적용되며 임금 인상과 함께 근로조건 개선을 담고 있다. 해사노동협약(MLC)상 핵심노동자 지위 인정도 포함됐다.","eSum":"The IBF deal covers around 250,000 seafarers globally, securing better pay alongside improved conditions, including recognition of key worker status under the Maritime Labour Convention.","kImp":"MLC 핵심노동자 지위 인정은 향후 위기 시 승하선 보장의 법적 근거로 작용할 수 있다.","eImp":"Key worker recognition under MLC provides a legal basis for guaranteed crew change in future crises.","url":"https://www.nautilusint.org/en/news-insight/news/ibf-deal-secures-better-pay-and-conditions-for-250000-seafarers/"},{"code":"HR","title":"선원 임금, 선원 우위 시장에서 지속 상승","src":"Splash247","date":"2026-06-20","kSum":"선원 공급 부족이 이어지면서 선원이 협상 우위를 갖는 시장이 형성됐고 임금은 계속 오르고 있다. 선주·선박관리사의 사내 크루 매니저 약 90%가 급여를 인상했다고 답했다.","eSum":"With crew supply tight, a crew-led market has emerged and salaries keep rising. Almost 90% of in-house crew managers at shipowners and shipmanagers reported raising salaries.","kImp":"선원 우위 시장이 고착되면 선원비 인플레이션이 구조적으로 지속되어 운항예산 상향이 불가피하다.","eImp":"A persistent crew-led market makes manning cost inflation structural, forcing upward revision of operating budgets.","url":"https://splash247.com/seafarer-salaries-still-rising-in-a-crew-led-market/"},{"code":"HR","title":"사관 부족, 2030년까지 10만명 초과 위험","src":"Splash247","date":"2026-06-18","kSum":"현재 사관 부족은 약 39,100명으로 추정되며 부원은 56,890명 과잉이다. 2030년 사관 수요는 116만명에 달해 매년 22,747명의 신규 유입이 필요하지만 부족 규모가 10만명을 넘을 위험이 있다.","eSum":"The current officer shortfall is estimated at 39,100 while ratings show a surplus of 56,890. By 2030 officer demand reaches 1.16m, requiring 22,747 new officers annually, with the shortage risking exceeding 100,000.","kImp":"사관 부족 심화는 배승 지연과 인건비 상승을 동시에 유발하므로 자체 양성·유지 프로그램 투자가 필요하다.","eImp":"Deepening officer shortages drive both manning delays and cost inflation, justifying investment in in-house cadet and retention programmes.","url":"https://splash247.com/officer-shortage-risks-exceeding-100000-by-2030/"},{"code":"HR","title":"선원 노동시장 경색, 사상 최고 수준 기록","src":"Splash247","date":"2026-06-15","kSum":"선원 노동시장 경색도가 기록상 최고 수준에 도달했다. 사관 공급 부족이 사상 최고치를 기록했으며 단기간 내 개선 가능성이 낮아 배승비 인플레이션으로 이어지고 있다.","eSum":"Seafarer labour market tightness has hit the highest level on record. Officer supply shortage is at an all-time high and unlikely to improve, resulting in manning cost inflation.","kImp":"노동시장 경색 지표가 최고치라는 것은 향후 1-2년 선원 확보 경쟁이 더 치열해짐을 시사한다.","eImp":"Record tightness signals intensifying competition for crew over the next one to two years.","url":"https://splash247.com/seafarer-labour-market-tightness-at-highest-levels-recorded/"},{"code":"HR","title":"NorthStandard, 선원복지에 명확한 측정지표 필요","src":"SAFETY4SEA","date":"2026-07-02","kSum":"NorthStandard는 선원복지가 지속적 개선을 이루려면 더 명확한 측정지표가 필요하다고 지적했다. 선언적 약속을 넘어 측정 가능한 성과 관리로 전환해야 한다는 주장이다.","eSum":"NorthStandard argues crew welfare needs clearer metrics to drive lasting change, moving beyond declaratory commitments to measurable performance management.","kImp":"복지 KPI 체계 도입은 P&I 클럽의 요구사항이 될 수 있어 선제적 지표 설계가 유리하다.","eImp":"Welfare KPIs may become a P&I club expectation, so designing metrics proactively is advantageous.","url":"https://safety4sea.com/cm-northstandard-crew-welfare-needs-clearer-metrics-to-drive-lasting-change/"},{"code":"HR","title":"호르무즈 해협 피격 선원 3명, 선사 상대 소송 제기","src":"SAFETY4SEA","date":"2026-07-10","kSum":"3월 호르무즈 해협에서 피격된 태국 화물선의 전 선원 3명이 7월 10일 선사와 선장을 상대로 소송을 제기했다. 3월 11일 오만 북방에서 Mayuree Naree호가 피격돼 3명이 사망했고, 생존 선원들은 PTSD 진단을 받아 승선 복귀가 불가능한 상태다.","eSum":"Three former crew of a Thai cargo vessel attacked in the Strait of Hormuz in March filed suit on 10 July against Precious Shipping Co. and the master. The Mayuree Naree was struck by a projectile north of Oman on 11 March, killing three. Survivors are diagnosed with PTSD and reportedly unable to return to seafaring.","kImp":"분쟁수역 항해 시 선원의 정신적 피해에 대한 선사 책임이 법정에서 다뤄지는 선례로, 위험구역 운항 정책 재검토가 필요하다.","eImp":"A precedent testing owner liability for crew psychological harm in conflict zones; high-risk area transit policies warrant review.","url":"https://safety4sea.com/seafarers-sue-shipping-company-over-deadly-strait-of-hormuz-attack/"},{"code":"HR","title":"선원 유지율 문제 해결의 실마리","src":"Splash247","date":"2026-06-10","kSum":"임금 인상에도 불구하고 선박관리사의 10곳 중 4곳만이 선원 유지 개선을 보고했다. 신세대 사관·부원에게 충성심은 급여명세서가 아니라 인정받고 지원받으며 연결되는 경험에서 나온다는 분석이다.","eSum":"Despite wage rises, only four in ten shipmanagers report any improvement in crew retention. For a new generation of officers and ratings, loyalty comes not from a payslip but from being seen, supported and connected.","kImp":"임금 인상만으로 유지율이 개선되지 않는다는 점은 커리어패스·연결성 등 비금전적 요인 투자의 필요성을 시사한다.","eImp":"Pay alone is not lifting retention, indicating a need to invest in non-monetary factors such as career paths and connectivity.","url":"https://splash247.com/how-to-crack-the-seafarer-retention-riddle/"},{"code":"HR","title":"해사 인재육성 프로그램으로 선원난 대응","src":"SAFETY4SEA","date":"2026-06-22","kSum":"해사 인재육성 프로그램(Maritime Talent Development Program)이 선원 위기 대응책으로 제시됐다. 2026년 부족률은 9~11%로 추정되며, 실질적 조치가 없으면 2030년 12%에 근접할 수 있다는 전망이다.","eSum":"A Maritime Talent Development Program is proposed to navigate the crew crisis. The 2026 shortage is estimated at 9-11%, potentially approaching 12% by 2030 without substantial action.","kImp":"부족률이 두 자릿수에 근접하는 구조적 추세로, 장기 인재 파이프라인 구축이 단기 채용보다 중요해진다.","eImp":"With shortfall trending toward double digits, building a long-term talent pipeline outweighs short-term recruitment.","url":"https://safety4sea.com/cm-maritime-talent-development-program-navigating-the-crew-crisis/"}]},{"code":"HSEQ","type":"news","kTitle":"Section 10. HSEQ·손해방지","eTitle":"Section 10. HSEQ","items":[{"code":"HSEQ","title":"Gard 선원클레임 리포트 2026: 부상 대부분 일상 작업 중 발생","src":"Gard","date":"2026-07-01","kSum":"Gard가 2025년 약 3,000건의 P&I 선원클레임과 약 400건의 부상 사례 심층 분석을 담은 2026 선원클레임 리포트를 발간했다. 부상의 대부분이 일상적 작업 중 발생하며 경험 많은 선원이 자주 연루된다. 승선 첫 3개월, 특히 첫 1개월의 부상 위험이 높고 08:00~10:00에 부상이 집중된다.","eSum":"Gard published its 2026 Crew Claims Report drawing on around 3,000 P&I crew claims from 2025 including in-depth review of some 400 injury cases. Most injuries occur during routine work and frequently involve experienced seafarers. The first three months onboard, especially the first month, carry elevated risk, with injuries concentrated between 08:00 and 10:00.","kImp":"승선 초기 및 오전 작업시간대 집중 관리, 일상작업 리스크 재평가가 부상 저감의 핵심 개입 지점이다.","eImp":"Targeted controls in the early onboard period and morning work window, plus reassessment of routine-task risk, are the key intervention points.","url":"https://www.gard.no/en/about-gard/company-news/gard-crew-claims-report-2026-most-seafarer-injuries-happen-during-routine-work/"},{"code":"HSEQ","title":"NorthStandard, 2026 PSC 집중점검 대비 화물고박 안내","src":"NorthStandard","date":"2026-07-03","kSum":"NorthStandard가 2026년 PSC 집중점검(CIC) 주제인 화물고박에 대비한 안내를 발표했다. 고박장치 상태, 화물고박매뉴얼(CSM) 준수, 승무원 숙지도가 주요 점검 포인트로 지목됐다.","eSum":"NorthStandard issued guidance on cargo securing in preparation for the 2026 PSC Concentrated Inspection Campaign, highlighting lashing equipment condition, Cargo Securing Manual compliance and crew familiarity as key inspection focus areas.","kImp":"CIC 시행 전 고박장치 점검 및 CSM 갱신을 완료하지 않으면 출항정지 위험이 커진다.","eImp":"Failure to verify lashing gear and update the CSM before the CIC materially raises detention risk.","url":"https://north-standard.com/insights-and-resources/resources/articles/cargo-securing-in-focus-preparing-for-the-2026-psc-cic"},{"code":"HSEQ","title":"Gard: 곡물코드 개정 진행 중, 준비됐는가","src":"Gard","date":"2026-06-30","kSum":"Gard는 국제 곡물코드(Grain Code) 개정이 진행 중이라며 선사의 대비를 촉구했다. 곡물 적재 시 복원성 계산과 트리밍 요건 변화가 예상되어 관련 절차와 승인문서 갱신이 필요하다.","eSum":"Gard flags that the international Grain Code is being revised and urges owners to prepare. Changes to stability calculations and trimming requirements for grain loading are expected, requiring updates to procedures and approval documents.","kImp":"곡물선 운항사는 개정 발효 전 곡물적재 승인서와 복원성 자료 갱신 일정을 미리 확보해야 한다.","eImp":"Grain trade operators should schedule renewal of grain loading approvals and stability data ahead of entry into force.","url":"https://gard.no/insights/the-grain-code-is-being-revised-are-you-ready/"},{"code":"HSEQ","title":"NorthStandard, 손해방지 파트너십 확대 — Orca AI 도입 보조금","src":"NorthStandard","date":"2026-06-28","kSum":"NorthStandard가 견조한 실적과 전략적 성장을 발표하면서 손해방지 파트너십을 확대했다. Orca AI 상황인식 시스템 도입 선사에 선지급 보조금을 제공하며, Orca AI 운용 선박은 고위험 근접조우가 52% 감소한 것으로 나타났다.","eSum":"NorthStandard reported strong results and strategic momentum, expanding loss prevention partnerships including an upfront subsidy for Members adopting Orca AI situational awareness. Vessels operating with Orca AI show a 52% reduction in high-severity close encounters.","kImp":"P&I 클럽 보조금을 활용한 상황인식 기술 도입은 충돌 리스크와 보험료를 동시에 낮출 수 있는 기회다.","eImp":"Club-subsidised situational awareness technology offers a route to cut both collision risk and premium exposure.","url":"https://north-standard.com/insights-and-resources/resources/press-releases/northstandard-reports-strong-results-and-strategic-momentum"},{"code":"HSEQ","title":"밀폐구역 사망사고, 서류작업 늘린다고 끝나지 않는다","src":"Splash247","date":"2026-06-24","kSum":"밀폐구역 진입 사망사고가 절차서와 체크리스트 확대만으로는 근절되지 않는다는 비판이 제기됐다. 2000~2024년 1,010명 이상의 선상·육상 작업자가 밀폐구역에서 사망했으며, 시간압박·훈련 편차·의사소통 공백이 근본 원인으로 지목된다.","eSum":"Critics argue enclosed space deaths will not end with more paperwork. Over 1,010 ship and shore workers died in enclosed spaces between 2000 and 2024, with time pressure, inconsistent training and communication gaps identified as root causes.","kImp":"절차 추가보다 시간압박 해소와 실기 훈련 강화가 실질적 사망사고 저감에 직결된다.","eImp":"Relieving time pressure and strengthening practical drills matter more than adding procedures for cutting fatalities.","url":"https://splash247.com/enclosed-space-deaths-wont-end-with-more-paperwork/"},{"code":"HSEQ","title":"사례연구: 밀폐구역 진입 후 2명 사망","src":"SAFETY4SEA","date":"2026-06-19","kSum":"밀폐구역 진입 사고로 2명이 사망한 사례가 분석됐다. 밀폐구역 사고 사망자의 50% 이상이 동료를 구조하려다 발생한다는 점이 재확인됐다. 2022년과 2023년 각각 14건의 밀폐구역 사고가 기록됐으나 사망자는 18명에서 34명으로 급증했다.","eSum":"A case study analyses a double fatality following enclosed space entry. Over 50% of those who die in enclosed space accidents do so attempting to rescue co-workers. Both 2022 and 2023 recorded 14 enclosed space incidents, yet casualties rose sharply from 18 to 34.","kImp":"구조자 2차 사망이 지배적 패턴이므로 비상대응 훈련에서 진입 금지 원칙을 최우선으로 교육해야 한다.","eImp":"Rescuer secondary fatalities dominate, so emergency drills must prioritise the do-not-enter principle.","url":"https://safety4sea.com/case-study-double-fatality-after-enclosed-space-entry/"},{"code":"HSEQ","title":"USCG, MODU 밀폐구역 3명 사망 후 안전경보 발령","src":"IIMS","date":"2026-06-17","kSum":"미국 해안경비대(USCG)가 시추설비(MODU) 밀폐구역에서 3명이 질식 사망한 사고 후 안전경보를 발령했다. 진입 전 가스측정과 허가 절차 미비가 지적됐다.","eSum":"The US Coast Guard issued a Safety Alert on confined space entry dangers after three people were asphyxiated in a confined space on a drilling rig (MODU), citing shortcomings in pre-entry gas testing and permit procedures.","kImp":"USCG 경보는 미국 입항 선박의 밀폐구역 절차 점검 강화로 이어질 수 있어 사전 대비가 필요하다.","eImp":"The USCG alert may prompt tighter scrutiny of enclosed space procedures on vessels calling at US ports.","url":"https://www.iims.org.uk/uscg-publishes-a-safety-alert-after-three-confined-space-fatalities-on-a-modu/"},{"code":"HSEQ","title":"구명정 사고: 주요 관찰사항과 교훈","src":"IIMS","date":"2026-06-15","kSum":"구명정 관련 사고의 주요 관찰사항과 교훈이 정리됐다. 온로드 릴리즈 후크 오작동, 정비 미흡, 훈련 중 사고가 반복되는 패턴으로 확인됐다. 바하마 해사청은 구명정 진수용 질소실린더 축압 시스템의 심각한 위험에 대해 안전경보를 발령한 바 있다.","eSum":"Key observations and lessons from lifeboat incidents were compiled, identifying recurring patterns of on-load release hook malfunction, poor maintenance and accidents during drills. The Bahamas Maritime Authority has issued a safety alert on serious risk from nitrogen cylinder stored kinetic energy systems used for launching lifeboats.","kImp":"질소실린더 진수시스템 탑재 선박은 바하마 경보 대상 여부를 즉시 확인하고 정비이력을 점검해야 한다.","eImp":"Vessels with nitrogen cylinder launch systems should immediately verify applicability of the Bahamas alert and audit maintenance records.","url":"https://www.iims.org.uk/lifeboat-incidents-key-observations-lessons-learned/"},{"code":"HSEQ","title":"IUMI, 컨테이너선 화재안전 조치 촉구","src":"Maritime Executive","date":"2026-06-12","kSum":"국제해상보험연맹(IUMI)이 컨테이너선 화재안전에 대한 조치를 촉구했다. 미신고 위험물과 대형선의 소화 한계가 주요 우려로 제기됐다.","eSum":"The International Union of Marine Insurance called for action on container ship fire safety, raising undeclared dangerous goods and firefighting limitations on large vessels as principal concerns.","kImp":"보험자 측 압박이 커지면 컨테이너선 화재 관련 인수조건과 보험료에 영향을 미칠 수 있다.","eImp":"Growing underwriter pressure may affect container ship fire-related terms and premiums.","url":"https://maritime-executive.com/article/iumi-calls-for-action-on-container-ship-fire-safety"},{"code":"HSEQ","title":"아조프해 드론 공격으로 선박 4척 피해·선원 1명 사망","src":"SAFETY4SEA","date":"2026-07-11","kSum":"7월 11일 아조프해 타간로그만에서 드론 공격으로 선박 4척이 피해를 입고 선원 1명이 사망했다.","eSum":"One seafarer was killed after a drone attack struck four vessels in Taganrog Bay in the Sea of Azov on 11 July.","kImp":"흑해·아조프해 항로의 전쟁위험 등급과 선원 안전 조치 재검토가 필요하다.","eImp":"War risk grading and crew protection measures for Black Sea and Azov routes require review.","url":"https://safety4sea.com/drone-attack-damages-four-vessels-leaving-one-seafarer-dead-in-sea-of-azov/"},{"code":"HSEQ","title":"신조 Maersk 컨테이너선, 인도 연안서 폭발·화재로 사망자 발생","src":"Riviera Maritime Media","date":"2026-07-08","kSum":"신조 컨테이너선 Maersk Frankfurt호가 아라비아해 항해 중 폭발과 화재를 일으켰다. 파나마 해사청 발표에 따르면 최소 1명이 사망했으며 시신은 화염으로 접근 불가능한 래싱브리지에 있었다. 인도 해안경비대가 뉴망갈로르 남서 50해리 해상에서 진화·방제작업을 이어갔다.","eSum":"The newly built container ship Maersk Frankfurt suffered an explosion and fire while navigating the Arabian Sea. The Panama Maritime Authority confirmed at least one death, the body located in the lashing bridge and unreachable because of flames. The Indian Coast Guard continued firefighting and pollution prevention 50 nautical miles southwest of New Mangalore.","kImp":"신조선에서도 대형 화재가 발생한다는 점은 화물 신고 정확성과 초기 진화 역량이 선령과 무관한 리스크임을 보여준다.","eImp":"A major fire on a newbuilding shows that cargo declaration accuracy and early firefighting capability are risks independent of vessel age.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/newly-built-maersk-box-ship-suffers-deadly-explosion-and-fire-near-indian-coast-81655"},{"code":"HSEQ","title":"Gard 안전경보: 블랙아웃 시 비상전원 시스템은 작동할 것인가","src":"Gard","date":"2026-07-09","kSum":"Gard가 블랙아웃 상황에서의 비상전원 시스템 신뢰성 문제를 다룬 안전경보를 발행했다. 비상발전기 자동기동 실패와 정기 시험 미비가 반복 지적됐다.","eSum":"Gard published a safety alert on emergency power system reliability during blackout situations onboard ships, citing recurring failures of emergency generators to auto-start and gaps in routine testing.","kImp":"비상전원 미작동은 블랙아웃을 통제 불능 사고로 확대시키는 핵심 요인이다.","eImp":"Emergency power failure is a key escalation factor turning a blackout into an uncontrolled casualty.","url":"https://www.gard.no/en/insights/emergency-power-system-in-blackout/"}]},{"code":"KR","type":"news","kTitle":"Section 11. 한국 해운시장","eTitle":"Section 11. Korean Shipping Market","items":[{"code":"KR","title":"팬오션, 베이하이조선에 VLCC 2척 추가 발주","src":"더구루","date":"2026-07-13","kSum":"팬오션이 중국 베이하이조선에 초대형원유운반선(VLCC) 2척을 추가 발주했다. SK해운 VLCC 사업부 인수에 이어 유조선 선대 확대에 속도를 내는 모습이다.","eSum":"Pan Ocean placed an additional order for two VLCCs at China's Beihai Shipbuilding, accelerating tanker fleet expansion following its acquisition of SK Shipping's VLCC business division.","kImp":"팬오션의 탱커 부문 확장은 벌크 편중 포트폴리오의 다각화 전략으로, 국적선사 유조선 선대 경쟁 구도에 변화를 예고한다.","eImp":"Pan Ocean's tanker expansion diversifies a bulk-heavy portfolio and signals a shift in the Korean tanker fleet landscape.","url":"https://www.theguru.co.kr/news/article.html?no=104161"},{"code":"KR","title":"부산항 운영사 통합 추진","src":"한국해운신문","date":"2026-07-10","kSum":"부산항 터미널 운영사 통합이 추진되고 있다. 운영사 난립에 따른 과당경쟁과 물량 분산 문제를 해소하고 항만 경쟁력을 높이기 위한 조치로 풀이된다.","eSum":"Consolidation of Busan Port terminal operators is being pursued, aimed at resolving excessive competition and cargo fragmentation caused by operator proliferation and improving port competitiveness.","kImp":"운영사 통합은 부산항 기항 선사의 터미널 협상력과 하역요율 구조에 직접적 영향을 미친다.","eImp":"Operator consolidation directly affects terminal negotiating leverage and stevedoring rate structures for lines calling Busan.","url":"http://www.maritimepress.co.kr/news/articleView.html?idxno=324935"},{"code":"KR","title":"HD현대·삼성중공업 연간 수주 목표 70% 돌파","src":"한국일보","date":"2026-07-13","kSum":"HD현대중공업이 약 6개월 만에 연간 수주 목표 233억1,000만 달러의 70.3%를 달성했다. HD한국조선해양은 유럽 선주와 초대형 암모니아운반선(VLAC) 3척 계약을 체결했고 올해 142척 163억9,000만 달러를 수주했다. 삼성중공업은 연간 목표 139억 달러의 72%를 채워 누적 수주액 100억 달러를 넘어섰다.","eSum":"HD Hyundai Heavy Industries reached 70.3% of its annual order target of $23.31bn in about six months. HD Korea Shipbuilding signed for three VLACs with a European owner and has booked 142 vessels worth $16.39bn this year. Samsung Heavy filled 72% of its $13.9bn target, passing $10bn cumulative orders.","kImp":"조선 3사의 조기 목표 달성은 선표 여유 축소로 이어져 신조 발주 선사의 인도시기와 선가 협상에 불리하게 작용한다.","eImp":"Early target attainment tightens available slots, weakening owners' leverage on delivery dates and newbuilding prices.","url":"https://www.hankookilbo.com/news/article/A2026071315340005359"},{"code":"KR","title":"캐나다 잠수함 놓친 한화·HD현대, 단기 실적·주가 부담","src":"인베스트조선","date":"2026-07-07","kSum":"한화오션과 HD현대중공업이 캐나다 초계잠수함 프로젝트(CPSP) 수주전에서 독일 티센크루프마린시스템즈(TKMS)에 밀려났다. 60조원 규모 사업 실패로 단기 실적과 주가에 부담이 불가피하다는 분석이다.","eSum":"Hanwha Ocean and HD Hyundai Heavy Industries lost the Canadian Patrol Submarine Project to Germany's TKMS. The failure on the roughly KRW 60tn programme is seen as an unavoidable drag on near-term earnings and share prices.","kImp":"대형 특수선 수주 실패는 한국 조선의 방산 수출 모멘텀 약화를 의미하며 상선 부문 의존도를 높인다.","eImp":"Losing a flagship naval contract weakens Korean yards' defence export momentum and increases reliance on the commercial segment.","url":"https://www.investchosun.com/site/data/html_dir/2026/07/07/2026070780023.html"},{"code":"KR","title":"고려해운, 컨선 운임 반등 베팅해 선박 추가 발주","src":"서울경제","date":"2026-07-09","kSum":"고려해운이 1900TEU급 컨테이너선 6척을 HD현대중공업에 발주했다. 총 4,400억원 규모로 1척당 733억원 수준이며 2028년 6월 인도 완료가 목표다. 고려해운은 선복량 기준 HMM에 이은 국내 2위 해운사다.","eSum":"Korea Marine Transport Co. ordered six 1,900 TEU container ships at HD Hyundai Heavy Industries, worth KRW 440bn in total or about KRW 73.3bn per vessel, with delivery completion targeted for June 2028. KMTC is Korea's second-largest carrier by capacity after HMM.","kImp":"국적 2위 선사의 신조 베팅은 인트라아시아 항로 운임 반등 기대를 반영하며 역내 선복 경쟁 심화를 예고한다.","eImp":"A newbuilding bet by Korea's second-largest carrier reflects expectations of an intra-Asia rate rebound and foreshadows tighter regional capacity competition.","url":"https://www.sedaily.com/article/20012080"},{"code":"KR","title":"컨선만으론 못 버틴다 — 해운업계, 벌크선 강화로 체질 개선","src":"이데일리","date":"2026-07-11","kSum":"컨테이너선 운임 변동성과 공급과잉 우려가 이어지면서 해운업계가 벌크선 강화로 체질 개선에 나섰다. 벌크선은 5~20년 장기계약이 가능해 1년 단위 계약의 컨테이너선 대비 안정적 이익을 기대할 수 있다. HMM은 벌크선 8척과 가스선 2척 등 총 10척, 약 1조6,600억원 규모를 발주했다.","eSum":"Amid container rate volatility and oversupply concerns, Korean carriers are strengthening bulk fleets to rebalance their portfolios. Bulkers allow 5-20 year long-term contracts versus annual container contracts, offering steadier earnings. HMM ordered ten vessels, eight bulkers and two gas carriers, worth about KRW 1.66tn.","kImp":"국적선사의 벌크·에너지선 비중 확대는 컨테이너 사이클 리스크 헤지 전략으로, 장기용선 수요 증가를 시사한다.","eImp":"Korean carriers' shift toward bulk and energy tonnage hedges container cycle risk and points to rising long-term charter demand.","url":"https://edaily.co.kr/News/Read?mediaCodeNo=257&newsId=05015126645486968"},{"code":"KR","title":"한화오션, 8000억 규모 태국 호위함 수주","src":"더구루","date":"2026-06-20","kSum":"60조원 규모 캐나다 잠수함 선정을 앞두고 한화오션이 8,000억원 규모 태국 호위함 사업을 수주했다. 태국 해군이 요구한 기술이전과 현지생산 요건을 가장 안정적으로 충족해 평가에서 최고점을 받았다.","eSum":"Ahead of the Canadian submarine decision, Hanwha Ocean won a KRW 800bn Thai frigate programme, scoring highest in evaluation by most reliably meeting the Royal Thai Navy's technology transfer and local production requirements.","kImp":"기술이전·현지생산 역량이 방산 수주의 결정 변수로 확인되어 향후 동남아 해군 사업 전략의 기준이 된다.","eImp":"Technology transfer and local production capability proved decisive, setting the template for future Southeast Asian naval bids.","url":"https://theguru.co.kr/news/article.html?no=103480"},{"code":"KR","title":"HD현대중공업·한화오션 참여 태국 호위함 사업자 발표 최종 단계","src":"더구루","date":"2026-06-12","kSum":"HD현대중공업과 한화오션이 참여한 태국 호위함 사업의 사업자 발표가 최종 단계에 진입했다. 국내 조선 2사가 동일 사업에 경쟁 참여하는 구도가 형성됐다.","eSum":"The Thai frigate programme, with HD Hyundai Heavy Industries and Hanwha Ocean both bidding, entered the final stage of contractor announcement, with two Korean yards competing on the same project.","kImp":"국내 조선사 간 해외 방산 경쟁은 가격 하락 압력으로 이어질 수 있어 수주 전략 조율 필요성이 제기된다.","eImp":"Head-to-head bidding by Korean yards abroad risks price erosion, raising the case for bid strategy coordination.","url":"https://www.theguru.co.kr/mobile/article.html?no=103236"},{"code":"KR","title":"한화오션, 2026년은 특수선·해양플랜트 수주에 주목해야","src":"쉬핑뉴스넷","date":"2026-07-09","kSum":"한화오션의 2026년은 특수선과 해양플랜트 수주가 핵심 변수로 지목됐다. 한화오션은 상반기에만 43억5,000만 달러를 수주해 지난해 동기 32억2,000만 달러 대비 35.1% 증가했다.","eSum":"Hanwha Ocean's 2026 hinges on naval and offshore plant orders. The yard booked $4.35bn in the first half alone, up 35.1% from $3.22bn in the same period last year.","kImp":"상선 외 특수선·해양 부문 확대는 조선사 수익 변동성을 낮추지만 상선 선표 확보 경쟁에는 부정적이다.","eImp":"Expansion beyond commercial ships into naval and offshore lowers yard earnings volatility but tightens commercial slot availability.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=69948"},{"code":"KR","title":"CJ대한통운·팬오션·대한해운 52주 신고가 — 현대글로비스 주가 급등","src":"쉬핑뉴스넷","date":"2026-07-10","kSum":"지난 한 달간 CJ대한통운, 팬오션, 대한해운이 52주 신고가를 경신했다. 현대글로비스도 주가가 급등하며 전방산업 랠리가 나타났다.","eSum":"Over the past month CJ Logistics, Pan Ocean and Korea Line Corp all set 52-week highs, while Hyundai Glovis surged, producing a rally across the downstream sector.","kImp":"국적 해운·물류주 동반 강세는 시장이 벌크·자동차선 부문의 실적 개선을 선반영하고 있음을 시사한다.","eImp":"A broad rally in Korean shipping and logistics equities suggests the market is pricing in earnings recovery in the bulk and car carrier segments.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=68536"},{"code":"KR","title":"신조 추진 HMM, 中조선 기웃 논란","src":"한국해운신문","date":"2026-07-10","kSum":"HMM이 신조 발주를 추진하면서 중국 조선소를 검토한 데 대한 논란이 제기됐다. 국적선사의 국내 조선 발주 원칙과 원가 경쟁력 사이의 긴장이 부각됐다.","eSum":"Controversy arose over HMM considering Chinese yards for newbuilding orders, highlighting tension between the principle of national carriers ordering domestically and cost competitiveness.","kImp":"국적선사의 중국 발주는 해운·조선 상생 정책과 충돌하며 KOBC 금융지원 조건 논의로 확산될 수 있다.","eImp":"Ordering in China conflicts with the shipping-shipbuilding co-prosperity policy and may spill into debate over KOBC financing conditions.","url":"http://www.maritimepress.co.kr/news/articleView.html?idxno=321651"}]},{"code":"INS","type":"news","kTitle":"Section 12. 해상보험 (H&M)","eTitle":"Section 12. Marine Insurance (H&M)","items":[{"code":"INS","title":"호르무즈, 해상 리스크 프리미엄과 공포심리","src":"Splash247","date":"2026-06-24","kSum":"호르무즈 해협의 리스크 프리미엄이 실제 물리적 위험보다 시장의 공포심리에 의해 과도하게 형성되고 있다는 분석이다. 보험 요율이 사고 통계보다 뉴스 헤드라인에 더 민감하게 반응하고 있다.","eSum":"Analysis argues the Hormuz maritime risk premium is being driven more by market fear than actual physical risk, with insurance rates reacting more to headlines than to incident statistics.","kImp":"단기 요율 급등은 긴장 완화 시 빠르게 되돌아갈 수 있어 장기 계약 체결에 신중해야 한다.","eImp":"Spike pricing may unwind fast if tensions ease — caution warranted on locking in long-term war cover.","url":"https://splash247.com/hormuz-the-maritime-risk-premium-and-fear/"},{"code":"INS","title":"재보험사 철수로 걸프 전쟁위험 보험 인수 중단","src":"gCaptain","date":"2026-06-22","kSum":"일부 재보험사가 걸프 지역 익스포저에서 철수하면서 전쟁위험 보험 인수가 중단되는 사례가 발생했다. 선주들은 담보 공백 리스크에 직면했다.","eSum":"Gulf war risk insurance has been pulled by some markets as reinsurers exit the exposure, leaving owners facing potential cover gaps.","kImp":"담보 취소 통지(cancellation notice) 수령 시 대체 담보 확보까지 항해 일정 조정이 필요하다.","eImp":"On receipt of a cancellation notice, voyage plans must be adjusted until replacement cover is bound.","url":"https://gcaptain.com/gulf-war-risk-insurance-pulled-as-reinsurers-exit/"},{"code":"INS","title":"보험 초크포인트: 강압 수단이 된 전쟁위험 요율","src":"Maritime Executive","date":"2026-06-30","kSum":"전쟁위험 보험 가격 책정이 사실상 해상 강압(coercion)의 도구로 기능하고 있다는 논평이다. 특정 국적·선주 이해관계에 따라 요율이 차등 적용되며 항로 선택을 좌우한다.","eSum":"Editorial argues war-risk pricing has become an instrument of maritime coercion, with rates differentiated by flag and beneficial ownership and effectively dictating routing choices.","kImp":"보험 접근성 자체가 항로 결정 변수로, 선대 배선 전략에 보험 리스크를 선반영해야 한다.","eImp":"Insurance availability is now a routing variable — fleet deployment strategy must price in cover risk upfront.","url":"https://maritime-executive.com/editorials/the-insurance-chokepoint-war-risk-pricing-as-an-instrument-of-maritime-coe"},{"code":"INS","title":"이란 분쟁 확대로 해상보험료 급등","src":"gCaptain","date":"2026-06-16","kSum":"이란 관련 분쟁이 확대되면서 해상보험료가 전반적으로 급등했다. 전쟁위험 뿐 아니라 선체·적하 담보 전반에 파급되고 있다.","eSum":"Maritime insurance premiums surged as the Iran conflict widened, with pressure spreading beyond war risk into hull and cargo covers.","kImp":"적하보험까지 요율 상승이 전이되면 무역업체의 물류 원가 부담이 확대된다.","eImp":"Rate contagion into cargo cover raises logistics costs for traders as well as owners.","url":"https://gcaptain.com/maritime-insurance-premiums-surge-as-iran-conflict-widens/"},{"code":"INS","title":"런던 해상보험사, 중동 전쟁위험 구역 확대","src":"Seatrade Maritime","date":"2026-06-19","kSum":"런던 시장 합동전쟁위원회(JWC)가 중동 전쟁위험 리스팅 구역을 확대했다. 확대 구역 진입 선박은 사전 통지 및 추가보험료 부과 대상이 된다.","eSum":"London marine insurers have extended the Middle East war risk listed areas, meaning vessels entering the expanded zones face notification requirements and additional premiums.","kImp":"JWC 리스팅 구역 변경은 즉시 항해 지시서와 용선계약 전쟁조항 검토를 요구한다.","eImp":"JWC listed-area changes require immediate review of voyage orders and charterparty war clauses.","url":"https://www.seatrade-maritime.com/security/london-marine-insurers-extend-middle-east-war-risk-zones"},{"code":"INS","title":"적하보험 손해율 개선·용량 증가 — Gallagher 분석","src":"Insurance Marine News","date":"2026-06-10","kSum":"보험중개사 Gallagher는 적하보험(cargo) 시장의 손해율이 개선되고 인수 용량이 증가하고 있다고 분석했다. 이는 요율 하방 압력으로 이어지고 있다.","eSum":"Broker Gallagher reports improved loss ratios and increased capacity in the cargo insurance market, feeding downward pressure on rates.","kImp":"적하보험 갱신 시 요율 인하 협상 여지가 커진 우호적 시장 환경이다.","eImp":"Buyers have room to negotiate cargo rate reductions at renewal in this softer market.","url":"https://insurancemarinenews.com/insurance-marine-news/improved-loss-ratios-and-increased-capacity-in-cargo-market-says-gallagher/"},{"code":"INS","title":"2025년 신디케이트 실적 — Aegis 신디케이트 1225","src":"Insurance Marine News","date":"2026-06-05","kSum":"로이즈 신디케이트들이 2025년 실적과 2026년 전망을 공개하는 가운데 Aegis 신디케이트 1225의 결과가 발표됐다. 해상 부문 인수 실적과 향후 전략이 포함됐다.","eSum":"Lloyd's syndicates are publishing 2025 results with 2026 outlooks; Aegis Syndicate 1225's marine underwriting performance and forward strategy were reported.","kImp":"로이즈 신디케이트 실적은 H&M·적하 인수 용량의 선행 지표로 활용된다.","eImp":"Syndicate results serve as a leading indicator of H&M and cargo underwriting capacity.","url":"https://insurancemarinenews.com/cargo/syndicate-results-2025-17-aegis-syndicate-1225/"},{"code":"INS","title":"Lloyd's List Intelligence, 선박 실사 워크벤치 출시","src":"Maritime Executive","date":"2026-06-23","kSum":"Lloyd's List Intelligence가 언더라이터용 Vessel Due Diligence Workbench를 출시했다. 도크 이력, 기관 상태, 검사 기록, 기항 이력 등 리스크 신호를 단일 화면에 통합한다.","eSum":"Lloyd's List Intelligence launched a Vessel Due Diligence Workbench consolidating risk signals — dry dock status, machinery condition, inspections and port call history — into a single view for underwriters.","kImp":"H&M 인수 심사가 데이터 기반으로 정밀화되면서 선박 상태 기록 관리가 요율에 직결된다.","eImp":"Data-driven H&M underwriting means vessel condition records now directly affect rating.","url":"https://maritime-executive.com/corporate/lloyd-s-list-intelligence-launches-vessel-due-diligence-workbench"},{"code":"INS","title":"IUMI, 선체보험 시장 어려운 클레임 환경 경고","src":"IUMI","date":"2025-09-16","kSum":"IUMI는 선체(H&M) 보험 시장이 보험료 기반 증가에도 불구하고 노후 선대, 대형 손해 심도, 지정학적 충격으로 위험 환경이 심화되고 있다고 발표했다. 세계 선대 평균 선령은 22.6년이며 35%가 25년을 초과한다.","eSum":"IUMI warns the hull market faces a challenging claims environment: the premium base is rising but the underlying risk environment is intensifying from an ageing fleet, higher loss severity, geopolitical shocks and energy-transition complexity. World fleet average age is 22.6 years, 35% over 25 years.","kImp":"H&M 요율 협상 시 보험사가 선령·기관손상 데이터를 근거로 인상을 요구할 여지가 커진다.","eImp":"Underwriters gain leverage to push H&M rates up using fleet-age and machinery-damage data at renewal.","url":"https://iumi.com/news/press-release/iumi-highlights-challenging-hull-marine-insurance-market-and-elevated-risk/"},{"code":"INS","title":"세계 해상보험료 사상 최고치 기록","src":"Lloyd's List","date":"2025-09-15","kSum":"IUMI 통계에 따르면 글로벌 해상보험료가 사상 최고 수준에 도달했다. 선체보험료는 96.7억 달러로 전년 대비 3.5% 증가했으며 유럽이 전체의 약 53%, 아시아·태평양이 35%를 차지했다.","eSum":"Global marine insurance premiums hit an all-time high per IUMI statistics. Ocean hull premium reached USD 9.67bn, up 3.5% year-on-year, with Europe at ~53% of global hull premium and Asia/Pacific 35%.","kImp":"보험료 총액 증가에도 요율은 연화 국면이어서 물량 증가가 주된 성장 동인임을 시사한다.","eImp":"Growth is volume-driven rather than rate-driven, signalling a softening H&M pricing cycle.","url":"https://www.lloydslist.com/LL1154731/Global-marine-insurance-premiums-hit-all-time-high"},{"code":"INS","title":"IUMI: 선체시장, 기관손상 주도로 손해 심도 상승","src":"SAFETY4SEA","date":"2025-09-17","kSum":"IUMI는 선체보험 손해 심도가 코로나 이전 수준을 상회하며 기관손상(machinery failure)이 이를 주도하고 있다고 분석했다. 용량 증가로 인해 일부 인수사가 기술적 규율보다 성장을 우선시하는 경향이 관측된다.","eSum":"IUMI reports hull loss severity remains above pre-COVID levels, led by machinery failures, while increased capacity has led some underwriters to prioritise growth over technical discipline.","kImp":"기관손상 예방 정비(PMS) 실적이 H&M 인수 심사의 핵심 변수로 부상한다.","eImp":"Machinery maintenance records become a decisive factor in H&M underwriting assessment.","url":"https://safety4sea.com/iumi-hull-market-experiences-challenging-claims-environment/"},{"code":"INS","title":"2025년 세계 10대 해상보험사","src":"Lloyd's List","date":"2025-12-10","kSum":"Lloyd's List가 2025년 기준 글로벌 상위 10개 해상보험사를 집계했다. Gard가 세계 최대 P&I 클럽이자 최대 선체·기관(H&M) 담보 제공자로 자리하고 있다.","eSum":"Lloyd's List ranked the top 10 global marine insurers for 2025. Gard stands as both the world's largest P&I club and the biggest global provider of hull and machinery cover, written commercially.","kImp":"H&M 시장의 인수 집중도가 높아 대형사 정책 변화가 시장 전체 요율에 파급된다.","eImp":"High concentration in H&M means a single large carrier's policy shift moves the whole market.","url":"https://www.lloydslist.com/LL1155823/Top-10-marine-insurers-2025"}]},{"code":"PNI","type":"news","kTitle":"Section 13. P&I 클럽","eTitle":"Section 13. P&I Clubs","items":[{"code":"PNI","title":"Skuld, 2026년 P&I 갱신의 최대 승자로 부상","src":"Lloyd's List","date":"2026-02-25","kSum":"Skuld가 2026년 P&I 갱신에서 SK해운, CMA CGM, Oldendorff 등 대형 선주 물량을 확보하며 최대 승자로 부상했다.","eSum":"Skuld emerged as the big winner of the 2026 P&I renewal, picking up business from major owners including SK Shipping, CMA CGM and Oldendorff.","kImp":"대형 선주의 클럽 이동은 향후 풀(Pool) 클레임 배분 구조에 영향을 준다.","eImp":"Large-owner club moves affect the future distribution of Pool claims exposure.","url":"https://www.lloydslist.com/LL1156402/Skuld-emerges-as-big-winner-in-2026-PI-renewal"},{"code":"PNI","title":"2026 P&I 갱신 라운드: 승자와 패자","src":"Lloyd's List","date":"2026-03-05","kSum":"NorthStandard의 Jeremy Grose는 2026년 갱신을 흥미로울 것이 없는(low-excitement) 갱신으로 평가했다. 클럽 간 대규모 물량 이동은 제한적이었다.","eSum":"NorthStandard MD Jeremy Grose called the 2026 P&I renewal a low-excitement renewal, with limited dramatic movement of business between International Group clubs.","kImp":"안정적 갱신은 클럽 재무 건전성이 전반적으로 양호함을 시사한다.","eImp":"A stable renewal signals broadly healthy club balance sheets across the IG.","url":"https://www.lloydslist.com/LL1156490/PI-renewal-round-The-winners-and-losers"},{"code":"PNI","title":"London·Skuld, 성장 클럽 대열에 합류","src":"Lloyd's List","date":"2026-03-02","kSum":"London Club과 Skuld가 입회 톤수 성장을 기록한 클럽 명단에 합류했다. 갱신 결과가 클럽별로 공개되면서 성장세가 확인되고 있다.","eSum":"London Club and Skuld joined the lengthening list of P&I clubs reporting growth in entered tonnage as renewal outcomes were disclosed.","kImp":"톤수 성장 경쟁은 일반증액(GI) 억제 압력으로 작용한다.","eImp":"Competition for tonnage growth suppresses general increase levels.","url":"https://www.lloydslist.com/LL1156443/London-and-Skuld-join-lengthening-list-of-growing-PI-clubs"},{"code":"PNI","title":"3개 P&I 클럽, 입회 톤수 성장 기록","src":"Lloyd's List","date":"2026-03-01","kSum":"Gard, NorthStandard, Skuld, West of England, Steamship Mutual 등이 입회 톤수 증가를 기록했다. Gard의 유지율(retention rate)은 99.6%로 집계됐다.","eSum":"Several clubs including Gard, NorthStandard, Skuld, West of England and Steamship Mutual clocked up tonnage growth; Gard's retention rate came in at 99.6%.","kImp":"높은 유지율은 회원 이탈 리스크가 낮아 클럽의 요율 결정력이 유지됨을 의미한다.","eImp":"High retention means low member churn and preserved pricing power for the clubs.","url":"https://www.lloydslist.com/LL1156432/Trio-of-PI-clubs-clock-up-growth-in-entered-tonnage"},{"code":"PNI","title":"걸프 분쟁 장기화가 P&I 클럽을 압박하는 경로","src":"Lloyd's List","date":"2026-06-26","kSum":"걸프 분쟁이 장기화될 경우 P&I 클럽의 풀·초과손해 재보험 구조와 자본에 미칠 압박을 분석했다. 재보험사의 전쟁위험 회피 성향이 핵심 변수다.","eSum":"Analysis of how a prolonged Gulf conflict could squeeze P&I clubs through the Pool and excess-of-loss reinsurance structure, with reinsurer appetite for war risk the key variable.","kImp":"분쟁 장기화 시 2027 갱신에서 일반증액 상향 압력이 커질 수 있다.","eImp":"A prolonged conflict raises the risk of higher general increases at the 2027 renewal.","url":"https://www.lloydslist.com/LL1156600/How-a-prolonged-Gulf-conflict-could-squeeze-PI-clubs"},{"code":"PNI","title":"UK P&I 클럽 서큘러 09/26: 이사회 업데이트","src":"UK P&I Club","date":"2026-05-20","kSum":"UK P&I 클럽 이사회는 합산비율이 105%로 개선되고 자유준비금이 5억 8,600만 달러로 사상 최고치를 기록했다고 회원사에 통지했다.","eSum":"UK P&I Club board circular reports a combined ratio improved to 105% reflecting a more normal claims environment, and free reserves rising to a record $586m.","kImp":"사상 최고 준비금은 회원 환급 또는 증액 억제 여지를 시사한다.","eImp":"Record reserves point to scope for member returns or restrained general increases.","url":"https://www.ukpandi.com/news-and-resources/circulars/article/circular-09/26-update-from-the-board"},{"code":"PNI","title":"Steamship Mutual, 2026 경영 하이라이트 공개","src":"Steamship Mutual","date":"2026-06-02","kSum":"Steamship Mutual는 자유준비금 5억 7,800만 달러, S&P A 등급, 합산비율 112%를 기록하며 어려운 시장에서 안정성과 회원 중심 경영을 유지했다고 발표했다.","eSum":"Steamship Mutual published its 2026 management highlights: $578m free reserves, an S&P A rating and a combined ratio of 112%, demonstrating stability and member focus in a challenging market.","kImp":"112% 합산비율은 투자수익 의존도가 높아 시장 변동 시 취약할 수 있음을 뜻한다.","eImp":"A 112% combined ratio means reliance on investment income, a vulnerability if markets turn.","url":"https://www.steamshipmutual.com/press-release-steamship-mutual-publishes-2026-management-highlights-demonstrating-strength"},{"code":"PNI","title":"Skuld, 특정 전쟁위험에 대한 일반 취소 통지 발행","src":"Skuld","date":"2026-06-15","kSum":"Skuld는 재보험사 우려에 따라 특정 전쟁위험 담보에 대한 일반 취소 통지(general notice of cancellation)를 회원사에 발행했다.","eSum":"Skuld issued a general notice of cancellation in respect of certain war risks to members, following reinsurer concerns over exposure.","kImp":"통지 발효일 이전에 대체 담보를 확보하지 못하면 무담보 항해 리스크가 발생한다.","eImp":"Failure to arrange replacement cover before the notice takes effect creates uninsured voyage exposure.","url":"https://www.skuld.com/about/-/circulars/2026/general-notice-of-cancellation-in-respect-of-certain-war-risks-/"},{"code":"PNI","title":"Gard 서큘러 15/2025: 2026 정책연도 IG 재보험 구조","src":"Gard","date":"2025-12-05","kSum":"국제그룹(IG) 2026/27 풀 및 초과손해(GXL) 재보험 구조가 확정됐다. 개별 클럽 보유액은 1,000만 달러, GXL 부착점은 1억 달러로 유지되며 총 한도는 33.5억 달러로 2.5억 달러 확대됐다.","eSum":"The IG Pool and Group Excess of Loss reinsurance structure for 2026/27 is finalised: individual club retention unchanged at USD 10m, GXL attachment unchanged at USD 100m, and the overall RI limit extended by $250m to $3.35bn.","kImp":"러시아·우크라이나 제외 리스크 총량 담보는 1억→1.25억 달러로 확대돼 관련 항로 운항 여력이 소폭 개선됐다.","eImp":"Aggregated cover for Russia/Ukraine/Belarus excluded risks rose from $100m to $125m, marginally easing trading in those waters.","url":"https://gard.no/circulars/15-2025-reinsurance-arrangements-for-the-2026-policy-year-arranged-through/"},{"code":"PNI","title":"North, 어려운 P&I 연도 후 견조한 갱신 실적 보고","src":"Insurance Marine News","date":"2026-02-20","kSum":"NorthStandard는 P&I 업계에 어려웠던 한 해를 보낸 후 견조한 갱신 실적을 보고했다. 온건한 갱신 증액을 통해 신중한 보험료 정책을 취했다.","eSum":"North reported solid renewals after a challenging P&I year, taking a prudent position on premiums with a modest renewal increase.","kImp":"온건 증액 기조가 클럽 간 확산되면 선주의 P&I 비용 예측 가능성이 높아진다.","eImp":"If moderate-increase discipline spreads across clubs, owners gain better P&I cost predictability.","url":"https://insurancemarinenews.com/insurance-marine-news/north-reports-solid-renewals-after-pis-challenging-year/"}]},{"code":"VET","type":"news","kTitle":"Section 14. 베팅·검사","eTitle":"Section 14. Vetting & Inspection","items":[{"code":"VET","title":"RightShip, 2026년 2월 25일부터 RISQ 3.2 기준 검사 시행","src":"SAFETY4SEA","date":"2026-02-25","kSum":"2026년 2월 25일부터 모든 RightShip 검사가 RISQ 3.2에 따라 시행된다. 밀폐구역 진입 절차, 구명·소방설비, 해치커버 상태, 기관실 준비상태, 파일럿 사다리 안전이 주요 고위험 지적항목으로 유지된다.","eSum":"From 25 February 2026 all RightShip Inspections are conducted under RISQ 3.2. High-risk items — enclosed space entry, LSA/FFE, hatch cover condition, machinery space readiness and pilot ladder safety — remain the most frequently observed issues.","kImp":"벌크선 선장·기관장은 RISQ 3.2 신규 항목에 맞춰 사전 자체점검 체크리스트를 갱신해야 한다.","eImp":"Bulker masters and chief engineers must update pre-inspection self-check lists to RISQ 3.2 items.","url":"https://safety4sea.com/rightship-inspections-conducted-in-accordance-with-risq-3-2/"},{"code":"VET","title":"RightShip 검사 선령 트리거 2단계, 2026년 4월 1일 발효","src":"SAFETY4SEA","date":"2026-03-05","kSum":"2026년 4월 1일부터 유효한 RightShip 검사가 없는 선령 12년 이상 벌크선·일반화물선의 안전점수가 5점 만점에 2점으로 하향된다. 7월 1일부터는 11년 이상으로 확대된다.","eSum":"From 1 April 2026 dry bulk and general cargo vessels aged 12+ without a valid RightShip Inspection have their Safety Score downgraded to 2/5; from 1 July 2026 this extends to vessels 11 years and older.","kImp":"7월 1일 시행으로 선령 11년 이상 벌크선은 즉시 검사를 예약하지 않으면 용선 후보에서 배제된다.","eImp":"With the 1 July trigger live, 11-year-old bulkers must book inspections now or be screened out of fixtures.","url":"https://safety4sea.com/rightship-phase-2-of-inspection-age-trigger-takes-effect-on-1-april-2026/"},{"code":"VET","title":"벌크선·일반화물선 검사에 새로운 선령 트리거 도입","src":"SAFETY4SEA","date":"2026-01-15","kSum":"RightShip이 벌크선·일반화물선 검사 선령 기준을 14년에서 10년으로 4단계에 걸쳐 낮춘다. 2026년 4월 12년, 7월 11년, 2027년 1월 10년으로 순차 적용된다.","eSum":"RightShip is lowering the inspection age trigger for dry bulk and general cargo carriers from 14 to 10 years in four phases: 12 years in April 2026, 11 years in July 2026, and 10 years from January 2027.","kImp":"선대 전반의 검사 부담이 급증하므로 검사관 확보 및 일정 관리가 병목이 될 수 있다.","eImp":"Fleet-wide inspection burden rises sharply; inspector availability and scheduling become a bottleneck.","url":"https://safety4sea.com/new-age-trigger-for-dry-bulk-and-general-cargo-carrier-inspections/"},{"code":"VET","title":"RightShip, 검사 선령 트리거 개정 일정 발표","src":"RightShip","date":"2025-12-01","kSum":"RightShip이 업계 이해관계자와 협의해 선박 검사 선령 트리거의 개정 일정을 발표했다. 선주·관리사·용선자에게 미치는 실무적 영향을 설명한다.","eSum":"RightShip announced a revised timeline for the vessel inspection age trigger in collaboration with industry stakeholders, explaining what it means for owners, managers and charterers.","kImp":"용선자는 벳팅 노미네이션 통과 요건 변경을 용선계약 조항에 반영해야 한다.","eImp":"Charterers need to reflect the revised vetting-nomination pass criteria in charterparty terms.","url":"https://rightship.com/insights/revised-rightship-inspection-age-trigger-what-means-owners-managers-charterers"},{"code":"VET","title":"RightShip, 업계 반발 후 벌크선 검사 변경 연기","src":"Seatrade Maritime","date":"2025-11-20","kSum":"RightShip이 업계의 강한 반발을 수용해 벌크선 검사 선령 기준 변경 일정을 연기했다. 당초 일괄 적용 계획이 단계적 도입으로 수정됐다.","eSum":"RightShip delayed its dry bulk inspection changes after industry pushback, converting a planned single-step implementation into a phased rollout.","kImp":"업계 의견 수렴 사례로, 향후 벳팅 규정 변경 시 협의 절차가 표준화될 가능성이 있다.","eImp":"A precedent for consultation — future vetting rule changes are likely to follow a formal engagement process.","url":"https://www.seatrade-maritime.com/dry-bulk/rightship-delays-dry-bulk-inspection-changes-after-industry-pushback"},{"code":"VET","title":"RightShip, 업계 비판 수용해 검사 선령 계획 재작성","src":"TradeWinds","date":"2025-11-19","kSum":"RightShip이 업계 비판에 따라 검사 선령 계획을 전면 재작성했다. 8,000 DWT 미만 선박에도 유사한 검사 요건을 적용해 전 세계 벌크·일반화물 선대 안전기준을 일관되게 만든다는 방침이다.","eSum":"RightShip bowed to industry criticism and redrew its inspection age plans, while extending similar inspection requirements to vessels under 8,000 DWT to make safety standards more consistent across the global dry bulk and general cargo fleet.","kImp":"소형선까지 검사 대상이 확대되면서 중소 선주의 컴플라이언스 비용이 증가한다.","eImp":"Extending inspections to smaller vessels raises compliance costs for small and mid-sized owners.","url":"https://www.tradewindsnews.com/bulkers/rightship-bows-to-industry-criticism-and-redraws-inspection-age-plans/2-1-1751380"},{"code":"VET","title":"RightShip, 벌커 연례검사 선령 10년으로 인하","src":"Seatrade Maritime","date":"2025-09-15","kSum":"RightShip이 벌크선 연례검사 선령 기준을 10년으로 인하한다. 선령 10년 초과 시 사고·PSC 억류율이 뚜렷이 상승한다는 데이터 분석에 근거한다.","eSum":"RightShip cut the bulker annual inspection age to 10 years, based on analysis showing a strong correlation between vessel age and rising safety risk, particularly once vessels pass 10 years old.","kImp":"선령 10년 전후 선박의 자산가치·용선 경쟁력에 검사 이력이 직접 반영된다.","eImp":"Inspection history now directly affects asset value and chartering competitiveness around the 10-year mark.","url":"https://www.seatrade-maritime.com/dry-bulk/rightship-cuts-bulker-annual-inspection-age-to-10-years"},{"code":"VET","title":"RightShip 딥다이브: RISQ 3.2 개정과 검사 고도화","src":"RightShip","date":"2026-02-20","kSum":"RightShip이 RISQ 3.2 개정 내용과 검사 프로세스 고도화를 상세히 설명했다. 검사 항목 재구성과 고위험 지적사항 중심의 접근이 핵심이다.","eSum":"RightShip's deep dive details the RISQ 3.2 update and enhancements to its inspection process, centred on restructured questions and a focus on high-risk findings.","kImp":"RISQ 3.2 개정 항목을 SMS 절차와 선내 교육에 반영하는 것이 지적 최소화의 관건이다.","eImp":"Embedding RISQ 3.2 changes into SMS procedures and onboard training is key to minimising findings.","url":"https://rightship.com/insights/deep-dive-advancing-vessel-safety-update-risq-3.2-and-rightship-inspections"},{"code":"VET","title":"OCIMF, 탱커 검사 프로그램 디지털화 추진","src":"SAFETY4SEA","date":"2026-05-20","kSum":"OCIMF가 탱커 검사 프로그램의 디지털화를 추진한다. SIRE 2.0에서 종이 기반 대체 절차 사용 비율이 최근 12개월간 0.2%에 그쳐 디지털 전환이 안착했음을 보여준다.","eSum":"OCIMF is digitalising its tanker inspection programme; only 0.2% of SIRE 2.0 inspections needed the paper-based contingency over the past 12 months, showing successful digital adoption.","kImp":"태블릿 기반 검사가 표준화되면서 선내 IT 환경 및 검사관 대응 준비가 필수다.","eImp":"Tablet-based inspection is now standard — onboard IT readiness and crew preparation are essential.","url":"https://safety4sea.com/ocimf-to-digitalize-its-tanker-inspection-programme/"},{"code":"VET","title":"벳팅, 점점 복잡하고 주관적으로 변화","src":"Riviera Maritime Media","date":"2026-06-10","kSum":"벳팅 프로세스가 갈수록 복잡해지고 주관적 판단이 개입되고 있다는 논평이다. 검사관 재량과 화주별 상이한 기준이 선주에게 예측 불가능성을 야기한다.","eSum":"Opinion piece argues vetting is becoming more complex and subjective, with inspector discretion and divergent charterer criteria creating unpredictability for owners.","kImp":"화주별 벳팅 기준 차이를 사전 파악해 선대별 배선 전략을 조정할 필요가 있다.","eImp":"Owners should map charterer-specific vetting criteria and adjust fleet deployment accordingly.","url":"https://www.rivieramm.com/opinion/opinion/vetting-is-becoming-more-complex-and-subjective-41418"},{"code":"VET","title":"효과적인 벳팅 조항 작성 방법","src":"Riviera Maritime Media","date":"2026-04-15","kSum":"용선계약상 벳팅 조항(vetting clause) 작성 시 주의점을 다뤘다. TMSA 준수 등 선주의 선대 전반 성과가 승인 전제조건으로 작용하는 경우가 많다.","eSum":"Analysis of drafting effective vetting clauses in charterparties, noting that owner performance across the fleet — including TMSA compliance — is often a prerequisite for approval.","kImp":"벳팅 조항의 모호성은 분쟁으로 이어지므로 승인 실패 시 책임 배분을 명확히 해야 한다.","eImp":"Ambiguous vetting clauses cause disputes — allocation of risk on vetting failure must be explicit.","url":"https://www.rivieramm.com/opinion/opinion/drafting-effective-vetting-clauses-40602"},{"code":"VET","title":"벌크 부문 안전성 개선과 검사의 역할","src":"RightShip","date":"2026-03-10","kSum":"RightShip은 벌크 부문이 타 선종 대비 사고·사망·PSC 억류율이 높으며, 검사가 이를 개선하는 핵심 수단이라고 분석했다. 20만 DWT 초과선은 10~13년 구간, 소형선은 14~19년 구간에서 사고율이 정점을 보인다.","eSum":"RightShip's analysis: the dry bulk sector faces higher incident, fatality and PSC detention rates than other segments. Vessels over 200,000 dwt show a rise in incidents at 10-13 years, while smaller vessels peak at 14-19 years.","kImp":"선형별 리스크 정점 구간이 달라 선대 매각·검사 전략을 선형별로 차별화해야 한다.","eImp":"Risk peaks differ by vessel size — inspection and divestment strategy should be segmented by ship type.","url":"https://rightship.com/insights/improving-safety-outcomes-dry-bulk-role-of-inspections"},{"code":"VET","title":"SIRE 2.0 시행 첫해 2만 2,000건 이상 검사 완료","src":"SAFETY4SEA","date":"2025-09-10","kSum":"SIRE 2.0 시행 첫해 2,100개 항만에서 460명의 인증 검사관에 의해 2만 2,000건 이상의 검사가 완료됐다. INTERTANKO 분석에 따르면 부정적 지적사항의 대다수는 프로세스, 그 다음이 인적요인과 관련된다.","eSum":"Over 22,000 SIRE 2.0 inspections were completed in its first year across 2,100 ports by 460 accredited inspectors. INTERTANKO's Phase III observations show the majority of negative findings relate to processes, followed by human factors.","kImp":"프로세스 관련 지적이 최다인 만큼 SMS 절차서의 실질적 이행 증빙 정비가 우선순위다.","eImp":"With process findings dominant, evidencing real SMS procedure implementation is the top priority.","url":"https://safety4sea.com/over-22000-sire-2-0-inspections-completed-during-its-first-year/"}]},{"code":"CLASS","type":"news","kTitle":"Section 15. 선급","eTitle":"Section 15. Classification Societies","items":[{"code":"CLASS","title":"DNV, 2026년 선급규칙 개정 의견수렴 개시","src":"DNV","date":"2026-03-01","kSum":"DNV가 2026년 선급규칙 개정안에 대한 업계 의견수렴(hearing)을 3월 1일부터 4월 12일까지 진행했다. 총 77개 문서가 2026년 7월 1일자로 발효될 예정이다.","eSum":"DNV opened the hearing period for its 2026 rules from 1 March to 12 April 2026, with 77 documents planned for publication and entry into force on 1 July 2026.","kImp":"7월 1일 발효 규칙은 신조 계약 및 개조 설계에 즉시 반영해야 한다.","eImp":"The 1 July rule set must be reflected immediately in newbuilding contracts and conversion designs.","url":"https://www.dnv.com/news/2026/dnv-rules-2026-hearing-period-now-open/"},{"code":"CLASS","title":"DNV, HD현대미포 암모니아 이중연료 중형 가스선 승인","src":"Offshore Energy","date":"2026-06-10","kSum":"DNV가 HD현대미포의 암모니아 이중연료 중형 가스운반선(MGC) 설계에 원칙승인(AiP)을 부여했다. 선수부 거주구(FWD accommodation) 배치가 특징이다.","eSum":"DNV granted an AiP to HD Hyundai Mipo's ammonia dual-fuel medium gas carrier design, notable for its forward accommodation arrangement.","kImp":"암모니아 연료선의 거주구 배치 혁신은 독성가스 노출 저감 설계의 표준이 될 수 있다.","eImp":"Forward accommodation on ammonia-fuelled ships may become a design norm for reducing toxic gas exposure.","url":"https://www.offshore-energy.biz/dnv-okays-hd-hyundai-mipos-ammonia-dual-fuel-medium-gas-carrier-with-fwd-accommodation/"},{"code":"CLASS","title":"Höegh Evi·Aker BP, 차세대 CO2 운반선 DNV 승인 획득","src":"MarineLink","date":"2026-06-05","kSum":"Höegh Evi와 Aker BP가 차세대 액화 CO2(LCO2) 운반선 설계에 대해 DNV 원칙승인(AiP)을 획득했다. 유럽 산업 배출원에서 노르웨이 대륙붕 해저 저장소로 CO2를 운송하도록 설계됐다.","eSum":"Höegh Evi and Aker BP secured DNV Approval in Principle for a next-generation liquefied CO2 carrier designed to move captured CO2 from European industrial emitters to offshore sequestration sites on the Norwegian Continental Shelf.","kImp":"CCS 밸류체인 확대로 LCO2 운반선이 신규 선종 발주 축으로 부상하고 있다.","eImp":"LCO2 carriers are emerging as a new ordering segment as the CCS value chain scales up.","url":"https://www.marinelink.com/news/hegh-evi-aker-bp-secure-dnv-approval-526527"},{"code":"CLASS","title":"Pherousa, 선박용 암모니아 크래킹 기술로 ABS·DNV 승인 획득","src":"MarineLink","date":"2026-04-20","kSum":"노르웨이 Pherousa가 선박용 암모니아 크래킹 기술에 대해 ABS와 DNV로부터 원칙승인(AiP)을 획득했다. PEM 연료전지와 연료가스공급시스템(FGSS)을 통한 완전 전기추진이 특징이다.","eSum":"Norwegian firm Pherousa secured AiPs from both ABS and DNV for its onboard ammonia cracking technology, featuring PEM fuel cells and a fuel gas supply system for fully electric propulsion.","kImp":"복수 선급 동시 승인은 기술의 상용화 가능성을 높이는 신호로 해석된다.","eImp":"Dual-class AiP is a signal of the technology's commercialisation readiness.","url":"https://www.marinelink.com/news/pherousa-scoops-abs-dnv-approvals-523345"},{"code":"CLASS","title":"Lloyd's Register, 바이오연료 자문 서비스 출범","src":"MarineLink","date":"2026-07-06","kSum":"Lloyd's Register가 해운 탈탄소화 가속을 위한 신규 바이오연료 자문(Biofuel Advisory) 서비스를 출범시켰다. 선주의 바이오연료 도입 의사결정과 리스크 관리를 지원한다.","eSum":"Lloyd's Register launched a new Biofuel Advisory service to help shipowners accelerate decarbonisation, supporting adoption decisions and associated risk management.","kImp":"IMO 넷제로 프레임워크 대응에서 바이오연료가 즉시 적용 가능한 감축 수단으로 부각된다.","eImp":"Biofuels stand out as an immediately deployable abatement lever under the IMO net-zero framework.","url":"https://www.marinelink.com/news/lloyds-register-launches-biofuel-advisory-530074"},{"code":"CLASS","title":"Bureau Veritas, Greenroom Robotics 자율운항 소프트웨어에 AiP 부여","src":"MarineLink","date":"2026-07-08","kSum":"Bureau Veritas가 Greenroom Robotics의 해양 자율운항 소프트웨어에 원칙승인(AiP)을 부여했다. 자율운항 소프트웨어에 대한 선급 검증 사례가 확대되고 있다.","eSum":"Bureau Veritas granted an Approval in Principle to Greenroom Robotics' maritime autonomy software, extending class verification into autonomous navigation software.","kImp":"소프트웨어 자체에 대한 선급 승인은 MASS 규정 정립의 실질적 진전을 의미한다.","eImp":"Class approval of software itself marks tangible progress toward a MASS regulatory framework.","url":"https://www.marinelink.com/news/bureau-veritas-grants-aip-greenroom-535490"},{"code":"CLASS","title":"일본 자율운항선 프레임워크, ClassNK·BV 승인 획득","src":"Offshore Energy","date":"2026-06-18","kSum":"일본의 자율운항선 프레임워크가 ClassNK와 Bureau Veritas로부터 승인을 받았다. 일본 주도의 MASS 표준화 노력이 국제 선급의 인정을 확보했다.","eSum":"A Japanese autonomous ship framework received the green light from ClassNK and Bureau Veritas, giving Japan's MASS standardisation effort international class recognition.","kImp":"일본식 자율운항 프레임워크가 IMO MASS 코드 논의의 유력 참조 모델이 될 수 있다.","eImp":"The Japanese framework could become a reference model in IMO MASS Code deliberations.","url":"https://www.offshore-energy.biz/japanese-autonomous-ship-framework-gets-green-light-from-classnk-and-bv/"},{"code":"CLASS","title":"한국 조선소들, 암모니아 추진선 설계 ABS 승인 획득","src":"Offshore Energy","date":"2026-06-22","kSum":"한국 조선소들이 암모니아 추진선 설계에 대해 ABS의 승인을 획득했다. 암모니아 연료 선박의 상용 설계가 국내 조선소 중심으로 축적되고 있다.","eSum":"South Korean shipyards received ABS approval for ammonia-fuelled ship designs, consolidating commercial ammonia vessel design capability at Korean yards.","kImp":"한국 조선업의 암모니아 선종 선점은 2030년대 신조 발주 사이클에서 경쟁우위로 작용한다.","eImp":"Korean yards' early lead in ammonia designs is a competitive advantage in the 2030s ordering cycle.","url":"https://www.offshore-energy.biz/south-korean-shipyards-receive-abs-approval-for-ammonia-ship-designs/"},{"code":"CLASS","title":"중국 가스운반선·FSRU 5개 프로젝트, Bureau Veritas 승인","src":"Offshore Energy","date":"2026-07-01","kSum":"중국 조선소의 가스운반선 및 FSRU 5개 프로젝트가 Bureau Veritas의 승인을 받았다. 중국의 LNG 선종 설계 역량 확대가 확인된다.","eSum":"Five Chinese gas carrier and FSRU projects received Bureau Veritas approval, confirming the expansion of Chinese yards' LNG segment design capability.","kImp":"중국의 가스선 설계 역량 확대는 한국 조선소의 LNG선 독점 구도에 대한 위협이다.","eImp":"China's growing gas carrier design capability threatens Korean yards' LNG newbuilding dominance.","url":"https://www.offshore-energy.biz/five-chinese-gas-carrier-and-fsru-vessel-projects-receive-bureau-veritas-blessing/"},{"code":"CLASS","title":"Seatrium, ABS에 이어 Bureau Veritas와도 파트너십 체결","src":"Offshore Energy","date":"2026-06-30","kSum":"싱가포르 Seatrium이 ABS에 이어 Bureau Veritas와도 파트너십을 체결했다. 해양·offshore 설비 설계 및 인증 협력을 확대한다.","eSum":"Singapore's Seatrium forged a partnership with Bureau Veritas after an earlier tie-up with ABS, expanding cooperation on offshore asset design and certification.","kImp":"조선소-선급 간 전략적 제휴가 신기술 인증 속도를 좌우하는 경쟁 요소로 부상한다.","eImp":"Yard-class strategic alliances are becoming a competitive factor in speed of new-technology certification.","url":"https://www.offshore-energy.biz/after-abs-seatrium-forges-partnership-with-bureau-veritas/"},{"code":"CLASS","title":"Azane, 최초의 암모니아 벙커링 터미널로 DNV AiP 획득","src":"Offshore Energy","date":"2026-05-15","kSum":"Azane Fuel Solutions가 최초의 암모니아 벙커링 터미널 설계에 대해 DNV 원칙승인(AiP)을 획득했다. 암모니아 연료 공급 인프라 구축의 첫 관문을 통과했다.","eSum":"Azane won a DNV AiP for the first ammonia bunkering terminals, clearing an initial hurdle for ammonia fuel supply infrastructure.","kImp":"암모니아 추진선 확산의 병목인 벙커링 인프라 문제 해소에 진전이 있음을 시사한다.","eImp":"Progress on the bunkering infrastructure bottleneck that constrains ammonia-fuelled fleet uptake.","url":"https://www.offshore-energy.biz/azane-wins-dnv-aip-for-first-ammonia-bunkering-terminals/"},{"code":"CLASS","title":"DNV, HD현대중공업 암모니아 이중연료 컨테이너선에 AiP 발급","src":"MarineLink","date":"2026-02-10","kSum":"DNV가 HD현대중공업(HHI)의 암모니아 이중연료 컨테이너선 설계에 원칙승인(AiP)을 발급했다. 컨테이너 선종으로 암모니아 연료 적용이 확대되고 있다.","eSum":"DNV issued an AiP for HD Hyundai Heavy Industries' dual-fuel ammonia container ship design, extending ammonia fuel application into the container segment.","kImp":"컨테이너선에 암모니아 적용이 검증되면 정기선사의 연료 전환 선택지가 넓어진다.","eImp":"Validating ammonia on boxships widens fuel-transition options for liner operators.","url":"https://www.marinelink.com/news/dnv-issues-aip-hd-hhis-dualfuel-ammonia-518632"}]},{"code":"COMM","type":"news","kTitle":"Section 16. 상업·용선시장","eTitle":"Section 16. Commercial & Chartering","items":[{"code":"COMM","title":"회그 오토라이너스, 화물량 증가와 3억 달러 계약 연장 발표","src":"Baird Maritime","date":"2026-07-10","kSum":"노르웨이 자동차선사 회그 오토라이너스가 화물 운송량 증가와 함께 약 3억 달러 규모의 장기 운송계약 연장을 확보했다고 발표했다. 2분기 실적은 견조한 수준을 유지했다.","eSum":"Norwegian car carrier owner Hoegh Autoliners reported cargo volume growth alongside a roughly $300m long-term contract extension, with second-quarter performance holding up.","kImp":"PCTC 계약 운임이 높은 수준에서 재계약되고 있음을 보여주는 지표로, 자동차선 시장의 구조적 강세가 이어지고 있음을 시사한다.","eImp":"A marker that PCTC contract rates are being repriced at elevated levels, signalling the structural strength in the vehicle-carrier market is persisting.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/hoegh-autoliners-reports-cargo-volume-growth-and-300m-contract-extension"},{"code":"COMM","title":"회그 오토라이너스, 2분기 실적 유지 속 계약 연장 확보","src":"TradeWinds","date":"2026-07-10","kSum":"회그 오토라이너스가 2분기 실적이 견조하게 유지되는 가운데 주요 화주와의 운송계약 연장을 확보했다고 트레이드윈즈가 보도했다. 스팟 운임 강세와 계약 재산정이 실적을 뒷받침했다.","eSum":"TradeWinds reports Hoegh Autoliners secured a shipping contract extension as second-quarter performance held up, supported by firm spot rates and contract repricing.","kImp":"자동차선 장기계약 운임이 상향 재산정되는 흐름이 이어지고 있어, 선주 측 협상력이 여전히 우위에 있음을 보여준다.","eImp":"Long-term vehicle-carrier contracts continue to be repriced upward, showing owners still hold the negotiating advantage.","url":"https://www.tradewindsnews.com/containers/hoegh-autoliners-nets-contract-extension-as-second-quarter-performance-holds-up/2-1-2015371"},{"code":"COMM","title":"차이나 머천츠 에너지, 10척 신조 발주 계획","src":"Splash247","date":"2026-07-13","kSum":"상하이 상장사 China Merchants Energy Shipping이 3개 선종에 걸쳐 10척의 신조선 발주 계획을 공개했다.","eSum":"Shanghai-listed China Merchants Energy Shipping has laid out plans for 10 newbuildings across three shipping segments.","kImp":"중국 국영 선사의 공격적 발주는 중국 조선소 슬롯 경쟁을 심화시키고 신조선가 상승 압력으로 작용한다.","eImp":"Aggressive ordering by Chinese state-linked owners intensifies competition for Chinese yard slots and adds upward pressure on newbuild prices.","url":"https://splash247.com/china-merchants-energy-lines-up-10-ship-order/"},{"code":"COMM","title":"페트로브라스 부상, 유니펙의 탱커 시장 지배력 약화","src":"Splash247","date":"2026-07-13","kSum":"브라질 국영 페트로브라스가 최근 원유탱커 시장에서 가장 큰 수혜자 중 하나로 부상한 반면, 중국 유니펙의 용선 지배력은 약화되고 있다.","eSum":"Brazil's state-controlled Petrobras has emerged as one of the biggest gainers in the crude tanker market, while Unipec's chartering dominance weakens.","kImp":"호르무즈 봉쇄로 중동 물량이 감소하면서 대서양 분지 화주의 용선 영향력이 커지는 구조적 전환이 진행 중이다.","eImp":"With Hormuz throttling Middle East volumes, a structural shift is under way toward Atlantic-basin charterers gaining influence.","url":"https://splash247.com/petrobras-rises-as-unipecs-tanker-dominance-weakens/"},{"code":"COMM","title":"컨테이너 스팟운임과 수요 보합, 그러나 변동성 축적","src":"The Loadstar","date":"2026-07-10","kSum":"태평양 횡단 및 아시아-유럽 항로 컨테이너 스팟운임이 이번 주 완만한 상승세를 보였다. 수요는 견조하나 하반기 변동성 확대 가능성이 제기됐다.","eSum":"Container spot rates on the transpacific and Asia-Europe trades showed moderate gains this week, with demand steady but warnings of building volatility.","kImp":"7월 15일 수에즈 운하 할증료 인상과 맞물려 컨테이너 운임의 추가 상승 압력이 예상된다.","eImp":"Combined with the 15 July Suez surcharge hike, further upward pressure on box rates is likely.","url":"https://theloadstar.com/ocean-spots-and-demand-hold-steady-but-waves-may-be-building/"},{"code":"COMM","title":"브레마: 컨테이너선 매입 열풍 종료, 선사 선별적 접근 필요","src":"The Loadstar","date":"2026-07-10","kSum":"브레마(Braemar)에 따르면 중소형 컨테이너선 발주 급증으로 구조적 선복 부족이 대부분 해소됐으며, 선사들은 향후 보다 선별적으로 접근해야 한다고 분석했다.","eSum":"Braemar says the surge in orders for small and mid-sized containerships has largely addressed the structural capacity shortfall, and lines must now be more selective.","kImp":"피더선 선복 부족 해소는 용선료 하락 압력으로 이어질 수 있어, S&P 및 용선 전략 재검토가 필요하다.","eImp":"Easing feeder shortages could pressure charter rates lower, warranting a rethink of S&P and chartering strategy.","url":"https://theloadstar.com/box-ship-buying-spree-is-over-says-braemar-lines-must-be-more-selective/"},{"code":"COMM","title":"미국 수입업체, 변동성 속 신규 공급처 모색 지속","src":"The Loadstar","date":"2026-07-09","kSum":"6월 미국 컨테이너 수입은 전반적으로 보합세를 유지했으나, 데카르트(Descartes) 자료에 따르면 소싱 구조상 수입업체들이 관세 리스크에 대응해 공급처 다변화를 지속하고 있다.","eSum":"US containerised imports held broadly steady in June, but Descartes data suggests importers continue diversifying sourcing in response to tariff risk.","kImp":"관세發 소싱 이전은 항로별 물동량 구조를 재편해 태평양 횡단 및 동남아 항로 선복 배치에 영향을 미친다.","eImp":"Tariff-driven sourcing shifts are reshaping trade-lane volumes, with implications for transpacific and Southeast Asian capacity deployment.","url":"https://theloadstar.com/volatility-drives-us-importers-to-continue-to-look-for-new-suppliers/"},{"code":"COMM","title":"발틱운임지수(BDI) 3일 연속 상승, 6월 5일 이후 최고","src":"Hellenic Shipping News","date":"2026-07-14","kSum":"발틱거래소 건화물 운임지수가 7월 14일 3거래일 연속 상승해 약 0.5% 오른 2,960포인트로 6월 5일 이후 최고치를 기록했다. 케이프사이즈 지수는 1% 상승한 4,702포인트로 한 달여 만의 최고, 수프라막스는 1,707포인트로 6월 22일 이후 최고를 나타냈다.","eSum":"The Baltic Exchange's dry bulk index advanced for a third session on 14 July, up about 0.5% to 2,960 points, its highest since 5 June. The capesize index rose 1% to 4,702 points, a one-month high, while supramax hit 1,707 points, its best since 22 June.","kImp":"전 선형에 걸친 동반 상승은 건화물 시황의 계절적 회복이 실제 수요에 기반하고 있음을 시사한다.","eImp":"Gains across all vessel segments suggest the seasonal dry bulk recovery is underpinned by genuine demand rather than sentiment alone.","url":"https://www.hellenicshippingnews.com/baltic-dry-index-rises-for-3rd-day/"},{"code":"COMM","title":"컨테이너 리포트 28주차 — 태평양 항로 FBX01 7,666달러로 급등","src":"Hellenic Shipping News","date":"2026-07-13","kSum":"28주차 컨테이너 시황에서 중국/동아시아–미서안(FBX01)은 전주 대비 588달러 오른 7,666달러로 6월 초 대비 1,534달러 상승했다. 미동안(FBX03)은 9,102달러로 보합, 북유럽(FBX11)은 5,837달러로 40달러 소폭 상승했다.","eSum":"Week 28 container rates: China/East Asia–USWC (FBX01) jumped $588 to $7,666, up $1,534 since early June; USEC (FBX03) plateaued at $9,102; North Europe (FBX11) edged up $40 to $5,837. The 24 July deadline for the end of temporary US surcharges is driving the transpacific.","kImp":"태평양 항로만 홀로 급등하는 비대칭 시황으로, 관세·서차지 시한이라는 정책 변수가 운임을 좌우하고 있어 7월 말 이후 급락 리스크가 크다.","eImp":"An asymmetric market where only the transpacific is surging on a policy deadline, implying sharp correction risk once the 24 July surcharge cut-off passes.","url":"https://www.hellenicshippingnews.com/container-report-week-28/"},{"code":"COMM","title":"발틱운임지수(BDI) 34포인트 상승한 2,944 마감","src":"Hellenic Shipping News","date":"2026-07-10","kSum":"발틱거래소 건화물운임지수(BDI)가 7월 10일 금요일 34포인트 오른 2,944포인트로 마감했다. 케이프사이즈를 중심으로 한 강세가 지수를 끌어올렸다.","eSum":"The Baltic Exchange's dry bulk freight index (BDI) climbed 34 points on Friday 10 July 2026 to close at 2,944 points, lifted by strength in the larger segments.","kImp":"BDI가 2,900선을 상회하며 계절적 비수기에도 견조한 건화물 수요를 확인시켜, 케이프사이즈 용선료와 선가에 지지력을 제공한다.","eImp":"A BDI holding above 2,900 confirms resilient dry bulk demand even in the seasonal lull, underpinning capesize charter rates and asset values.","url":"https://www.hellenicshippingnews.com/baltic-dry-index-climbs-to-2944-up-34-points/"},{"code":"COMM","title":"선사들 운임 인상 시장 테스트 나섰지만 피크는 이미 지났나","src":"The Loadstar","date":"2026-07-09","kSum":"선사들이 7월 15일자 일반운임인상(GRI)과 성수기할증료(PSS)를 적용하며 잔여 성수기 수요를 시험하고 있다. 극동–미서안에서 머스크와 하파그로이드(제미나이)는 40피트당 6,000달러 미만의 우대운임을 제시해 경쟁사들의 7,000달러 인상 시도를 무력화할 수 있다는 지적이 나온다.","eSum":"Carriers are applying GRIs and peak season surcharges from 15 July to test how much peak-season demand remains. On Far East–USWC, Maersk and Gemini partner Hapag-Lloyd are quoting under $6,000 per 40ft, potentially blocking rivals' attempts to push rates above $7,000.","kImp":"제미나이 얼라이언스의 저가 전략이 시장 전체 인상 시도를 좌초시킬 수 있어, 얼라이언스 간 가격 경쟁이 하반기 컨테이너 운임의 최대 하방 요인으로 부상했다.","eImp":"Gemini's undercutting could sink the market-wide hike, making inter-alliance price competition the single biggest downside risk to H2 container rates.","url":"https://theloadstar.com/carriers-test-the-markets-with-rate-hikes-but-has-the-peak-hit-its-peak/"},{"code":"COMM","title":"컨테이너 운임 랠리, 비관론자 예상보다 길게 갈 여지 있다","src":"The Loadstar","date":"2026-07-13","kSum":"로드스타는 현재의 컨테이너 운임 랠리가 시장의 비관론자들이 가정하는 것보다 더 오래 지속될 여력이 있다고 분석했다. 항만 체선과 타이트한 선복이 공급 측면에서 운임을 지지하고 있다는 진단이다.","eSum":"The Loadstar argues the container rate rally has more legs than bears assume, with port congestion and tight effective capacity providing supply-side support to freight rates.","kImp":"체선에 따른 실질 선복 흡수가 신조선 인도 물량을 상쇄하고 있어, 공급 과잉 시나리오의 실현 시점이 뒤로 밀릴 수 있다.","eImp":"Congestion is absorbing effective capacity and offsetting newbuild deliveries, potentially pushing back the timing of the anticipated oversupply scenario.","url":"https://theloadstar.com/container-rate-rally-has-more-legs-than-bears-assume/"},{"code":"COMM","title":"다미코, MR2 탱커 2년 기간용선 체결 — 하반기 커버율 53%","src":"Splash247","date":"2026-07-14","kSum":"다미코 인터내셔널 시핑이 MR2 프로덕트 탱커를 2년 기간으로 용선 체결했다. 이번 계약으로 2026년 하반기 가용 선박일의 53%를 평균 TCE 약 23,700달러/일 수준에 확보했다.","eSum":"d'Amico International Shipping fixed an MR2 product tanker on a two-year time charter. Following the deal, it has 53% of available vessel days for H2 2026 covered at an average TCE of about $23,700 per day.","kImp":"프로덕트 탱커 선주들이 2년 기간용선을 통해 하반기 수익을 고정하는 흐름으로, 현물 시장 변동성에 대한 방어적 포지셔닝을 보여준다.","eImp":"Product tanker owners are locking in H2 earnings via period cover — defensive positioning against spot market volatility.","url":"https://splash247.com/damico-fixes-mr2-for-two-years/"},{"code":"COMM","title":"급등하는 신조선가 향방 놓고 시장 의견 갈려","src":"Splash247","date":"2026-07-09","kSum":"신조선가가 지속 상승하는 가운데 향후 궤적을 두고 시장의 전망이 엇갈리고 있다. 2026년 약 8,000만 GT의 신조선 인도가 예정돼 있고 2027년에는 1억 GT로 정점을 찍을 것으로 전망된다.","eSum":"Opinion is divided on the trajectory of soaring newbuild prices. Around 80m gt of new tonnage is due to deliver in 2026, peaking at about 100m gt in 2027.","kImp":"선가 고점 논쟁은 발주 타이밍과 중고선가 밸류에이션에 직결되며, 2027년 인도 정점은 전 선종의 운임 하방 압력 시점을 예고한다.","eImp":"The newbuild price-peak debate directly affects ordering timing and secondhand valuations, while the 2027 delivery peak flags when freight-rate pressure hits across segments.","url":"https://splash247.com/trajectory-of-soaring-newbuild-prices-divides-opinion/"}]},{"code":"GEO","type":"news","kTitle":"Section 17. 지정학","eTitle":"Section 17. Geopolitics","items":[{"code":"GEO","title":"우크라이나 드론 공격으로 아조프해 해운 중단","src":"Splash247","date":"2026-07-13","kSum":"우크라이나 드론이 러시아 연계 선박 수십 척을 표적으로 삼으면서 러시아가 아조프해 해운을 중단할 수밖에 없게 됐다. 7월 6~13일 진행된 다중 작전에서 다수의 그림자 선단 유조선이 피격됐다.","eSum":"Russia has been forced to suspend shipping through the Sea of Azov after Ukrainian drones targeted scores of Russia-linked vessels, with numerous shadow-fleet tankers hit during a multi-day operation from 6-13 July.","kImp":"흑해·아조프해 항로의 전쟁위험 보험료 급등과 크림반도 연료 공급 차질이 예상되며, 러시아 원유 수출 경로에 실질적 타격이다.","eImp":"Expect war-risk premiums in the Black Sea/Azov to spike and Crimean fuel supply to be disrupted — a material blow to Russian crude export routes.","url":"https://splash247.com/ukraine-drone-strikes-force-azov-shipping-halt/"},{"code":"GEO","title":"프랑스, 허위 선적 그림자 선단 유조선 선주에 벌금","src":"Splash247","date":"2026-07-06","kSum":"프랑스 검찰이 지난주 그림자 선단 유조선 Tagor호의 선주에게 100만 유로의 벌금을 부과했다. 해당 선박은 허위 선적(false flag) 혐의로 프랑스에서 억류됐다.","eSum":"French prosecutors fined the owner of the shadow-fleet tanker Tagor EUR 1m after the vessel was detained in France over false-flag allegations.","kImp":"유럽 연안국이 형사·행정 제재를 통해 그림자 선단을 압박하는 새로운 집행 모델로, 선적 검증 리스크가 커지고 있다.","eImp":"A new enforcement model in which European coastal states use criminal and administrative penalties against the shadow fleet, raising flag-verification risk.","url":"https://splash247.com/france-fines-shadow-fleet-tanker-owner-over-false-flag/"},{"code":"GEO","title":"파나마운하, 흘수 제한 재차 강화","src":"Splash247","date":"2026-07-06","kSum":"파나마운하청(ACP)이 네오파나막스 선박에 대한 최대 허용 흘수를 다시 축소할 예정이다. 수자원 리스크가 구조적 문제로 재부상하고 있다는 신호다.","eSum":"The Panama Canal Authority is preparing to tighten draught limits for neopanamax vessels again, another sign that water risk is re-emerging as a structural issue.","kImp":"호르무즈 봉쇄와 수에즈 할증료 인상이 겹친 상황에서 파나마운하 제약까지 더해지면 3대 요충지가 동시에 압박받는 초유의 상황이 된다.","eImp":"With Hormuz blockaded and Suez surcharges rising, added Panama constraints would put all three major chokepoints under simultaneous pressure.","url":"https://splash247.com/panama-canal-tightens-draught-limits-again/"},{"code":"GEO","title":"트럼프, 이란 봉쇄 재개·호르무즈 수호자 선언·화물가액 20% 부과 제안","src":"gCaptain","date":"2026-07-13","kSum":"트럼프 대통령이 이란 해운에 대한 봉쇄를 재개한다고 발표하면서, 호르무즈 해협을 통과하는 화물에 대해 화물가액의 20%를 보호 대가로 부과하는 방안을 제시했다.","eSum":"President Trump announced the US will reinstate its blockade of Iranian shipping while proposing to charge 20% of cargo value for transiting the Strait of Hormuz, declaring the US guardian of Hormuz.","kImp":"국제 해협의 통항 자유 원칙(UNCLOS)에 정면 배치되는 제안으로, 실행 시 해운 비용 구조와 국제 해양법 질서 자체가 재편될 수 있다.","eImp":"A proposal that directly contradicts UNCLOS transit-passage principles; if implemented it could reshape shipping cost structures and the law-of-the-sea order itself.","url":"https://gcaptain.com/trump-reinstates-iran-blockade-declares-u-s-guardian-of-the-hormuz-strait-proposes-20-cargo-fee/"},{"code":"GEO","title":"IMO 이사회, 통항 자유 재확인·상선 공격 규탄 결의","src":"gCaptain","date":"2026-07-13","kSum":"IMO 이사회 제137차 회기에서 국제 해협의 통항 자유를 재확인하고 상선에 대한 공격을 규탄하며 호르무즈 해협의 자유로운 통항을 촉구하는 결의를 채택했다.","eSum":"The IMO Council adopted a resolution at its 137th session reaffirming freedom of navigation through international straits, condemning attacks on commercial vessels and calling for unhindered transit through the Strait of Hormuz.","kImp":"IMO의 결의는 법적 구속력은 없으나, 선원 보호와 통항권에 관한 국제적 규범 기준을 제시해 향후 보험·용선 분쟁의 준거로 활용될 수 있다.","eImp":"Non-binding, but it sets an international normative benchmark on seafarer protection and transit rights that may be invoked in future insurance and charterparty disputes.","url":"https://gcaptain.com/imo-council-reaffirms-freedom-of-navigation-condemns-attacks-on-commercial-shipping/"},{"code":"GEO","title":"우크라이나, 아조프해에서 유조선·건화물선 추가 타격 주장","src":"gCaptain","date":"2026-07-07","kSum":"우크라이나가 아조프해에서 러시아 그림자 선단 유조선 8척과 건화물선, 페리를 드론으로 타격했다고 발표했다. 우크라이나 드론전 사령관은 산업적 규모의 성과라고 표현했다.","eSum":"Ukraine said drone strikes hit eight Russian shadow-fleet tankers plus a dry-cargo vessel and a ferry in the Sea of Azov, with its drone commander describing industrial-scale results.","kImp":"상선에 대한 조직적 드론 공격이 정례화되면서, 흑해권 선박의 전쟁위험 담보 확보가 사실상 불가능해질 수 있다.","eImp":"With systematic drone attacks on merchant ships becoming routine, obtaining war-risk cover for Black Sea-region tonnage may become effectively impossible.","url":"https://gcaptain.com/ukraine-says-it-hit-more-oil-and-dry-cargo-ships-in-sea-of-azov/"},{"code":"GEO","title":"KOBC: 컨테이너 해운에서 지정학이 수급을 압도","src":"The Loadstar","date":"2026-07-10","kSum":"한국해양진흥공사(KOBC)는 향후 상당 기간 컨테이너 해운에 미치는 영향에서 지정학적 요인이 순수한 수급 논리를 능가할 것이라고 전망했다.","eSum":"Korea Ocean Business Corporation (KOBC) says geopolitics will have a greater impact on container shipping in the foreseeable future than pure supply and demand.","kImp":"국내 정책금융기관의 공식 진단으로, 한국 선사의 선대 운용 및 투자 의사결정에서 지정학 리스크 프리미엄 반영이 불가피해졌다.","eImp":"An official assessment from Korea's policy finance institution — Korean owners will now need to embed geopolitical risk premia into fleet deployment and investment decisions.","url":"https://theloadstar.com/geopolitics-now-trumps-supply-and-demand-in-box-shipping-says-kobc/"},{"code":"GEO","title":"걸프테이너, 호르 파칸 확장 통해 대규모 물류 구상 발표","src":"The Loadstar","date":"2026-07-09","kSum":"호르 파칸 항만을 보유한 아랍에미리트 사업자 걸프테이너가 대규모 처리능력 확장 계획을 공개했다. 호르무즈 해협 외곽에 위치한 입지적 강점을 활용하려는 전략이다.","eSum":"Gulftainer, the Emirati owner of Khor Fakkan port, unveiled a major capacity expansion, leveraging the port's position outside the Strait of Hormuz.","kImp":"호르무즈 봉쇄 장기화에 대비해 해협 외곽 환적 허브로의 물류 재편이 가속화되고 있으며, 제벨알리 등 걸프 내부 항만의 상대적 지위 약화가 예상된다.","eImp":"Logistics is being restructured toward transhipment hubs outside the strait as the Hormuz blockade persists, likely eroding the relative standing of inner-Gulf ports such as Jebel Ali.","url":"https://theloadstar.com/gulftainer-unveils-major-logistics-ambitions-for-khor-fakkan-expansion/"},{"code":"GEO","title":"EU 3유로 관세? 쉬인·테무는 이미 우회로를 구축","src":"The Loadstar","date":"2026-07-10","kSum":"EU가 도입하려는 소액 화물 3유로 관세에 대해, 쉬인과 테무가 이미 EU 역내 물류거점을 통한 우회 구조를 완성했다는 분석이 제기됐다.","eSum":"Analysis suggests Shein and Temu have already built bypass structures via in-EU fulfilment ahead of the EU's proposed EUR 3 customs duty on low-value parcels.","kImp":"전자상거래 관세 정책이 항공·해상 혼재화물 흐름을 재편하고 있으며, 아시아-유럽 항로의 화물 구성 변화로 이어질 수 있다.","eImp":"E-commerce duty policy is reshaping air/sea consolidated cargo flows and may alter the cargo mix on the Asia-Europe trade.","url":"https://theloadstar.com/the-eus-e3-customs-duty-shein-and-temu-already-built-the-bypass/"},{"code":"GEO","title":"우크라이나, 아조프해 그림자 선단 유조선 드론 타격 발표","src":"SAFETY4SEA","date":"2026-07-08","kSum":"우크라이나가 아조프해에서 러시아 그림자 선단 유조선을 겨냥한 드론 공격을 감행했다고 발표했다. 우크라이나는 러시아 석유·석유제품을 운송하는 유조선이 전쟁 자금을 직접 조달하므로 합법적 군사 표적이 될 수 있다고 주장했다.","eSum":"Ukraine announced drone strikes targeting Russian shadow-fleet tankers in the Sea of Azov, arguing that tankers carrying Russian oil directly finance the war effort and may therefore be legitimate military targets.","kImp":"상선을 군사 표적으로 규정하는 법적 논리가 확산될 경우, 제재 대상 선박뿐 아니라 일반 상선의 안전 담보 체계 전반이 흔들릴 수 있다.","eImp":"If the legal rationale for treating merchant ships as military targets spreads, it could destabilise safety assurances for commercial shipping well beyond sanctioned tonnage.","url":"https://safety4sea.com/ukraine-says-drone-strikes-hit-shadow-fleet-tankers-in-sea-of-azov/"},{"code":"GEO","title":"영상 | 우크라이나, 크림 향발 러시아 그림자 선단 공격 강화","src":"Baird Maritime","date":"2026-07-08","kSum":"우크라이나가 크림반도로 향하는 러시아 그림자 선단에 대한 공격을 대폭 강화했다. 72시간 동안 유조선 19척을 포함해 21척이 피격된 것으로 보고됐다.","eSum":"Ukraine has sharply intensified strikes on the Crimea-bound Russian shadow fleet, with 21 vessels — including 19 tankers — reported hit over a 72-hour period.","kImp":"크림 연료 보급선 차단이 목표로, 러시아의 흑해 물류 취약성이 드러나면서 해당 해역 운항 선박의 보험·용선 조건이 급격히 악화될 전망이다.","eImp":"Aimed at cutting Crimea's fuel lifeline; the exposure of Russian Black Sea logistics vulnerability will sharply worsen insurance and chartering terms for vessels in the area.","url":"https://www.bairdmaritime.com/security/incidents/acts-of-war/video-ukraine-intensifies-strikes-on-crimea-bound-russian-shadow-fleet"}]},{"code":"TW","type":"news","kTitle":"Section 18. TradeWinds 선박관리","eTitle":"Section 18. TradeWinds Ship Management","items":[{"code":"TW","title":"그리스 파이오니어 마린, NRP 지원 벌크선 매입 후 확장 준비","src":"TradeWinds","date":"2026-07-08","kSum":"그리스 선사 파이오니어 마린이 NRP가 지원한 최신 벌크선 매입을 마무리하며 추가 확장에 나설 채비를 갖췄다.","eSum":"Greece's Pioneer Marine is primed for further expansion after completing its latest NRP-backed bulker acquisition.","kImp":"선박관리사가 자산 확보와 관리선대 확장을 병행하는 모델로, 관리 수익 기반 확대 전략의 전형을 보여준다.","eImp":"An example of a manager pairing asset acquisition with managed-fleet growth — a template for expanding a management-fee revenue base.","url":"https://www.tradewindsnews.com/bulkers/greece-s-pioneer-marine-primed-for-expansion-after-latest-nrp-backed-buy/2-1-2014428"},{"code":"TW","title":"하이드마, 네덜란드·터키 선박관리사 인수로 50척 규모 확대","src":"TradeWinds","date":"2026-07-07","kSum":"하이드마(Heidmar)가 네덜란드 선박관리·선원공급 업체 Q-Shipping을 인수해 9척을 추가했다. 이로써 상업관리 약 50척, 기술관리 16척 체제를 갖췄으며 네덜란드·터키 거점과 우크라이나 선원공급 조직을 확보했다.","eSum":"Heidmar acquired Dutch ship management and crewing firm Q-Shipping, adding nine vessels. It now commercially manages around 50 ships and technically manages 16, gaining an operating presence in the Netherlands and Turkiye plus a Ukrainian crewing operation.","kImp":"최소 자본으로 관리선대와 지리적 거점을 동시에 확보한 자산경량화(asset-light) 성장 전략의 사례로, 선박관리 시장의 통합 가속을 시사한다.","eImp":"A textbook asset-light growth play — managed fleet and geographic reach acquired with minimal capital — signalling accelerating consolidation in ship management.","url":"https://www.tradewindsnews.com/ship-management/heidmar-swells-to-50-vessels-after-buyout-of-dutch-turkish-shop/2-1-2014224"},{"code":"TW","title":"호주 보고서: 선원 불만 1위는 근로시간과 임금","src":"TradeWinds","date":"2026-07-02","kSum":"호주 당국 보고서에 따르면 선원들이 제기한 불만 중 근로시간과 임금 문제가 가장 많은 비중을 차지한 것으로 나타났다.","eSum":"An Australian report finds working hours and wages top the list of complaints raised by seafarers.","kImp":"MLC 준수 점검에서 근로시간·임금이 최우선 지적 항목이 되고 있어, 선박관리사의 기록 관리와 PSC 대응 체계 강화가 요구된다.","eImp":"Hours and wages are becoming the leading MLC compliance findings, requiring managers to tighten record-keeping and PSC readiness.","url":"https://www.tradewindsnews.com/ship-management/working-hours-and-wages-top-list-of-seafarer-complaints-australian-report-finds/2-1-2011164"},{"code":"TW","title":"2030년까지 해기사 11만 3,000명 이상 추가 필요","src":"TradeWinds","date":"2026-06-30","kSum":"해운업계가 2030년까지 11만 3,000명 이상의 신규 해기사를 확보해야 한다는 전망이 제시됐다.","eSum":"Shipping needs more than 113,000 new officers by 2030, according to industry projections.","kImp":"해기사 수급 부족이 구조화되면서 선박관리사의 인력 확보 비용과 이직률 관리가 핵심 경쟁력으로 부상한다.","eImp":"With the officer shortfall becoming structural, recruitment cost and retention management are emerging as core competitive factors for ship managers.","url":"https://www.tradewindsnews.com/ship-management/shipping-needs-more-than-113-000-new-officers-by-2030/2-1-2009420"},{"code":"TW","title":"노조·변호사, 기소된 선원의 본국 재판 촉구","src":"TradeWinds","date":"2026-06-29","kSum":"선원 노조와 법률 전문가들이 형사 기소된 선원을 본국에서 재판받도록 해야 한다고 촉구했다. 외국 관할에서의 장기 구금 문제가 배경이다.","eSum":"A seafarers' union and a maritime lawyer urged that accused crews be tried in their home countries, citing prolonged detention in foreign jurisdictions.","kImp":"선원 범죄화(criminalisation) 이슈가 재부상하고 있어, 선박관리사의 선원 법률지원 체계와 P&I 담보 범위 점검이 필요하다.","eImp":"The criminalisation-of-seafarers issue is resurfacing, warranting a review of managers' crew legal-support arrangements and P&I cover scope.","url":"https://www.tradewindsnews.com/law/try-accused-crews-in-their-home-countries-union-and-lawyer-urge/2-1-2008867"},{"code":"TW","title":"바퀴를 다시 발명하지 말라 — 선원 위기에 대한 노조 수장의 일갈","src":"TradeWinds","date":"2026-06-29","kSum":"선원 노조 수장이 반복되는 선원 위기 대응과 관련해 업계가 이미 존재하는 해법을 놔두고 매번 새로운 틀을 만들려 한다며 비판했다.","eSum":"A union chief criticised the industry for repeatedly reinventing frameworks to address seafarer crises instead of applying solutions that already exist.","kImp":"코로나 교대 위기, 호르무즈 사태 등 반복되는 선원 위기에 대해 표준화된 대응 프로토콜 부재가 지적되고 있다.","eImp":"Highlights the absence of a standardised response protocol for recurring seafarer crises — from Covid crew change to the current Hormuz situation.","url":"https://www.tradewindsnews.com/sustainability/stop-reinventing-the-wheel-union-chief-on-seafarer-crises/2-1-2008764"},{"code":"TW","title":"e-farer의 부상 — 선원 증서의 클라우드 전환","src":"TradeWinds","date":"2026-06-28","kSum":"선원 자격증서 관리가 클라우드 기반으로 이전되면서 이른바 e-farer라 불리는 디지털 증서 체계가 확산되고 있다.","eSum":"Crew certification is moving to the cloud, giving rise to the so-called e-farer — digital certificate management.","kImp":"증서 위변조 방지와 승선 배치 속도 개선이 기대되나, 기국별 인정 여부와 사이버 보안이 선결 과제다.","eImp":"Promises reduced certificate fraud and faster crew deployment, but flag-state recognition and cyber security remain prerequisites.","url":"https://www.tradewindsnews.com/technology/the-rise-of-the-e-farer-as-crew-certification-goes-into-the-cloud/2-1-2007338"},{"code":"TW","title":"키프로스 선주, 엘렛슨 가스 LPG선 2척 관리권 인수","src":"TradeWinds","date":"2026-06-25","kSum":"키프로스 선주가 엘렛슨 가스(Eletson Gas) 소속 LPG 운반선 2척의 관리권을 인수했다.","eSum":"A Cypriot shipowner has taken over management of two Eletson Gas LPG carriers.","kImp":"엘렛슨 그룹의 구조조정 여파로 관리권이 이전되는 사례로, 분쟁 중인 선대의 관리 이전 시 승계 리스크 관리가 중요하다.","eImp":"A management transfer stemming from the Eletson group restructuring — succession risk management matters when taking over disputed fleets.","url":"https://www.tradewindsnews.com/gas/cypriot-owner-takes-over-management-of-two-eletson-gas-lpg-carriers/2-1-2003378"},{"code":"TW","title":"BSM, 베테랑 비외른 스프로테 퇴임과 함께 경영진 개편","src":"TradeWinds","date":"2026-06-23","kSum":"베른하르트 슐테 십매니지먼트(BSM)가 업계 베테랑 비외른 스프로테(Bjoern Sprotte)의 퇴임에 맞춰 경영진 개편을 단행했다.","eSum":"Bernhard Schulte Shipmanagement (BSM) announced management changes as industry veteran Bjoern Sprotte moves on.","kImp":"세계 최대급 선박관리사의 리더십 교체로, 향후 BSM의 선대 전략 및 서비스 포트폴리오 변화 가능성을 주시할 필요가 있다.","eImp":"A leadership change at one of the world's largest ship managers — worth watching for shifts in BSM's fleet strategy and service portfolio.","url":"https://www.tradewindsnews.com/ship-management/bsm-rings-in-management-changes-as-industry-veteran-bjoern-sprotte-moves-on/2-1-2000101"},{"code":"TW","title":"스위스 ABC 마리타임, 신규 탱커사 설립 후 선복 확보 의욕","src":"TradeWinds","date":"2026-06-23","kSum":"스위스 선주 ABC 마리타임이 새로운 탱커 회사를 설립한 뒤 추가 선복 확보에 적극 나서고 있다.","eSum":"Swiss shipowner ABC Maritime is hungry for tonnage after forming a new tanker firm.","kImp":"탱커 시황 강세를 배경으로 한 신규 진입으로, 관리선대 확대에 따른 기술관리 역량 확보가 관건이다.","eImp":"A new entrant riding tanker market strength; securing technical management capability alongside fleet growth will be the key challenge.","url":"https://www.tradewindsnews.com/tankers/swiss-owner-abc-maritime-hungry-for-tonnage-after-forming-new-tanker-firm/2-1-2000291"},{"code":"TW","title":"호르무즈 봉쇄 장기화로 연료비 상승, 선박 벙커링 우회 불가피","src":"TradeWinds","date":"2026-06-22","kSum":"호르무즈 해협 봉쇄가 이어지면서 연료 가격이 계속 상승하고 있으며, 선박들이 벙커링을 위해 항로를 우회할 수밖에 없는 상황이 이어지고 있다.","eSum":"The Strait of Hormuz closure continues to push fuel prices up, with vessels forced to reroute for bunkers.","kImp":"벙커링 거점 재편은 선박관리사의 운항 계획·연료 조달 전략에 직접적 영향을 미치며, 우회에 따른 운항일수 증가가 비용으로 전가된다.","eImp":"The reshaping of bunkering hubs directly affects managers' voyage planning and fuel procurement, with added steaming days passed through as cost.","url":"https://www.tradewindsnews.com/ship-management/strait-of-hormuz-closure-continues-to-hit-fuel-prices-as-vessels-forced-to-reroute-for-bunkers/2-1-1997982"}]},{"code":"HOT","type":"news","kTitle":"Section 19. 핫이슈: 호르무즈 해협","eTitle":"Section 19. Hot Topic: Strait of Hormuz","items":[{"code":"HOT","title":"미국-이란 상호 공격 속 선박들, 트랜스폰더 끄고 호르무즈 은밀 통항","src":"gCaptain","date":"2026-07-13","kSum":"미국과 이란의 교전 격화로 공개 통항이 사실상 중단된 가운데, 일부 선박이 트랜스폰더를 끈 채 호르무즈를 통과하고 있다. 일요일 통항한 6척의 상선 전원이 트랜스폰더를 끈 상태였으며, 이른바 다크 통항이 3일 연속 공개 통항을 앞질렀다.","eSum":"With observable crossings all but ceased amid intensified US-Iran fighting, ships are transiting Hormuz with transponders off. All six commodity carriers that crossed on Sunday went dark, and dark crossings outnumbered observable passages for three straight days.","kImp":"정상 선단의 다크 운항 확산은 AIS 기반 리스크 관리·제재 스크리닝 체계의 실효성을 근본적으로 훼손하며, 충돌 위험도 증가시킨다.","eImp":"Mainstream tonnage going dark fundamentally undermines AIS-based risk management and sanctions screening, while raising collision risk.","url":"https://gcaptain.com/ships-transit-hormuz-in-secret-as-us-and-iran-trade-strikes/"},{"code":"HOT","title":"호르무즈 통항량 수주 내 최저치로 급감","src":"gCaptain","date":"2026-07-13","kSum":"7월 12일 일요일 호르무즈 해협 통항 선박이 6척으로 5주 만의 최저치를 기록했다. 이란산 원유 200만 배럴을 실은 VLCC Humanity호와 쿠웨이트산 석유제품 50만 배럴을 실은 Capetan Andreas호가 빠져나갔고, 주말간 LNG선의 진입은 관측되지 않았다.","eSum":"Just six vessels transited the Strait of Hormuz on Sunday 12 July, the lowest in five weeks. Exiting tankers included VLCC Humanity with 2m barrels of Iranian crude and Capetan Andreas with about 500,000 barrels of Kuwaiti products; no LNG tankers were seen entering over the weekend.","kImp":"LNG 선박의 통항 중단은 카타르發 LNG 공급 차질로 직결되며, 아시아 LNG 현물가와 유럽 에너지 안보에 즉각적 영향을 미친다.","eImp":"The halt in LNG transits translates directly into Qatari LNG supply disruption, with immediate effects on Asian spot LNG prices and European energy security.","url":"https://gcaptain.com/hormuz-traffic-slows-to-multi-week-low-as-renewed-us-iran-strikes-raise-safety-risk/"},{"code":"HOT","title":"미국, 화요일부터 이란 해상 봉쇄 재개","src":"gCaptain","date":"2026-07-13","kSum":"미국이 이란 항만 출입 상선에 대한 봉쇄를 화요일부터 재개한다고 발표했다. 봉쇄 해제 한 달도 채 되지 않아 다시 제한 조치가 복원되는 것이다.","eSum":"The United States announced it will resume enforcing its maritime blockade of Iran from Tuesday, restoring restrictions on commercial shipping to and from Iranian ports less than a month after lifting them.","kImp":"봉쇄 재개는 이란산 원유를 취급하는 그림자 선단뿐 아니라 정상 선사의 걸프 기항 리스크도 높여, 용선계약상 안전항 조항 분쟁이 늘어날 전망이다.","eImp":"The renewed blockade raises Gulf-calling risk for mainstream owners as well as the Iran-linked shadow fleet, and is likely to drive more safe-port disputes under charterparties.","url":"https://gcaptain.com/u-s-to-resume-maritime-blockade-of-iran-on-tuesday-as-hormuz-tensions-escalate/"},{"code":"HOT","title":"호르무즈 충돌 격화로 유가 급등","src":"gCaptain","date":"2026-07-12","kSum":"미국과 이란이 새로운 공격을 주고받으면서 유가가 급등했다. 양측은 호르무즈 해협의 개방 여부를 두고 상반된 입장을 내놓고 있다.","eSum":"Oil jumped as the US and Iran exchanged fresh strikes, with the two sides offering conflicting statements on whether the Strait of Hormuz is open.","kImp":"유가 급등은 벙커유 가격 상승으로 직결되어 전 선종의 운항비를 압박하며, 특히 연료비 비중이 큰 컨테이너선 수익성에 타격이 크다.","eImp":"The oil spike feeds straight into bunker prices, squeezing operating costs across all segments and hitting container-ship margins hardest given their fuel intensity.","url":"https://gcaptain.com/oil-jumps-as-conflict-over-hormuz-escalates-with-fresh-strikes/"},{"code":"HOT","title":"컨테이너선 피격으로 호르무즈 보안 상황 붕괴","src":"Splash247","date":"2026-07-13","kSum":"글로벌 피더 시핑이 운영하는 7,000TEU급 컨테이너선이 피격되면서 호르무즈 해협의 보안 상황이 급격히 악화됐다. 인도 선원 1명이 사망하고 8명이 부상했다.","eSum":"Security in the Strait of Hormuz deteriorated sharply after a 7,000 teu container vessel operated by Global Feeder Shipping was struck; an Indian seafarer was killed and eight crew injured.","kImp":"선원 사망 사고 발생으로 선원 노조의 항행 거부 요구가 확산될 가능성이 크며, 걸프 항로 배승 협상이 난항을 겪을 전망이다.","eImp":"A seafarer fatality will likely fuel union demands for refusal to sail, making crewing negotiations for Gulf voyages considerably harder.","url":"https://splash247.com/hormuz-security-collapses-after-boxship-attack/"},{"code":"HOT","title":"컨테이너선 피격·호르무즈 재폐쇄, 중동 운임 팬데믹 정점 넘어서","src":"The Loadstar","date":"2026-07-13","kSum":"미국-이란 충돌 재개로 호르무즈가 사실상 재폐쇄되면서 걸프 수입업체와 포워더들이 다시 중동 육상 연계(landbridge) 경로로 눈을 돌리고 있다. 중동 항로 운임은 팬데믹 정점을 상회했다.","eSum":"With renewed US-Iran conflict effectively closing Hormuz again, Gulf importers and forwarders are once more turning to Middle East landbridge routes, and Middle East rates have sailed past their pandemic peak.","kImp":"운임이 팬데믹 최고치를 넘어선 것은 대체 경로의 물리적 한계를 의미하며, 걸프 수입 화주의 물류비 부담이 임계점에 도달했음을 시사한다.","eImp":"Rates exceeding pandemic highs reflect the physical limits of alternative routings and suggest Gulf importers' logistics costs have reached a breaking point.","url":"https://theloadstar.com/box-ship-attacked-hormuz-shut-again-middle-east-rates-sail-past-pandemic-peak/"},{"code":"HOT","title":"트럼프의 휴전 종료 선언에 호르무즈 통항 붕괴","src":"Splash247","date":"2026-07-09","kSum":"미국의 이틀 연속 공습 이후 목요일 호르무즈 해협 통항이 사실상 중단됐다. 트럼프 대통령이 휴전이 끝났다고 선언한 직후다.","eSum":"Traffic through the Strait of Hormuz came to a near standstill on Thursday after a second consecutive day of US strikes, following Trump's declaration that the ceasefire was over.","kImp":"6월 체결된 미-이란 양해각서(MoU) 체제가 완전히 붕괴되면서, 외교적 해결에 기댄 시황 회복 시나리오는 당분간 유효성을 잃었다.","eImp":"With the June US-Iran MoU framework fully collapsed, market-recovery scenarios premised on a diplomatic settlement are off the table for now.","url":"https://splash247.com/hormuz-traffic-collapses-as-trump-declares-ceasefire-over/"},{"code":"HOT","title":"카타르 LNG선, 호르무즈 통항 시도 후 유턴","src":"gCaptain","date":"2026-07-13","kSum":"카타르 소속 LNG 운반선들이 호르무즈 해협 진입을 시도했다가 방향을 돌려 되돌아간 것으로 확인됐다. 안보 상황 재악화와 선원 안전 우려, 전쟁위험보험 조건 미확정이 겹치며 카타르에너지의 수출 정상화 시도가 다시 좌초됐다.","eSum":"Qatari LNG carriers attempted to enter the Strait of Hormuz but turned around and reversed course. Renewed security deterioration, crew safety concerns and unsettled war-risk terms have again stalled QatarEnergy's push to restore exports.","kImp":"세계 LNG 물동량의 약 20%를 차지하는 카타르 수출이 재개-중단을 반복하면서 아시아 LNG 현물가와 용선료 변동성이 확대되고 있다.","eImp":"Qatar accounts for roughly a fifth of global LNG trade; repeated stop-start export attempts amplify Asian spot LNG price and LNG charter-rate volatility.","url":"https://gcaptain.com/qatar-lng-vessels-u-turn-after-attempt-to-pass-through-hormuz/"},{"code":"HOT","title":"긴장 재고조에도 LNG선·일본계 선박 호르무즈 통항 증가","src":"gCaptain","date":"2026-07-09","kSum":"중동 긴장이 재차 고조되는 가운데 GasLog Shanghai를 비롯한 발라스트 LNG선 최소 5척과 일본계 선박들이 호르무즈 해협을 통항했다. Al Samriya, Al Dafna, Al Gattara, Al Rayyan 등 카타르에너지 연계 선박이 포함됐다.","eSum":"Despite renewed Middle East tensions, at least five ballast LNG carriers including GasLog Shanghai plus several Japan-linked vessels transited the Strait of Hormuz. QatarEnergy-linked ships Al Samriya, Al Dafna, Al Gattara and Al Rayyan were among them.","kImp":"서방계 선박이 통항을 기피하는 사이 비서방·아시아계 선박이 위험을 감수하며 통항하는 통항 선단의 국적 분화 현상이 뚜렷해지고 있다.","eImp":"A clear bifurcation is emerging: Western-affiliated tonnage avoids or goes dark while Asian and non-Western owners accept the risk, reshaping who carries Gulf cargoes.","url":"https://gcaptain.com/more-lng-japan-linked-vessels-transit-hormuz-despite-renewed-mideast-tensions/"},{"code":"HOT","title":"카타르, LNG선 피격 공식 확인 — 호르무즈·홍해 동시 피격","src":"Riviera Maritime Media","date":"2026-07-08","kSum":"카타르 정부가 자국 LNG 운반선에 대한 공격을 공식 확인한 가운데, 같은 시기 호르무즈 해협과 홍해에서 복수의 상선이 공격을 받았다. 두 개의 초크포인트가 동시에 위협받으면서 아시아-유럽 항로 전체가 압박을 받고 있다.","eSum":"Qatar officially confirmed the attack on its LNG carrier as multiple merchant ships came under fire in both the Strait of Hormuz and the Red Sea. With two chokepoints threatened simultaneously, the entire Asia-Europe trade lane is under pressure.","kImp":"호르무즈와 홍해가 동시에 위험구역이 되면서 우회 대안이 사실상 소멸, 톤-마일 급증과 유효선복 감소가 동시에 발생하고 있다.","eImp":"With Hormuz and the Red Sea both hostile, viable diversion options have effectively vanished, driving simultaneous tonne-mile inflation and effective capacity loss.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/qatar-confirms-attack-on-lng-carrier-as-ships-come-under-fire-in-hormuz-and-red-sea-89304"},{"code":"HOT","title":"카타르에너지 LNG선, 1주일간의 호르무즈 회피 끝내고 통항 재개","src":"TradeWinds","date":"2026-07-14","kSum":"카타르에너지 소속 LNG 운반선이 약 1주일간 이어진 호르무즈 해협 회피를 끝내고 통항을 재개했다. 피격 사건 이후 중단됐던 수출 흐름이 재개 신호를 보이고 있으나, 선사들은 여전히 통항 시점을 사안별로 결정하고 있다.","eSum":"A QatarEnergy LNG carrier has ended a week-long fresh avoidance of the Strait of Hormuz and resumed transit. Export flows suspended after the strike are showing signs of restarting, though owners are still deciding transit timing case by case.","kImp":"LNG 수출 흐름의 재개-중단이 주 단위로 반복되면서, 장기 계약 이행과 현물시장 수급 예측이 극도로 어려워지고 있다.","eImp":"Weekly stop-start cycles in LNG export flows make long-term contract performance and spot-market supply forecasting extremely difficult.","url":"https://www.tradewindsnews.com/gas/qatarenergy-lng-carrier-ends-week-long-fresh-avoidance-of-strait-of-hormuz/2-1-2013130"},{"code":"HOT","title":"호르무즈 같은 고위험 해역, 무인 운항이 답이 될 수 있나","src":"Maritime Executive","date":"2026-07-12","kSum":"호르무즈처럼 미사일·드론·전자전 위협이 상존하는 고위험 해역에서 기존 선박을 최소인원 또는 무인으로 운항할 수 있는지에 대한 실무적 검토가 제기됐다. 원격 감시, 자동 기관 감시, 통항 구간 한정 무인화 등이 논의되나 규정·보험·기술적 제약이 크다.","eSum":"An examination of whether existing ships could be operated with minimal or no crew through high-risk zones like Hormuz, where missile, drone and electronic-warfare threats persist. Remote monitoring, unattended machinery and segment-limited unmanned transits are discussed, but regulatory, insurance and technical constraints are significant.","kImp":"선원을 전투 위험에 노출시키지 않는 대안 논의가 본격화되면서, 자율운항 기술의 상업적 도입 명분이 안전 측면에서 새롭게 형성되고 있다.","eImp":"Debate over removing seafarers from combat exposure is giving autonomous-navigation technology a new, safety-driven commercial rationale.","url":"https://maritime-executive.com/editorials/could-existing-ships-operate-without-crew-in-high-risk-zones-like-hormuz"}]},{"code":"SYS","type":"news","kTitle":"Section 20. 시스템·앱","eTitle":"Section 20. System & App","items":[{"code":"SYS","title":"MOL, IBM 재팬과 AI 선박운항 플랫폼 출시","src":"Smart Maritime Network","date":"2026-07-01","kSum":"미쓰이OSK라인(MOL)이 IBM 재팬과 공동으로 선박 운항 관련 데이터를 통합하는 AI 기반 플랫폼을 개발해 출시했다. 운항 의사결정 개선을 목표로 한다.","eSum":"Mitsui O.S.K. Lines and IBM Japan jointly developed and launched an AI-powered platform integrating a range of vessel operations data to improve operational decision-making.","kImp":"대형 선사가 글로벌 IT 기업과 직접 손잡고 자체 AI 운항 플랫폼을 구축하는 흐름을 보여준다. 선사의 IT 내재화 전략 사례로 참고할 만하다.","eImp":"Shows major carriers partnering directly with global IT firms to build proprietary AI operations platforms — a reference case for in-housing maritime IT capability.","url":"https://smartmaritimenetwork.com/2026/07/01/mol-launches-ai-operations-platform-with-ibm-japan/"},{"code":"SYS","title":"SpecTec, AMOS에 조달 플랫폼 추가","src":"Smart Maritime Network","date":"2026-06-17","kSum":"SpecTec가 자사 선박 자산관리 소프트웨어 AMOS에 e-조달 플랫폼을 통합 추가했다. 정비·재고·조달을 단일 플랫폼에서 처리하는 방향을 강화했다.","eSum":"SpecTec added a procurement platform to its AMOS maritime asset management software, strengthening its move toward handling maintenance, inventory and procurement on a single integrated platform.","kImp":"AMOS는 국내외 선사 기술팀이 널리 쓰는 PMS로, 조달 모듈 통합은 별도 e-procurement 벤더 의존도를 낮춘다.","eImp":"AMOS is a widely used PMS among ship managers; embedding procurement reduces reliance on separate e-procurement vendors.","url":"https://smartmaritimenetwork.com/2026/06/17/spectec-adds-procurement-platform-to-amos/"},{"code":"SYS","title":"StormGeo, Alfa Laval 센서 데이터 통합해 선박 성능 추적","src":"Smart Maritime Network","date":"2026-06-01","kSum":"StormGeo가 Voyage Intelligence 플랫폼에 선내 에너지 소비 기기의 센서 데이터를 통합, 모회사 Alfa Laval과 공동 프로젝트로 엔진·선체 데이터 수집을 자동화한다.","eSum":"StormGeo expanded its Voyage Intelligence platform by integrating shipboard sensor data, starting with a joint project with parent company Alfa Laval to automate collection of engine and hull data.","kImp":"기상·항로 데이터와 기기 센서 데이터를 결합해 선체 청소·엔진 튜닝 등 선제적 조치를 판단하는 방향. 기술팀 의사결정 도구로 직결된다.","eImp":"Combining weather/routing data with equipment sensor data to inform proactive measures like hull cleaning or engine tuning — directly relevant to technical team decisions.","url":"https://smartmaritimenetwork.com/2026/06/01/stormgeo-integrates-alfa-laval-sensor-data-for-vessel-performance-tracking/"},{"code":"SYS","title":"Navarino, Palo Alto Networks와 해양 사이버보안 플랫폼 출시","src":"Smart Maritime Network","date":"2026-06-03","kSum":"해양 통신·IT 기업 Navarino가 Palo Alto Networks와 파트너십을 맺고 선박용 사이버보안 플랫폼을 출시했다.","eSum":"Maritime communications and IT provider Navarino partnered with Palo Alto Networks to launch a cyber security platform for vessels.","kImp":"IMO 사이버 리스크 관리 요건과 선급 규정 강화 속에서, 엔터프라이즈급 보안 벤더의 해양 시장 진입이 본격화되고 있다.","eImp":"Enterprise-grade security vendors are entering the maritime market as IMO cyber risk management requirements and class rules tighten.","url":"https://smartmaritimenetwork.com/2026/06/03/navarino-partners-with-palo-alto-networks-to-launch-cyber-platform/"},{"code":"SYS","title":"Navarino, NEMO 출시하며 운영기술(OT) 시장 진출","src":"Smart Maritime Network","date":"2026-05-26","kSum":"Navarino가 선대 인텔리전스 플랫폼 NEMO를 출시하며 선박 운영기술(OT) 영역으로 사업을 확장했다.","eSum":"Navarino entered the operational technology market with the launch of NEMO, a fleet intelligence platform.","kImp":"IT 통신 사업자가 OT 영역으로 확장하며 선박 IT/OT 경계가 흐려지고 있다. 통합 벤더 관리 전략 재검토가 필요하다.","eImp":"IT/communications providers expanding into OT blurs the shipboard IT/OT boundary, prompting a rethink of integrated vendor management.","url":"https://smartmaritimenetwork.com/2026/05/26/navarino-enters-operational-technology-market-with-launch-of-nemo/"},{"code":"SYS","title":"Veson Nautical, AI 우산 아래 소프트웨어 제품군 통합","src":"Smart Maritime Network","date":"2026-06-30","kSum":"Veson Nautical이 IMOS, CoCaptain, Mail, 신규 Vessel Insights·Bunker Insights를 단일 인터페이스로 묶은 통합 Veson Platform을 발표했다. 기존 IMOS 고객은 요청 시 추가 비용 없이 사용 가능하다.","eSum":"Veson Nautical announced the unified, AI-powered Veson Platform bringing together IMOS, CoCaptain, Mail and the newly released Vessel Insights and Bunker Insights under a single interface, available to existing IMOS clients at no extra cost on request.","kImp":"IMOS는 용선·항해관리 사실상 표준으로, 플랫폼 통합은 상용 오퍼레이션 워크플로우 전반의 AI 적용 범위를 넓힌다.","eImp":"IMOS is a de facto standard for chartering and voyage management; the platform consolidation widens AI's reach across commercial operations workflows.","url":"https://smartmaritimenetwork.com/2026/06/30/veson-integrates-software-offerings-under-ai-umbrella/"},{"code":"SYS","title":"Navarino, NEMO 선대 인텔리전스 플랫폼 출시","src":"Splash247","date":"2026-05-26","kSum":"Navarino가 선대 인텔리전스 플랫폼 NEMO를 출시했다고 Splash247이 보도했다.","eSum":"Splash247 reported Navarino's launch of the NEMO fleet intelligence platform.","kImp":"선박 통신 사업자의 데이터 플랫폼 전환은 선사 입장에서 통신·데이터·보안 번들 협상 여지를 넓힌다.","eImp":"Communications providers pivoting to data platforms widens owners' room to negotiate bundled connectivity, data and security deals.","url":"https://splash247.com/navarino-launches-nemo-fleet-intelligence-platform/"},{"code":"SYS","title":"Yusen Logistics, Yusen Vantage 디지털 부킹 플랫폼 확대","src":"Container News","date":"2026-07-04","kSum":"유센로지스틱스가 엔터프라이즈 소프트웨어 기업 Liferay와 공동 개발한 Yusen Vantage Focus(YVF Book) 플랫폼 롤아웃을 확대해 항공·해상 부킹을 간소화한다. 실시간 화물 가시성, 중앙집중 문서관리, 구성 가능한 워크플로우를 제공한다.","eSum":"Yusen Logistics expanded rollout of its Yusen Vantage Focus (YVF Book) platform, developed with enterprise software provider Liferay, to simplify air and ocean freight bookings, offering real-time shipment visibility, centralised document management and configurable workflows.","kImp":"물류기업의 자체 부킹 플랫폼 강화는 선사 직접 부킹 채널과의 경쟁 구도에 영향을 준다.","eImp":"Forwarders strengthening proprietary booking platforms affects the competitive dynamic with carriers' direct booking channels.","url":"https://container-news.com/yusen-logistics-expands-digital-freight-booking-with-yusen-vantage-platform/"},{"code":"SYS","title":"HD현대 아비커스, 현대글로비스와 자율운항 솔루션 실증 추진","src":"더구루","date":"2026-06-02","kSum":"아비커스가 그리스 아테네에서 열린 Posidonia 2026에서 현대글로비스, G-Marine Services, 한국선급(KR)과 자율운항 솔루션 실증 및 원격 운항 관제 개념 개발·검증을 위한 MOU를 체결했다.","eSum":"Avikus signed an MOU with Hyundai Glovis, G-Marine Services and Korean Register at Posidonia 2026 in Athens to promote demonstration of autonomous navigation solutions and to develop and validate remote operation control concepts.","kImp":"국내 자율운항 솔루션이 선사·선급과 결합해 원격관제(ROC) 단계로 확장되는 신호. PCTC 운항사에 직접적 함의가 있다.","eImp":"Signals Korean autonomous navigation tech extending into remote operation centre concepts with owners and class — directly relevant to PCTC operators.","url":"https://www.theguru.co.kr/news/article.html?no=102721"},{"code":"SYS","title":"BW LNG, 클라우드 ERP BASSnet Neo 도입 계약","src":"Smart Maritime Network","date":"2026-04-29","kSum":"BW LNG가 BASS Software와 클라우드 기반 BASSnet Neo 해양 ERP 플랫폼 도입 계약을 체결했다. 정비, 자재·재고관리, 조달, 드라이도킹 등 핵심 모듈이 포함된다.","eSum":"BW LNG agreed a contract with BASS Software to implement its cloud-based BASSnet Neo maritime ERP platform, including core modules such as Maintenance, Materials & Inventory Management, Procurement and Dry-Docking.","kImp":"주요 ERP 벤더의 클라우드 네이티브 전환이 실제 대형 선사 계약으로 이어지고 있다. 온프레미스 AMOS/BASSnet 운영사의 마이그레이션 검토 압력이 커진다.","eImp":"Major ERP vendors' cloud-native transition is converting into large owner contracts, increasing migration pressure on operators still on on-premise AMOS/BASSnet.","url":"https://smartmaritimenetwork.com/2026/04/29/bw-lng-to-deploy-cloud-erp-platform/"},{"code":"SYS","title":"Stolt Tankers, 디지털 승선교대 관리 플랫폼 Tilla 도입","src":"Smart Maritime Network","date":"2026-04-28","kSum":"Stolt Tankers가 승선교대 여행 수요 관리를 위해 Tilla의 기술 플랫폼을 도입한다. 선박 스케줄, 크루잉 데이터, 항만대리점 정보, 실시간 항공편 데이터를 통합한다.","eSum":"Stolt Tankers announced plans to adopt Tilla's technology platform to manage crew change travel, integrating vessel schedules, crewing data, port agency information and real-time flight data.","kImp":"승선교대 여행 관리는 크루잉 비용의 큰 축이며, 스케줄·항공 데이터 통합 자동화는 비용과 지연 리스크를 동시에 줄인다.","eImp":"Crew change travel is a major crewing cost line; automating schedule and flight data integration cuts both cost and delay risk.","url":"https://smartmaritimenetwork.com/2026/04/28/stolt-tankers-to-deploy-digital-crew-change-management-platform/"},{"code":"SYS","title":"NAVTOR, 디지털 항해일지 플랫폼 업그레이드","src":"Smart Maritime Network","date":"2026-06-29","kSum":"노르웨이 항해기술 기업 NAVTOR가 디지털 로그북 플랫폼을 업그레이드했다. 규정 보고 자동화와 육상-선박 데이터 연동을 강화해 항해·기관·오일 기록부의 수기 작성 부담을 줄이고 감사 대응력을 높이는 것이 골자다.","eSum":"Norwegian navigation technology firm NAVTOR has upgraded its digital logbook platform, strengthening automated regulatory reporting and ship-shore data integration to cut manual entry in deck, engine and oil record books and improve audit readiness.","kImp":"전자 항해일지는 PSC·감사 대응 시간을 단축시키는 직접적 수단으로, 선원 행정 부담 경감과 데이터 신뢰성 확보를 동시에 노린다.","eImp":"Electronic logbooks directly cut PSC and audit response time, simultaneously easing crew administrative burden and improving data integrity.","url":"https://smartmaritimenetwork.com/2026/06/29/navtor-upgrades-digital-logbook-platform/"},{"code":"SYS","title":"eBL 플랫폼 5곳, IGP&I 플랫폼 간 교환 승인 획득","src":"Splash247","date":"2026-06-10","kSum":"WaveBL, CargoX, edoxOnline, TradeGo, eTEU 등 5개 전자선하증권(eBL) 플랫폼이 DCSA 상호운용성 표준 부속서 v.2를 채택하고 국제P&I그룹(IGP&I) 승인을 받았다. 이로써 서로 다른 플랫폼 간에 법적 확실성과 보험 담보를 유지한 채 eBL 교환이 가능해졌다.","eSum":"Five eBL platforms - WaveBL, CargoX, edoxOnline, TradeGo and eTEU - have adopted the DCSA Standard Annex for eBL Platform Interoperability v.2 and secured International Group of P&I Clubs approval, enabling cross-platform eBL exchange with legal certainty and insurance backing intact.","kImp":"플랫폼 락인(lock-in)이 eBL 확산의 최대 장벽이었던 만큼, 상호운용성 확보는 전면 전자화 목표 달성의 결정적 전환점이다.","eImp":"Platform lock-in was the biggest barrier to eBL adoption; interoperability is a decisive turning point for the industry's full-digitalisation target.","url":"https://splash247.com/five-ebl-platforms-secure-igpi-approval-for-cross-platform-exchange/"},{"code":"SYS","title":"웨스턴 벌크, 전 선대에 제로노스 항해 최적화 도입","src":"Splash247","date":"2026-06-24","kSum":"노르웨이 건화물 운영선사 웨스턴 벌크(Western Bulk)가 운영 선대 전반에 제로노스의 항해 최적화 솔루션을 도입한다. 연료 소모 모델링과 기상 라우팅, CII·EU ETS 노출 관리를 통합해 운항 수익성을 개선하는 것이 목표다.","eSum":"Norwegian dry bulk operator Western Bulk is deploying ZeroNorth's voyage optimisation solution across its operated fleet, integrating fuel consumption modelling, weather routing and CII/EU ETS exposure management to improve voyage profitability.","kImp":"운영선사(operator)형 사업모델에서도 항해 최적화 SaaS가 필수 인프라로 자리 잡으며, 용선 손익 계산에 탄소비용이 상시 반영되고 있다.","eImp":"Voyage optimisation SaaS is becoming essential infrastructure even for asset-light operators, with carbon cost now permanently embedded in voyage P&L.","url":"https://splash247.com/western-bulk-taps-zeronorth-for-voyage-optimisation-across-fleet/"},{"code":"SYS","title":"DCSA, 표준 기반 플랫폼 간 eBL 거래 시연 완료","src":"Container News","date":"2026-05-20","kSum":"디지털컨테이너해운협회(DCSA)가 표준 기반 상호운용 eBL 거래를 완료했다고 발표했다. 서로 다른 eBL 플랫폼에 있는 발행자, 은행, 수하인 간에 공통 기술·법률 프레임워크로 전자선하증권이 이전되는 것을 실증했다.","eSum":"The Digital Container Shipping Association has completed a standards-based interoperable eBL transaction, demonstrating transfer of an electronic bill of lading between issuers, banks and consignees sitting on different eBL platforms under a common technical and legal framework.","kImp":"컨테이너 정기선의 서류 디지털화가 개념검증에서 실거래로 넘어가는 단계로, 무역금융 은행권의 eBL 수용 확대를 이끌 것으로 보인다.","eImp":"Container-line documentation digitalisation is moving from proof-of-concept to live transactions, which should widen trade-finance bank acceptance of eBLs.","url":"https://container-news.com/dcsa-standards-based-interoperable-ebl-transaction/"},{"code":"SYS","title":"WaveBL, SWIFT·글로벌 은행·MSC와 네트워크 연결 검증 완료","src":"Container News","date":"2026-05-06","kSum":"블록체인 기반 eBL 플랫폼 WaveBL이 SWIFT 및 복수의 글로벌 은행, eBL 발행사 MSC와 함께 네트워크 연결 개념검증(POV)을 완료했다. 은행 결제 메시징망과 eBL 플랫폼을 직접 연결해 신용장 거래에서 서류 전달 시간을 대폭 단축하는 것이 목표다.","eSum":"Blockchain-based eBL platform WaveBL has completed a network connectivity proof-of-value with Swift, several global banks and eBL issuer MSC, linking bank payment messaging rails directly to the eBL platform to sharply cut document transfer time in letter-of-credit transactions.","kImp":"eBL이 은행 결제망과 직결되면 무역금융의 최대 병목인 원본 서류 우송이 사라져, 선하증권 지연에 따른 화물인도보증(LOI) 리스크도 축소된다.","eImp":"Connecting eBLs to bank payment rails removes the original-document courier bottleneck in trade finance and shrinks LOI exposure from late bills of lading.","url":"https://container-news.com/wavebl-completes-network-connectivity-pov-with-swift-global-banks-and-ebl-issuer-msc/"},{"code":"SYS","title":"지부티 시핑·Grand Port Maritime, 업무 자동화 소프트웨어 도입","src":"Riviera Maritime Media","date":"2026-07-06","kSum":"지부티 시핑과 Grand Port Maritime이 정비 조율, 작업 일정관리 및 추적, 예비품 재고, 공급사 발주를 통합 관리하는 소프트웨어를 도입해 업무 프로세스를 자동화한다.","eSum":"Djibouti Shipping and Grand Port Maritime have deployed software to automate their processes, covering maintenance co-ordination, task scheduling and tracking, spare parts inventory and supplier ordering.","kImp":"신흥 항만·선사에서도 PMS·구매 통합 SaaS 도입이 확산되며, 소규모 선단 대상 저비용 클라우드 솔루션 시장이 열리고 있다.","eImp":"Adoption of integrated PMS/procurement SaaS is spreading to emerging-market ports and operators, opening a low-cost cloud solution market for small fleets.","url":"https://www.rivieramm.com/news-content-hub/djibouti-shipping-grand-port-maritime-deploy-software-to-automate-processes-89234"},{"code":"SYS","title":"JobMarineMan, 선원 직접 채용 생태계 구축 — AI 배승 도구 연내 출시","src":"MarineLink","date":"2026-06-18","kSum":"선원 채용 플랫폼 JobMarineMan이 중개인을 거치지 않는 직접 채용 생태계를 구축하고 있다. 다음 단계로 CV 스크리닝을 자동화하고 선주 요구조건에 맞춘 후보자 숏리스트를 제공하는 AI 기반 배승 도구를 2026년 하반기 출시할 계획이다.","eSum":"Crew recruitment platform JobMarineMan is building a direct, manning-agent-free recruitment ecosystem. Its next addition is an AI-driven crew manning tool that automates CV screening and delivers shortlists matched to shipowner-defined requirements, due later in 2026.","kImp":"약 9만명 사관 부족 상황에서 선원 채용의 탈중개화와 AI 매칭은 배승 리드타임과 수수료 구조를 동시에 바꿀 변수다.","eImp":"With a projected shortfall of nearly 90,000 officers, disintermediated hiring plus AI matching could reshape both manning lead times and agency fee structures.","url":"https://www.marinelink.com/news/jobmarineman-building-a-direct-crew-540408"},{"code":"SYS","title":"윌로그-현대글로비스, 반조립부품(CKD) 운송에 IoT 센서 도입","src":"한국해운신문(KSG)","date":"2026-07-08","kSum":"콜드체인·물류 모니터링 기업 윌로그가 현대글로비스와 협력해 반조립부품(CKD) 운송 화물에 IoT 센서를 도입한다. 컨테이너 내 온습도·충격·위치 데이터를 실시간 수집해 해상 운송 중 화물 손상 원인을 추적하고 클레임 대응력을 높이는 것이 목표다.","eSum":"Korean logistics-monitoring firm Willog is deploying IoT sensors on Hyundai Glovis CKD (completely knocked down) auto-parts shipments, collecting real-time temperature, humidity, shock and location data inside containers to trace cargo damage causes during ocean transit and strengthen claims handling.","kImp":"자동차 부품 해상운송의 화물 손상 클레임은 PCTC·컨테이너 복합운송의 고질적 분쟁 요인으로, 센서 기반 증빙은 책임 소재 규명과 보험료 협상에 직접 영향을 준다.","eImp":"Cargo damage claims on auto-parts ocean legs are a chronic dispute driver in PCTC and container multimodal moves; sensor-based evidence directly affects liability determination and insurance negotiation.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=146790"}]},{"code":"SMGR","type":"news","kTitle":"Section 21. 선박관리사","eTitle":"Section 21. Ship Managers","items":[{"code":"SMGR","title":"앵글로-이스턴, 탈탄소·선박 성능 최적화 디지털 서비스 SAPS 출시","src":"Anglo-Eastern","date":"2026-06-10","kSum":"앵글로-이스턴이 용선주와 상업 운항자를 위한 차세대 디지털 서비스 SAPS(Sustainability and Performance Services)를 출시했다. 데이터 기반 인사이트로 탈탄소 규제 대응, 선대 성능 최적화, 연료비 절감을 지원한다.","eSum":"Anglo-Eastern launched SAPS (Sustainability and Performance Services), a next-generation digital service for charterers and commercial operators. It uses data-driven insights to navigate decarbonisation rules, optimise fleet performance and cut fuel costs.","kImp":"선박관리사가 단순 기술관리를 넘어 상업·환경 데이터 서비스로 사업영역을 확장하는 흐름을 보여준다.","eImp":"Shows ship managers expanding beyond technical management into commercial and environmental data services.","url":"https://www.angloeastern.com/news-and-insights/anglo-eastern-launches-saps-next-generation-digital-service-to-tackle-decarbonisation-optimise-fleet-performance-and-cut-fuel-costs/"},{"code":"SMGR","title":"앵글로-이스턴, 싱가포르에 새 협업형 사무공간 개소","src":"Anglo-Eastern","date":"2026-05-28","kSum":"앵글로-이스턴이 싱가포르에 협업 중심으로 설계된 새 사무공간을 열었다. 아시아 허브 기능과 육상 인력 확충을 뒷받침하는 투자다.","eSum":"Anglo-Eastern opened a new, collaboration-focused workplace in Singapore. The investment underpins its Asian hub function and shore-staff expansion.","kImp":"선박관리 빅3의 싱가포르 거점 강화는 아시아 선주 대상 수주 경쟁 심화를 시사한다.","eImp":"A stronger Singapore base signals intensifying competition for Asian owners' management mandates.","url":"https://www.angloeastern.com/news-and-insights/anglo-eastern-opens-doors-to-new-collaborative-workplace-in-singapore/"},{"code":"SMGR","title":"윈드캣, 첫 Elevation 시리즈 CSOV 관리를 앵글로-이스턴에 위탁","src":"Anglo-Eastern","date":"2026-05-15","kSum":"윈드캣(Windcat)이 자사 최초의 Elevation 시리즈 CSOV(해상풍력 작업지원선) 관리를 앵글로-이스턴에 맡겼다. 앵글로-이스턴의 해상풍력 오프쇼어 부문 확장 사례다.","eSum":"Windcat entrusted Anglo-Eastern with managing its first Elevation Series CSOV. The award extends Anglo-Eastern's footprint in offshore wind support vessels.","kImp":"전통 상선 관리사가 오프쇼어 풍력 지원선으로 포트폴리오를 넓히는 성장 경로를 보여준다.","eImp":"Illustrates how traditional ship managers are broadening into offshore wind support tonnage.","url":"https://www.angloeastern.com/news-and-insights/anglo-eastern-to-manage-windcat-first-elevation-series-csov/"},{"code":"SMGR","title":"V., 인터내셔널 시웨이즈 LNG 레디 이중연료 신조 탱커 6척 전관리 계약 수주","src":"V.Group","date":"2026-06-18","kSum":"V.(V.Group)가 인터내셔널 시웨이즈로부터 LNG 레디 이중연료 신조 탱커 6척의 풀 매니지먼트 계약을 확보했다. 기술·선원·운항 전반을 맡는다.","eSum":"V. secured a full management contract with International Seaways for six dual-fuel (LNG) ready newbuild tankers, covering technical, crewing and operational scope.","kImp":"이중연료 신조선 관리 수주는 대체연료 역량이 관리사 선택의 핵심 기준이 됐음을 보여준다.","eImp":"Winning dual-fuel newbuild mandates shows alternative-fuel capability is now decisive in manager selection.","url":"https://vgrouplimited.com/v-secures-full-management-contract-with-international-seaways-for-six-dual-fuel-lng-ready-newbuild-tankers/"},{"code":"SMGR","title":"V., 실크 씨로드 마리타임과 선대 8척 관리 파트너십 체결","src":"IndexBox","date":"2026-06-05","kSum":"V.가 그리스 선주 실크 씨로드 마리타임(Silk Searoad Maritime)과 손잡고 선대 8척의 장기 관리·성능을 그리스 사무소에서 총괄한다. 예방정비 계획과 선대 프로세스 표준화를 지원한다.","eSum":"V. partnered with Greek owner Silk Searoad Maritime to oversee long-term management and performance of eight vessels from its Greece office, including proactive maintenance planning and process standardisation.","kImp":"그리스 선주의 3자 관리 아웃소싱 확대는 V.의 유럽 선대 성장 동력이다.","eImp":"Greek owners outsourcing to third-party managers is a key growth driver for V. in Europe.","url":"https://www.indexbox.io/blog/v-partners-with-silk-searoad-for-fleet-management-of-8-vessels/"},{"code":"SMGR","title":"V., 라스카리디스 마리타임과 선박관리 계약 — LR2 탱커 Lucknam 기술관리","src":"Cyprus Shipping News","date":"2026-03-25","kSum":"V.가 라스카리디스 마리타임의 신규 LR2 탱커 Lucknam에 대한 풀 테크니컬 매니지먼트 제공사로 선정됐다. 양쯔장조선 명명식과 함께 파트너십이 공식 출범했다.","eSum":"V. was chosen by Laskaridis Maritime to provide full technical management for its new LR2 tanker Lucknam, with the partnership inaugurated at the Yangzijiang naming ceremony.","kImp":"신규 그리스 대형 선주와의 관계 개설로 향후 선대 확대 여지가 크다.","eImp":"Opening a relationship with a major Greek owner creates room for further fleet growth.","url":"https://cyprusshippingnews.com/2026/03/25/v-signs-ship-management-agreement-with-laskaridis-maritime/"},{"code":"SMGR","title":"컬럼비아 그룹, ZSFL 아프라막스 신조 3척 관리 수임","src":"Cyprus Shipping News","date":"2026-05-20","kSum":"컬럼비아 그룹이 저장성항만금융리스(ZSFL)로부터 아프라막스 신조 탱커 3척의 관리 지명서를 받았다. CSM 싱가포르가 선원·기술·컴플라이언스·성능 전반을 담당한다.","eSum":"Columbia Group received an appointment letter from Zhejiang Seaport Financial Leasing (ZSFL) to manage three newbuild Aframax tankers, with CSM Singapore handling crewing, technical, compliance and performance.","kImp":"중국 리스사의 국제 관리사 활용 확대는 관리사에게 새로운 대형 수요처다.","eImp":"Chinese leasing houses turning to international managers is a major new demand pool.","url":"https://cyprusshippingnews.com/2026/05/20/columbia-group-takes-on-management-of-three-aframax-newbuildings-following-appointment-letter-with-zsfl-marking-next-step-in-strategic-collaboration/"},{"code":"SMGR","title":"컬럼비아 십매니지먼트, 전 선대에 Oceanly 소프트웨어 도입","src":"Riviera Maritime Media","date":"2026-06-02","kSum":"컬럼비아 십매니지먼트가 Oceanly 성능·데이터 소프트웨어를 관리 선대 전반에 롤아웃한다. 선상 데이터 수집과 육상 분석을 표준화한다.","eSum":"Columbia Shipmanagement is rolling out Oceanly software across its managed fleet, standardising onboard data capture and shore-side analytics.","kImp":"대형 관리사의 전사 디지털 표준화는 벤치마킹 대상이 된다.","eImp":"Fleet-wide digital standardisation by a major manager sets a benchmark for peers.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/columbia-shipmanagement-to-roll-out-oceanly-software-across-fleet-76684"},{"code":"SMGR","title":"BSM, 엘레나 판타지두 신임 최고인사책임자(CPO) 선임","src":"Bernhard Schulte Shipmanagement","date":"2026-06-01","kSum":"BSM이 엘레나 판타지두(Elena Pantazidou)를 2026년 6월 1일자 최고인사책임자로 선임했다. 인사·지속가능성·커뮤니케이션에 더해 그룹 HR 마린까지 총괄하며 육·해상 인력을 단일 리더십으로 통합한다.","eSum":"BSM appointed Elena Pantazidou as Chief People Officer effective 1 June 2026. She oversees people, sustainability and communications plus Group HR Marine, unifying shore and seagoing workforce leadership.","kImp":"육·해상 인사 통합은 선원 유지율과 경력경로 관리의 구조적 개선 신호다.","eImp":"Merging shore and sea HR signals a structural push on retention and career pathways.","url":"https://www.bs-shipmanagement.com/media-centre/article/481/leadership-changes-across-bsms-people-functions/"},{"code":"SMGR","title":"윌헬름센 십매니지먼트-MPC 캐피탈, 선박 IT 합작사 Waterway IT 설립","src":"Smart Maritime Network","date":"2026-04-01","kSum":"윌헬름센 십매니지먼트와 MPC 캐피탈이 선박 IT 역량을 합쳐 글로벌 해사 기술 합작사 Waterway IT를 출범했다. 출범 시점 약 70개 고객사 400척을 45명의 IT 인력이 지원하며 함부르크·오슬로·쿠알라룸푸르·마닐라·방갈로르 거점에서 24/7 운영한다.","eSum":"Wilhelmsen Ship Management and MPC Capital combined vessel IT expertise to launch Waterway IT, serving about 400 vessels across some 70 customers with 45 IT professionals from Hamburg, Oslo, Kuala Lumpur, Manila and Bangalore with 24/7 support.","kImp":"선상 IT·사이버보안 아웃소싱 시장이 독립 사업으로 성숙하고 있음을 보여준다.","eImp":"Shows onboard IT and cyber outsourcing maturing into a standalone business line.","url":"https://smartmaritimenetwork.com/2026/04/01/wilhelmsen-ship-management-and-mpc-capital-launch-vessel-it-joint-venture/"},{"code":"SMGR","title":"시너지 마린, 인도 SCILAL과 해기 역량개발·교육 MoU 체결","src":"SAFETY4SEA","date":"2026-06-12","kSum":"인도해운공사 자회사 SCILAL과 시너지 마린이 해기 역량개발·교육·지식교류 협력 MoU를 체결했다. 인도 국가해양일에 서명됐으며 단계적 협력으로 교육 프레임워크를 강화한다.","eSum":"India's SCILAL and Synergy Marine signed an MoU on maritime capability development, training and knowledge exchange, signed on National Maritime Day with a phased collaboration to strengthen training frameworks.","kImp":"인도 선원 인력풀 확대 경쟁에서 국영 파트너십은 강력한 채용 파이프라인이 된다.","eImp":"State-linked partnerships create a powerful recruitment pipeline in the race for Indian seafarers.","url":"https://safety4sea.com/indias-scilal-and-synergy-marine-sign-to-advance-maritime-training/"},{"code":"SMGR","title":"플릿 매니지먼트, ESG 해운상 소셜 리더 3년 연속 수상","src":"Fleet Management Limited","date":"2026-06-20","kSum":"플릿 매니지먼트가 아테네에서 열린 ESG Shipping Awards에서 소셜 리더 부문 금상을 3년 연속 수상했다. 전 세계 27,000명 이상의 선원과 가족을 위한 복지·경력개발·가족 지원 실적이 평가됐다.","eSum":"Fleet Management won Gold in the Social Leader category at the ESG Shipping Awards in Athens for a third consecutive year, recognising welfare, career development and family care for over 27,000 seafarers.","kImp":"선원 복지 성과가 계량 지표로 평가받으며 관리사 경쟁력의 핵심으로 자리잡았다.","eImp":"Seafarer welfare is now measured and rewarded as a core competitive differentiator for managers.","url":"https://www.fleetship.com/news/fleet-management-awarded-social-leader-honour-at-esg-shipping-awards-for-third-consecutive-year"},{"code":"SMGR","title":"플릿 매니지먼트, 인도 코치에 신규 사무소 개소","src":"Fleet Management Limited","date":"2026-05-22","kSum":"플릿 매니지먼트가 남인도 핵심 해운 거점인 코치(Kochi)에 신규 사무소를 열었다. 선원 지원 체계를 강화하고 현지 인력 접근성을 높이는 조치다.","eSum":"Fleet Management opened a new office in Kochi, strengthening seafarer support and reinforcing its presence in a key maritime hub in southern India.","kImp":"선원 송출 거점 밀착은 채용·유지율 경쟁에서 실질적 우위를 준다.","eImp":"Proximity to seafarer-supply hubs translates into real advantage in recruitment and retention.","url":"https://www.fleetship.com/news/fleet-management-strengthens-seafarer-support-with-new-kochi-office"},{"code":"SMGR","title":"트랜스월드 그룹-플릿 매니지먼트, 신규 선박관리 합작사 설립","src":"Fleet Management Limited","date":"2026-05-08","kSum":"트랜스월드 그룹과 플릿 매니지먼트가 신규 선박관리 합작법인 설립을 발표했다. 양사의 기술관리·선원관리 역량을 결합한다.","eSum":"Transworld Group and Fleet Management announced a new ship management joint venture, combining technical and crew management capabilities.","kImp":"관리사 간 JV 확산은 규모의 경제와 지역 선주 접근성을 동시에 노리는 전략이다.","eImp":"JV formation among managers pursues both scale economies and access to regional owners.","url":"https://www.fleetship.com/news/transworld-group-and-fleet-management-announce-new-ship-management-joint-venture"},{"code":"SMGR","title":"플릿 매니지먼트, 장먼난양조선과 협력 100척 인도·수주 돌파","src":"Fleet Management Limited","date":"2026-06-25","kSum":"플릿 매니지먼트가 중국 장먼난양조선(JNS)과의 장기 파트너십에서 인도·수주 합산 100척 돌파 이정표를 달성했다. 신조 감독·기술자문 협력의 성과다.","eSum":"Fleet Management marked a milestone in its long-standing partnership with Jiangmen Nanyang Ship Engineering (JNS), surpassing 100 vessels delivered and on order together.","kImp":"신조 감독 역량은 관리 선대 유입의 선행 지표로 작동한다.","eImp":"Newbuilding supervision capability acts as a leading indicator of future managed-fleet intake.","url":"https://www.fleetship.com/news/fleet-management-limited-and-jiangmen-nanyang-ship-engineering-co-partner-to-deliver-100-vessels"},{"code":"SMGR","title":"OSM 톰, 차세대 초대형 케이블 부설선 프로젝트 관리 서비스 착수","src":"OSM Thome","date":"2026-05-30","kSum":"OSM 톰이 차세대 초대형 케이블 부설선에 대한 프로젝트 관리 서비스를 시작했다. 터키 얄로바 테르산 조선소에서 도면 승인 단계와 현장 건조 감독을 모두 담당한다.","eSum":"OSM Thome launched project management services for a next-generation ultra-large cable-laying vessel, taking responsibility for both drawing approval and on-site construction supervision at Tersan Shipyard in Yalova, Turkey.","kImp":"고부가 특수선 신조 감독은 관리사 수익 믹스를 개선하는 성장 영역이다.","eImp":"High-value specialised newbuild supervision is a growth area improving managers' revenue mix.","url":"https://osmthome.com/osm-thome-launches-project-management-services-for-next-generation-cable-laying-vessel/"},{"code":"SMGR","title":"OSM 톰 1분기 2026 뉴스레터 — 신조 프로젝트·선대 인수 잇단 진전","src":"OSM Thome","date":"2026-04-30","kSum":"OSM 톰 1분기 2026 뉴스레터에 따르면 노르윈드 ECV 기공, VARD 3 32 SOV 1번선 기공, 윈드워드 프로젝트선 진수 등 신조 프로젝트가 잇달아 진전됐다. 벌크선 Eternity Diva 등 신규 선박도 관리 선대에 편입됐다.","eSum":"OSM Thome's Q1 2026 newsletter reports progress across newbuild projects — the Norwind ECV keel laying, the first of five VARD 3 32 SOVs, and the Windward project vessel launch — plus new fleet intake including bulker Eternity Diva.","kImp":"오프쇼어 풍력 SOV 선대 확보는 OSM 톰의 세그먼트 다변화를 뒷받침한다.","eImp":"Securing offshore wind SOV tonnage underpins OSM Thome's segment diversification.","url":"https://osmthome.com/osm-thome-newsletter-q1-2026/"},{"code":"SMGR","title":"노던 마린, 신규 LNG 선대 글로벌 서비스 투입 — LNG 관리 15년","src":"Northern Marine Group","date":"2026-06-16","kSum":"노던 마린 매니지먼트가 신규 LNG 선대를 글로벌 서비스에 투입했다. 2026년으로 LNG 선박관리 15주년을 맞았으며, H-Line Shipping 다중선 프로젝트 마지막 선박 HL Puffin도 성공적으로 인도됐다.","eSum":"Northern Marine's new LNG fleet entered global service as the company marks 15 years of LNG ship management, with the final H-Line Shipping newbuild LNG carrier HL Puffin successfully delivered.","kImp":"LNG 선대 확대는 고급 해기인력 수요와 경력경로 확대를 동반한다.","eImp":"LNG fleet growth drives demand for high-end officers and widens career pathways.","url":"https://www.nmg-stena.com/new-lng-fleet-enters-global-service-under-northern-marine/"},{"code":"SMGR","title":"노던 마린, 가스선대 확대로 해기사 경력 기회 확대","src":"Northern Marine Management","date":"2026-05-20","kSum":"노던 마린이 가스 선대 확대에 따라 해기사 채용·경력 기회를 넓힌다고 밝혔다. 오일·LPG·LNG 간 사내 크로스오버 교육 프로그램으로 선종 전환과 자격 확대를 지원한다.","eSum":"Northern Marine says its gas fleet expansion is opening career opportunities for officers, supported by in-house oil, LPG and LNG crossover training programmes enabling vessel-type transitions and added qualifications.","kImp":"크로스오버 교육은 가스선 해기사 부족 국면에서 내부 인력 전환 해법으로 주목된다.","eImp":"Crossover training is a notable in-house answer to the shortage of gas-qualified officers.","url":"https://www.nmms.co.uk/news/gas-fleet-expansion-offers-career-opportunities/"}]}]};